const TIENGANH6_EXAMS = [

/* ═══════════ ĐỀ 1 — MY NEW SCHOOL ═══════════ */
{
  id: 10701, title: 'Đề 1 · My new school — present simple, school things', time: 60,
  questions: [
    { sec: 'Phát âm', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently from the others: st<u>u</u>dy — st<u>u</u>dent — l<u>u</u>nch — s<u>u</u>bject', opts: o4('study', 'student', 'lunch', 'subject'), ans: 'B', why: 'Chữ "u" trong <i>student</i> đọc là /juː/, còn <i>study, lunch, subject</i> đều đọc /ʌ/.' },
    { sec: 'Phát âm', lvl: 'TH', name: 'Câu 2', pts: 1, text: 'Choose the word whose final <b>-s</b> is pronounced differently from the others.', opts: o4('clubs', 'friends', 'teachers', 'parents'), ans: 'D', why: 'Đuôi -s trong <i>parents</i> đọc /s/ vì đứng sau âm vô thanh /t/. Ba từ còn lại kết thúc bằng âm hữu thanh /b/, /d/, /ə/ nên -s đọc /z/.' },
    { sec: 'Trọng âm', lvl: 'NB', name: 'Câu 3', pts: 1, text: 'Choose the word that has a different stress pattern from the others.', opts: o4('between', 'lesson', 'pupil', 'homework'), ans: 'A', why: '<i>Between</i> trọng âm rơi vào âm tiết thứ hai (be-TWEEN); <i>lesson, pupil, homework</i> đều nhấn âm tiết thứ nhất.' },
    { sec: 'Present simple', lvl: 'NC', name: 'Câu 4', pts: 1, text: 'Nam and his brother ___ school uniform on Mondays, but Nam ___ his uniform on the other days.', opts: o4('wears – doesn\'t wear', 'wear – don\'t wear', 'wear – doesn\'t wear', 'wears – don\'t wear'), ans: 'C', why: 'Chủ ngữ đầu là "Nam and his brother" (số nhiều) → <i>wear</i>. Chủ ngữ sau là "Nam" (ngôi thứ ba số ít) → <i>doesn\'t wear</i>. Phải chia riêng cho từng vế chứ không chia giống nhau.' },
    { sec: 'Trạng từ tần suất', lvl: 'TH', name: 'Câu 5', pts: 1, text: 'Which sentence is correct?', opts: o4('She goes often to the library.', 'She often goes to the library.', 'She goes to the library often not.', 'Often she go to the library.'), ans: 'B', why: 'Trạng từ tần suất (<i>often</i>) đứng TRƯỚC động từ thường. Câu A đặt sai vị trí, câu C sai cấu trúc phủ định, câu D chia sai động từ.' },
    { sec: 'Từ vựng trường học', lvl: 'NB', name: 'Câu 6', pts: 1, text: 'In the ___, students borrow and read books.', opts: o4('library', 'laboratory', 'playground', 'canteen'), ans: 'A', why: '<i>Library</i> = thư viện, nơi mượn và đọc sách. <i>Laboratory</i> = phòng thí nghiệm, <i>playground</i> = sân chơi, <i>canteen</i> = căng tin.' },
    { sec: 'Giới từ', lvl: 'NC', name: 'Câu 7', pts: 1, text: 'My new school is different ___ my old school; here we study Science ___ a modern lab.', opts: o4('to – on', 'with – at', 'from – on', 'from – in'), ans: 'D', why: 'Cụm cố định <i>different from</i> (khác với). Với phòng thí nghiệm ta nói <i>in a lab</i> (ở bên trong phòng). "different with" và "on a lab" đều sai.' },
    { sec: 'Từ loại', lvl: 'TH', name: 'Câu 8', pts: 1, text: 'Choose the word that does NOT belong to the group.', opts: o4('Maths', 'History', 'uniform', 'Geography'), ans: 'C', why: '<i>Maths, History, Geography</i> đều là môn học; <i>uniform</i> là đồng phục, không phải môn học.' },
    { sec: 'There is / There are', lvl: 'NB', name: 'Câu 9', pts: 1, text: 'There ___ thirty students in my class.', opts: o4('are', 'is', 'be', 'am'), ans: 'A', why: '"Thirty students" là danh từ số nhiều nên dùng <i>There are</i>.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 10', pts: 1, text: 'Mai has five lessons on Monday morning. Each lesson lasts 45 minutes and there is a 5-minute break after each lesson except the last one. Her first lesson starts at 7.00. What time does her fifth lesson finish?', opts: o4('10.45', '11.05', '11.00', '10.55'), ans: 'B', why: 'Thời gian học: 5 × 45 = 225 phút. Giờ ra chơi: 4 lần × 5 = 20 phút. Tổng 245 phút = 4 giờ 5 phút. 7.00 + 4 giờ 5 phút = <b>11.05</b>. (Chọn 10.45 là quên cộng giờ ra chơi.)' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 11', pts: 1, text: 'Choose the underlined part that needs correction: <u>Every</u> day we <u>have</u> four <u>lesson</u> in the <u>morning</u>.', opts: o4('Every', 'have', 'lesson', 'morning'), ans: 'C', why: 'Sau số đếm "four" phải dùng danh từ số nhiều: <i>four lessons</i>. Ba phần còn lại đều đúng ("every day", "we have", "in the morning").' },
    { sec: 'Từ vựng trường học', lvl: 'NB', name: 'Câu 12', pts: 1, text: 'Which word means "a room where students do experiments"?', opts: o4('canteen', 'gym', 'library', 'laboratory'), ans: 'D', why: '<i>Laboratory</i> (lab) là phòng thí nghiệm — nơi học sinh làm thí nghiệm.' },
    { sec: 'its / it\'s', lvl: 'NC', name: 'Câu 13', pts: 1, text: 'My new school is very big. ___ playground is large, and ___ also got a modern library.', opts: o4('It\'s – its', 'Its – it\'s', 'Its – its', 'It\'s – it\'s'), ans: 'B', why: 'Chỗ trống 1 cần tính từ sở hữu "của nó" → <i>Its</i> (không có dấu phẩy trên). Chỗ trống 2 là dạng viết tắt của "it has got" → <i>it\'s</i>. Đây là cặp dễ nhầm nhất ở lớp 6.' },
    { sec: 'Giới từ thời gian', lvl: 'TH', name: 'Câu 14', pts: 1, text: 'We have Maths ___ Monday and Thursday.', opts: o4('on', 'in', 'at', 'to'), ans: 'A', why: 'Dùng <i>on</i> với thứ trong tuần; <i>in</i> dùng với tháng/năm/buổi; <i>at</i> dùng với giờ.' },
    { sec: 'Từ để hỏi', lvl: 'TH', name: 'Câu 15', pts: 1, text: '___ do you go to school? — By bus.', opts: o4('What', 'Where', 'How', 'When'), ans: 'C', why: 'Câu trả lời "By bus" nói về phương tiện nên câu hỏi phải bắt đầu bằng <i>How</i>.' },
    { sec: 'Present simple', lvl: 'NB', name: 'Câu 16', pts: 1, text: 'I ___ a new pencil case.', opts: o4('has', 'having', 'is', 'have'), ans: 'D', why: 'Chủ ngữ "I" luôn đi với <i>have</i>, không dùng <i>has</i>.' },
    { sec: 'Giao tiếp', lvl: 'NC', name: 'Câu 17', pts: 1, text: '— "I\'m afraid I can\'t join the football club this afternoon." — "___"', opts: o4('Yes, I\'d love to. Thank you.', 'That\'s a pity. See you tomorrow.', 'You\'re welcome. Don\'t mention it.', 'Not at all. It\'s my pleasure.'), ans: 'B', why: 'Người nói đang từ chối, nên phản hồi hợp lí là bày tỏ sự tiếc nuối: <i>That\'s a pity</i>. Phương án A là nhận lời, C và D là cách đáp lại lời cảm ơn.' },
    { sec: 'Present simple', lvl: 'TH', name: 'Câu 18', pts: 1, text: 'My school ___ in the city centre. It ___ a big library.', opts: o4('is – has', 'has – is', 'is – have', 'are – has'), ans: 'A', why: '"My school" là số ít → <i>is</i>; đại từ "It" ngôi thứ ba số ít → <i>has</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 19', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 19–23).</i><br>My name is Trang and I\'m in Class 6A <b>(19)___</b> Nguyen Du Secondary School. My school is small <b>(20)___</b> very beautiful. Every morning I ride my bike to school; it <b>(21)___</b> me about ten minutes. My favourite subject <b>(22)___</b> English because our teacher <b>(23)___</b> tells us funny stories.<br><br><b>Câu 19.</b>', opts: o4('in', 'to', 'at', 'on'), ans: 'C', why: 'Với tên riêng của một ngôi trường ta dùng <i>at</i>: "in Class 6A at Nguyen Du Secondary School".' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 20', pts: 1, text: '<b>Câu 20.</b> My school is small <b>(20)___</b> very beautiful.', opts: o4('and', 'but', 'so', 'because'), ans: 'B', why: '"Small" (nhỏ) và "very beautiful" (rất đẹp) là hai ý trái chiều nên phải nối bằng <i>but</i>. Chọn <i>and</i> là bỏ qua quan hệ tương phản.' },
    { sec: 'Điền từ (cloze)', lvl: 'VD', name: 'Câu 21', pts: 1, text: '<b>Câu 21.</b> Every morning I ride my bike to school; it <b>(21)___</b> me about ten minutes.', opts: o4('spends', 'lasts', 'costs', 'takes'), ans: 'D', why: 'Cấu trúc chỉ thời gian cần để làm việc gì là <i>It takes somebody + thời gian</i>. <i>Spend</i> có chủ ngữ là người, <i>cost</i> đi với tiền, <i>last</i> không có tân ngữ chỉ người.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> My favourite subject <b>(22)___</b> English.', opts: o4('is', 'are', 'be', 'am'), ans: 'A', why: '"My favourite subject" là danh từ số ít nên dùng <i>is</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> … because our teacher <b>(23)___</b> tells us funny stories.', opts: o4('never', 'hardly ever', 'often', 'rarely'), ans: 'C', why: 'Vế trước nói Trang THÍCH môn học vì cô giáo kể chuyện vui, nên tần suất phải mang nghĩa tích cực và thường xuyên: <i>often</i>. Ba phương án còn lại đều nghĩa "hiếm khi/không bao giờ", mâu thuẫn với lí do sau "because".' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 24', pts: 1, text: '<i>Read the passage and answer the questions (Câu 24–28).</i><br>Hoang is a new student at Thang Long Secondary School. It is a boarding school, so he lives there from Monday to Friday and goes home at the weekend. The school has three buildings: one for classrooms, one for the dormitory, and one for the library and the computer room. Lessons start at 7.15 and finish at 11.30 in the morning. In the afternoon, students join clubs. Hoang is a member of the chess club and he plays chess every Wednesday and Friday. He misses his parents, but he has many new friends.<br><br><b>Câu 24.</b> Where does Hoang live from Monday to Friday?', opts: o4('At his parents\' house.', 'In the library building.', 'In the classroom building.', 'At his school.'), ans: 'D', why: 'Bài đọc nói "It is a boarding school, so he lives there from Monday to Friday" — <i>there</i> chỉ ngôi trường.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> How many days a week does Hoang play chess?', opts: o4('Two.', 'Three.', 'Five.', 'One.'), ans: 'A', why: 'Hoang chơi cờ "every Wednesday and Friday" — hai ngày mỗi tuần.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 26', pts: 1, text: '<b>Câu 26.</b> Which statement is NOT true about Thang Long Secondary School?', opts: o4('It has a computer room.', 'Its students go home every evening.', 'It has a dormitory for students.', 'Its morning lessons end at 11.30.'), ans: 'B', why: 'Đây là trường nội trú: học sinh ở lại từ thứ Hai đến thứ Sáu và chỉ về nhà cuối tuần, nên câu B sai. Ba câu còn lại đều có trong bài.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> The word "dormitory" in the passage means ___.', opts: o4('a room where students cook meals', 'a hall where students play sports', 'a room where students borrow books', 'a room where students sleep at night'), ans: 'D', why: '<i>Dormitory</i> = kí túc xá, nơi học sinh nội trú ngủ. Bài đọc tách riêng toà nhà thư viện nên C không đúng.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> Which idea can be inferred from the passage?', opts: o4('Hoang does not like his new school at all.', 'Hoang\'s classroom is in the dormitory building.', 'Hoang sees his parents only at the weekend.', 'Hoang is the best chess player in his club.'), ans: 'C', why: 'Vì em ở nội trú từ thứ Hai đến thứ Sáu và chỉ "goes home at the weekend" nên chỉ gặp bố mẹ vào cuối tuần. A trái với câu cuối ("he has many new friends"), B sai vì lớp học ở toà nhà khác, D không hề được nhắc tới.' },
    { sec: 'Trật tự từ', lvl: 'TH', name: 'Câu 29', pts: 1, text: 'Rearrange the words to make a correct question: often / how / you / do / go / to / the library ?', opts: o4('How often do you go to the library?', 'How often you do go to the library?', 'How do you often go to the library?', 'How often go you to the library?'), ans: 'A', why: 'Câu hỏi với "How often" giữ trật tự: <i>How often + do/does + chủ ngữ + động từ nguyên thể</i>. Không tách "often" khỏi "how", cũng không đảo động từ chính lên trước chủ ngữ.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 30', pts: 1, text: 'Look at the timetable of Class 6A. <b>Monday:</b> Maths, English, IT, Music. <b>Tuesday:</b> Literature, Maths, English, PE. <b>Wednesday:</b> Maths, History, English, Art. How many English lessons does Class 6A have in these three days?', opts: o4('Two.', 'Three.', 'Four.', 'Five.'), ans: 'B', why: 'English xuất hiện đúng một lần ở mỗi ngày trong ba ngày → <b>3</b> tiết. (Maths cũng có 3 tiết, nhưng câu hỏi hỏi về English.)' },
  ],
},

/* ═══════════ ĐỀ 2 — MY HOUSE ═══════════ */
{
  id: 10702, title: 'Đề 2 · My house — there is/are, prepositions of place', time: 60,
  questions: [
    { sec: 'Phát âm', lvl: 'TH', name: 'Câu 1', pts: 1, text: 'Choose the word whose final <b>-s/-es</b> is pronounced differently from the others.', opts: o4('houses', 'boxes', 'rooms', 'dishes'), ans: 'C', why: 'Đuôi -s trong <i>rooms</i> đọc /z/. Ba từ còn lại kết thúc bằng âm gió /s/, /ks/, /ʃ/ nên -es đọc /ɪz/.' },
    { sec: 'Phát âm', lvl: 'NB', name: 'Câu 2', pts: 1, text: 'Choose the word that does NOT contain the sound /aʊ/.', opts: o4('sofa', 'house', 'mouse', 'flower'), ans: 'A', why: '<i>Sofa</i> /ˈsəʊfə/ chứa /əʊ/, không phải /aʊ/. <i>House, mouse, flower</i> đều có /aʊ/.' },
    { sec: 'Trọng âm', lvl: 'NC', name: 'Câu 3', pts: 1, text: 'Choose the word that has a different stress pattern from the others.', opts: o4('bedroom', 'kitchen', 'sofa', 'apartment'), ans: 'D', why: '<i>Apartment</i> nhấn âm tiết thứ hai (a-PART-ment); ba từ còn lại đều nhấn âm tiết thứ nhất. Lưu ý <i>bedroom</i> là danh từ ghép nên vẫn nhấn phần đầu.' },
    { sec: 'There is / There are', lvl: 'NB', name: 'Câu 4', pts: 1, text: 'There ___ a television in the living room.', opts: o4('are', 'is', 'be', 'have'), ans: 'B', why: '"A television" là danh từ số ít nên dùng <i>There is</i>.' },
    { sec: 'There is / There are', lvl: 'TH', name: 'Câu 5', pts: 1, text: 'There ___ four chairs and a table in the kitchen.', opts: o4('is', 'be', 'are', 'has'), ans: 'C', why: 'Danh từ đứng ngay sau là "four chairs" (số nhiều) nên dùng <i>There are</i>.' },
    { sec: 'There is / There are', lvl: 'NC', name: 'Câu 6', pts: 1, text: '___ any pictures on the wall? — Yes, there are two.', opts: o4('Is there', 'Are they', 'Is it', 'Are there'), ans: 'D', why: 'Câu trả lời "there are two" cho biết đây là câu hỏi với <i>There are</i>, và danh từ "pictures" ở số nhiều → <i>Are there</i>. Chọn "Are they" là nhầm cấu trúc "there be" với đại từ "they".' },
    { sec: 'Giới từ chỉ nơi chốn', lvl: 'NB', name: 'Câu 7', pts: 1, text: 'We keep the milk ___ the fridge.', opts: o4('in', 'on', 'under', 'behind'), ans: 'A', why: 'Sữa để BÊN TRONG tủ lạnh nên dùng <i>in</i>.' },
    { sec: 'Giới từ chỉ nơi chốn', lvl: 'TH', name: 'Câu 8', pts: 1, text: 'The sofa is ___ the two armchairs.', opts: o4('among', 'between', 'next', 'beside of'), ans: 'B', why: '<i>Between</i> dùng khi ở giữa HAI vật; <i>among</i> dùng khi ở giữa nhiều vật. "next" phải là "next to", còn "beside of" không tồn tại.' },
    { sec: 'Giới từ chỉ nơi chốn', lvl: 'NC', name: 'Câu 9', pts: 1, text: 'Look at the plan of a flat: the bathroom is next to the kitchen, and the kitchen is between the bathroom and the living room. Which room lies in the middle of the three?', opts: o4('The bathroom.', 'The bedroom.', 'The living room.', 'The kitchen.'), ans: 'D', why: 'Câu thứ hai nói rõ "the kitchen is between the bathroom and the living room" → bếp nằm giữa. Thứ tự ba phòng là: bathroom – kitchen – living room.' },
    { sec: 'Từ vựng nhà ở', lvl: 'NB', name: 'Câu 10', pts: 1, text: 'Where do people usually cook?', opts: o4('In the bedroom.', 'In the bathroom.', 'In the kitchen.', 'In the living room.'), ans: 'C', why: '<i>Kitchen</i> = nhà bếp, nơi nấu ăn.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 11', pts: 1, text: 'In Mai\'s building the ground floor is counted as floor 0. Mai lives on the third floor. There are 18 steps between two floors. How many steps does Mai walk up from the ground floor to her flat?', opts: o4('54', '36', '72', '48'), ans: 'A', why: 'Từ tầng 0 lên tầng 3 phải đi qua 3 nhịp cầu thang: 3 × 18 = <b>54</b> bậc. (Chọn 72 là nhầm thành 4 nhịp, chọn 36 là chỉ tính 2 nhịp.)' },
    { sec: 'Sở hữu cách', lvl: 'TH', name: 'Câu 12', pts: 1, text: 'That is ___ room. They share it.', opts: o4('the twins', 'the twins\'', 'the twin\'s', 'twins'), ans: 'B', why: 'Chủ sở hữu là "the twins" (số nhiều, đã có sẵn -s) nên chỉ thêm dấu phẩy trên: <i>the twins\'</i>. Câu "They share it" xác nhận có hai người.' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 13', pts: 1, text: 'Choose the underlined part that needs correction: <u>There is</u> four chairs <u>around</u> the table <u>in</u> the <u>kitchen</u>.', opts: o4('There is', 'around', 'in', 'kitchen'), ans: 'A', why: 'Danh từ theo sau là "four chairs" (số nhiều) nên phải sửa thành <i>There are</i>. Các phần còn lại đều dùng đúng.' },
    { sec: 'Từ vựng nhà ở', lvl: 'NB', name: 'Câu 14', pts: 1, text: 'Which word does NOT name a room?', opts: o4('kitchen', 'bathroom', 'bedroom', 'wardrobe'), ans: 'D', why: '<i>Wardrobe</i> là cái tủ quần áo — một món đồ đạc, không phải một căn phòng.' },
    { sec: 'Giới từ chỉ nơi chốn', lvl: 'TH', name: 'Câu 15', pts: 1, text: 'My house is ___ the supermarket and the post office.', opts: o4('next to', 'opposite', 'between', 'behind'), ans: 'C', why: 'Có hai địa điểm nối bằng "and" nên dùng <i>between … and …</i>. Ba giới từ còn lại chỉ đi với một địa điểm.' },
    { sec: 'Danh từ không đếm được', lvl: 'NC', name: 'Câu 16', pts: 1, text: 'Choose the sentence that has the closest meaning to: "There isn\'t any furniture in this room."', opts: o4('This room has some furniture.', 'This room has no furniture.', 'This room hasn\'t got any furnitures.', 'There aren\'t any furniture in this room.'), ans: 'B', why: '"isn\'t any" đồng nghĩa với "no". <i>Furniture</i> là danh từ không đếm được nên không thêm -s (loại C) và luôn đi với động từ số ít (loại D). Phương án A trái nghĩa.' },
    { sec: 'Câu hỏi How many', lvl: 'NC', name: 'Câu 17', pts: 1, text: '— "How many floors ___ your house ___ ?" — "Three."', opts: o4('do – has', 'does – has', 'do – have', 'does – have'), ans: 'D', why: 'Chủ ngữ "your house" là ngôi thứ ba số ít nên trợ động từ là <i>does</i>; sau trợ động từ, động từ chính trở về nguyên thể <i>have</i>. Lỗi hay gặp là chia -s hai lần ("does – has").' },
    { sec: 'Từ vựng nhà ở', lvl: 'NB', name: 'Câu 18', pts: 1, text: 'We take a shower in the ___.', opts: o4('bathroom', 'kitchen', 'garage', 'hall'), ans: 'A', why: '<i>Bathroom</i> = phòng tắm.' },
    { sec: 'Từ để hỏi', lvl: 'TH', name: 'Câu 19', pts: 1, text: '___ is your house? — It\'s in Le Loi Street.', opts: o4('What', 'Where', 'How', 'Which'), ans: 'B', why: 'Câu trả lời chỉ nơi chốn ("in Le Loi Street") nên hỏi bằng <i>Where</i>.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 20', pts: 1, text: 'A small flat costs 6 million dong a month. Three students share it and pay equally. How much does each of them pay in two months?', opts: o4('2 million dong', '3 million dong', '4 million dong', '12 million dong'), ans: 'C', why: 'Mỗi tháng mỗi bạn trả 6 : 3 = 2 triệu đồng; trong hai tháng là 2 × 2 = <b>4 triệu đồng</b>. (Chọn 2 triệu là quên nhân với hai tháng.)' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>I live in a town house <b>(21)___</b> Hai Phong. It has three floors and a small garden <b>(22)___</b> front of the house. My favourite room is the living room <b>(23)___</b> it is bright and airy. There is a big sofa and a television in it, and there <b>(24)___</b> many green plants near the window. In the evening my father often <b>(25)___</b> television in this room.<br><br><b>Câu 21.</b>', opts: o4('in', 'on', 'at', 'to'), ans: 'A', why: 'Với tên thành phố ta dùng giới từ <i>in</i>: "in Hai Phong".' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> … a small garden <b>(22)___</b> front of the house.', opts: o4('on', 'at', 'to', 'in'), ans: 'D', why: 'Cụm giới từ cố định là <i>in front of</i> (ở phía trước). Đây là cụm ba từ, không thay "in" bằng "at" hay "on" được.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> My favourite room is the living room <b>(23)___</b> it is bright and airy.', opts: o4('so', 'because', 'but', 'and'), ans: 'B', why: 'Vế sau nêu LÍ DO vì sao đó là phòng em thích nhất nên dùng <i>because</i>. Dùng <i>so</i> sẽ đảo ngược quan hệ nhân – quả.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> … and there <b>(24)___</b> many green plants near the window.', opts: o4('is', 'has', 'are', 'have'), ans: 'C', why: '"Many green plants" là số nhiều nên dùng <i>there are</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> In the evening my father often <b>(25)___</b> television in this room.', opts: o4('watch', 'is watching', 'watching', 'watches'), ans: 'D', why: 'Có trạng từ tần suất "often" và mốc thời gian lặp lại "in the evening" → thì hiện tại đơn; chủ ngữ "my father" số ít nên thêm -es: <i>watches</i>. Chọn "is watching" là nhầm sang hiện tại tiếp diễn.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>Linh lives in a stilt house in Hoa Binh. The house stands on tall wooden columns, so it is about two metres above the ground. There is a ladder in front of the house. Inside, there is one big room for the whole family: they eat, talk and sleep there. The kitchen is at the back of the house. Linh\'s family keeps buffaloes and chickens under the house. Linh loves her home because it is cool in summer and warm in winter.<br><br><b>Câu 26.</b> How do people get into Linh\'s house?', opts: o4('They climb a ladder.', 'They use a lift.', 'They walk through a garden.', 'They go down some steps.'), ans: 'A', why: 'Bài đọc viết "There is a ladder in front of the house" — muốn vào nhà sàn phải leo thang.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> Where is the kitchen?', opts: o4('In front of the house.', 'Under the house.', 'At the back of the house.', 'On the ground floor.'), ans: 'C', why: 'Câu "The kitchen is at the back of the house" trả lời trực tiếp.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> Which piece of information is NOT mentioned in the passage?', opts: o4('The animals kept under the house.', 'The number of bedrooms in the house.', 'The material of the columns.', 'The reason why Linh loves her house.'), ans: 'B', why: 'Bài đọc nói nhà sàn chỉ có MỘT phòng lớn dùng chung, không hề nói có bao nhiêu phòng ngủ. Trâu và gà (A), cột gỗ "wooden columns" (C) và lí do "cool in summer and warm in winter" (D) đều có trong bài.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> Linh\'s house is two metres above the ground. If each step of the ladder is 25 cm high, how many steps does the ladder have?', opts: o4('8', '4', '10', '12'), ans: 'A', why: 'Đổi 2 m = 200 cm, rồi lấy 200 : 25 = <b>8</b> bậc. (Chọn 4 là quên đổi đơn vị mà lấy 100 : 25.)' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 30', pts: 1, text: '<b>Câu 30.</b> The word "it" in the last sentence refers to ___.', opts: o4('the kitchen', 'the ladder', 'summer', 'her home'), ans: 'D', why: 'Câu cuối là "Linh loves her home because it is cool in summer…" — đại từ <i>it</i> thay cho <i>her home</i>.' },
  ],
},


/* ═══════════ ĐỀ 3 — MY FRIENDS ═══════════ */
{
  id: 10703, title: 'Đề 3 · My friends — present continuous, appearance & personality', time: 60,
  questions: [
    { sec: 'Phát âm', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently from the others: sh<u>or</u>t — sp<u>or</u>t — f<u>or</u>ty — w<u>or</u>k', opts: o4('short', 'sport', 'forty', 'work'), ans: 'D', why: 'Phần "or" trong <i>work</i> đọc là /ɜː/, còn <i>short, sport, forty</i> đều đọc /ɔː/.' },
    { sec: 'Hiện tại tiếp diễn', lvl: 'NC', name: 'Câu 2', pts: 1, text: 'Look! Nam and Mai ___ badminton in the schoolyard. They ___ it every Saturday.', opts: o4('play – are playing', 'are playing – play', 'play – play', 'are playing – are playing'), ans: 'B', why: 'Từ "Look!" báo hiệu hành động đang diễn ra → hiện tại tiếp diễn <i>are playing</i>. Cụm "every Saturday" chỉ thói quen → hiện tại đơn <i>play</i>. Mỗi vế phải dùng một thì khác nhau.' },
    { sec: 'Tính từ chỉ tính cách', lvl: 'TH', name: 'Câu 3', pts: 1, text: 'Choose the word that does NOT describe someone\'s personality.', opts: o4('kind', 'shy', 'tall', 'clever'), ans: 'C', why: '<i>Tall</i> tả ngoại hình (chiều cao), còn <i>kind, shy, clever</i> đều tả tính cách.' },
    { sec: 'Danh từ không đếm được', lvl: 'NB', name: 'Câu 4', pts: 1, text: 'My best friend has long black ___.', opts: o4('hair', 'hairs', 'a hair', 'the hairs'), ans: 'A', why: 'Khi nói về mái tóc nói chung, <i>hair</i> là danh từ không đếm được nên không thêm -s và không dùng mạo từ "a".' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 5', pts: 1, text: 'Choose the underlined part that needs correction: <u>At</u> the moment my brother <u>is</u> <u>listening</u> to music in his <u>bedrooms</u>.', opts: o4('At', 'is', 'listening', 'bedrooms'), ans: 'D', why: 'Người em chỉ có một phòng ngủ và trước đó đã có "his" nên phải dùng số ít <i>bedroom</i>. Cụm "At the moment" đi với hiện tại tiếp diễn "is listening" là hoàn toàn đúng.' },
    { sec: 'Tính từ chỉ tính cách', lvl: 'TH', name: 'Câu 6', pts: 1, text: 'Mai is very ___; she always helps her classmates with their homework.', opts: o4('lazy', 'shy', 'helpful', 'boring'), ans: 'C', why: 'Vế sau nói Mai luôn giúp bạn bè nên tính từ phù hợp là <i>helpful</i> (hay giúp đỡ). Các từ còn lại đều mang nghĩa trái ngược hoặc không liên quan.' },
    { sec: 'Hiện tại tiếp diễn', lvl: 'NB', name: 'Câu 7', pts: 1, text: 'Listen! Someone ___ at the door.', opts: o4('knock', 'is knocking', 'knocks', 'knocked'), ans: 'B', why: '"Listen!" cho biết hành động đang xảy ra ngay lúc nói nên dùng hiện tại tiếp diễn: <i>is knocking</i>.' },
    { sec: 'Phân biệt hai thì', lvl: 'NC', name: 'Câu 8', pts: 1, text: 'My cousin ___ glasses, and today he ___ a red T-shirt.', opts: o4('wears – is wearing', 'is wearing – wears', 'wears – wears', 'is wearing – is wearing'), ans: 'A', why: 'Đeo kính là đặc điểm thường xuyên → hiện tại đơn <i>wears</i>. "Today" chỉ việc đang diễn ra hôm nay, khác với thường ngày → hiện tại tiếp diễn <i>is wearing</i>.' },
    { sec: 'Câu hỏi lựa chọn', lvl: 'TH', name: 'Câu 9', pts: 1, text: '___ your sister tall or short? — She\'s quite tall.', opts: o4('Does', 'Do', 'Is', 'Are'), ans: 'C', why: 'Sau chỗ trống là tính từ "tall/short" nên cần động từ to be; chủ ngữ "your sister" số ít → <i>Is</i>.' },
    { sec: 'Tính từ chỉ tính cách', lvl: 'NB', name: 'Câu 10', pts: 1, text: 'Which adjective describes someone who does not talk much with new people?', opts: o4('funny', 'generous', 'active', 'shy'), ans: 'D', why: '<i>Shy</i> = nhút nhát, ngại nói chuyện với người lạ.' },
    { sec: 'Hiện tại tiếp diễn', lvl: 'TH', name: 'Câu 11', pts: 1, text: 'We ___ a picnic in the park at the moment.', opts: o4('have', 'are having', 'has', 'having'), ans: 'B', why: '"At the moment" đi với hiện tại tiếp diễn; chủ ngữ "We" → <i>are having</i>.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 12', pts: 1, text: 'Read the description: "Linh is 1.45 m tall. Mai is 5 cm taller than Linh. Ha is 3 cm shorter than Mai." How tall is Ha?', opts: o4('1.47 m', '1.42 m', '1.53 m', '1.50 m'), ans: 'A', why: 'Mai cao 1,45 m + 5 cm = 1,50 m. Ha thấp hơn Mai 3 cm nên cao 1,50 m − 3 cm = <b>1,47 m</b>. (Chọn 1,42 m là trừ nhầm từ chiều cao của Linh.)' },
    { sec: 'Câu đồng nghĩa', lvl: 'NC', name: 'Câu 13', pts: 1, text: 'Choose the sentence that has the closest meaning to: "My friend Nam has a good sense of humour."', opts: o4('Nam is a very shy boy.', 'Nam is very good at drawing.', 'Nam is always serious at school.', 'Nam often makes his friends laugh.'), ans: 'D', why: '<i>A good sense of humour</i> = khiếu hài hước, tức hay làm người khác cười. Phương án C nói ngược nghĩa.' },
    { sec: 'There is / There are', lvl: 'NB', name: 'Câu 14', pts: 1, text: 'There ___ two new students in my class today.', opts: o4('is', 'has', 'are', 'have'), ans: 'C', why: '"Two new students" là số nhiều nên dùng <i>There are</i>.' },
    { sec: 'Hỏi về tính cách', lvl: 'NC', name: 'Câu 15', pts: 1, text: '— "___ is your new friend like?" — "She is kind and cheerful."', opts: o4('What', 'How', 'Who', 'Which'), ans: 'A', why: 'Cấu trúc hỏi về tính cách hoặc ngoại hình là <i>What + be + S + like?</i>. Học sinh hay nhầm sang "How is she?" — câu đó hỏi về sức khỏe.' },
    { sec: 'Hỏi về ngoại hình', lvl: 'TH', name: 'Câu 16', pts: 1, text: 'Which question asks about someone\'s appearance?', opts: o4('What does she like?', 'What does she look like?', 'What is she doing?', 'How is she?'), ans: 'B', why: '<i>What does she look like?</i> hỏi về ngoại hình. Câu A hỏi sở thích, câu C hỏi hành động đang làm, câu D hỏi sức khỏe.' },
    { sec: 'Trả lời ngắn', lvl: 'NC', name: 'Câu 17', pts: 1, text: '— "Is Hung doing his homework now?" — "___ He is playing football in the yard."', opts: o4('Yes, he is.', 'Yes, he does.', 'No, he isn\'t.', 'No, he doesn\'t.'), ans: 'C', why: 'Câu sau cho biết Hùng đang đá bóng chứ không làm bài, nên phải trả lời phủ định. Câu hỏi bắt đầu bằng "Is" nên trả lời bằng <i>isn\'t</i>, không dùng "doesn\'t".' },
    { sec: 'Từ vựng ngoại hình', lvl: 'NB', name: 'Câu 18', pts: 1, text: 'Which word describes hair?', opts: o4('curly', 'quiet', 'clever', 'friendly'), ans: 'A', why: '<i>Curly</i> = xoăn, dùng để tả tóc. Ba từ còn lại tả tính cách.' },
    { sec: 'Hiện tại đơn', lvl: 'TH', name: 'Câu 19', pts: 1, text: 'My friends ___ volleyball every Sunday afternoon.', opts: o4('are playing', 'plays', 'is playing', 'play'), ans: 'D', why: '"Every Sunday afternoon" chỉ thói quen nên dùng hiện tại đơn; chủ ngữ "My friends" số nhiều nên giữ nguyên <i>play</i>.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 20', pts: 1, text: 'Read: "In Class 6B there are 36 students. One third of them join the music club and a quarter of them join the football club. The rest join the art club." How many students join the art club?', opts: o4('12', '15', '9', '21'), ans: 'B', why: 'Câu lạc bộ âm nhạc: 36 : 3 = 12 bạn. Câu lạc bộ bóng đá: 36 : 4 = 9 bạn. Còn lại 36 − 12 − 9 = <b>15</b> bạn vào câu lạc bộ mĩ thuật.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>My best friend is Trang. She is twelve years old, the same age <b>(21)___</b> me. She is quite tall and she has long straight hair. Trang is very <b>(22)___</b>: she always shares her snacks and lends me her books. Look! She <b>(23)___</b> over there, next to the big tree. She <b>(24)___</b> a white cap today. We <b>(25)___</b> to the same drawing club every Wednesday.<br><br><b>Câu 21.</b>', opts: o4('with', 'like', 'as', 'to'), ans: 'C', why: 'Cụm cố định <i>the same … as …</i> (giống như): "the same age as me".' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> Trang is very <b>(22)___</b>: she always shares her snacks and lends me her books.', opts: o4('lazy', 'shy', 'careless', 'generous'), ans: 'D', why: 'Dấu hai chấm cho biết vế sau giải thích cho tính từ: chia đồ ăn, cho mượn sách → <i>generous</i> (hào phóng). Ba tính từ còn lại đều không khớp với hành vi được mô tả.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> Look! She <b>(23)___</b> over there, next to the big tree.', opts: o4('is standing', 'stands', 'stand', 'standing'), ans: 'A', why: '"Look!" báo hiệu hành động đang diễn ra trước mắt nên dùng hiện tại tiếp diễn <i>is standing</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> She <b>(24)___</b> a white cap today.', opts: o4('wear', 'is wearing', 'wears', 'wearing'), ans: 'B', why: 'Trạng từ "today" cùng mạch với "Look!" ở câu trước, chỉ việc đang xảy ra hôm nay → hiện tại tiếp diễn <i>is wearing</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> We <b>(25)___</b> to the same drawing club every Wednesday.', opts: o4('go', 'are going', 'goes', 'going'), ans: 'A', why: '"Every Wednesday" chỉ thói quen lặp lại nên dùng hiện tại đơn; chủ ngữ "We" nên động từ giữ nguyên <i>go</i>.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>Minh is my classmate. He is short and a bit plump, with short black hair and a round face. He always wears glasses because he reads a lot. Minh is not very talkative, but he is the kindest boy in our class. When someone forgets a pen or a ruler, Minh is the first to help. He is also very good at Maths and he often explains difficult exercises to us after school. At the moment Minh is sitting in the school library. He is preparing for the Maths competition next month.<br><br><b>Câu 26.</b> Why does Minh wear glasses?', opts: o4('Because he is short.', 'Because he plays too many games.', 'Because he reads a lot.', 'Because he is good at Maths.'), ans: 'C', why: 'Bài đọc viết rõ: "He always wears glasses <b>because he reads a lot</b>." Việc giỏi Toán được nhắc ở câu khác, không phải lí do đeo kính.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> What is Minh doing at the moment?', opts: o4('He is playing football.', 'He is sitting in the library.', 'He is explaining an exercise.', 'He is buying a new pen.'), ans: 'B', why: 'Câu áp chót của bài: "At the moment Minh is sitting in the school library."' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> The word "talkative" in the passage means ___.', opts: o4('liking to read many books', 'liking to help other people', 'good at solving Maths problems', 'liking to talk a lot with people'), ans: 'D', why: '<i>Talkative</i> có gốc là "talk" nên nghĩa là hay nói, nói nhiều. Ba phương án kia mô tả các đặc điểm khác của Minh nhưng không phải nghĩa của từ này.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> Which word best describes Minh\'s character?', opts: o4('lazy', 'selfish', 'kind', 'noisy'), ans: 'C', why: 'Bài đọc gọi Minh là "the kindest boy in our class" và kể việc em luôn là người đầu tiên giúp bạn.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 30', pts: 1, text: '<b>Câu 30.</b> The Maths competition is next month. If today is 25 September, in which month will the competition take place?', opts: o4('October', 'November', 'September', 'December'), ans: 'A', why: '"Next month" nghĩa là tháng kế tiếp tháng hiện tại. Sau September là <b>October</b>.' },
  ],
},

/* ═══════════ ĐỀ 4 — MY NEIGHBOURHOOD ═══════════ */
{
  id: 10704, title: 'Đề 4 · My neighbourhood — comparative adjectives, directions', time: 60,
  questions: [
    { sec: 'Phát âm', lvl: 'TH', name: 'Câu 1', pts: 1, text: 'Choose the word that has a different vowel sound from the others.', opts: o4('quiet', 'big', 'live', 'city'), ans: 'A', why: 'Chữ "i" trong <i>quiet</i> đọc là /aɪ/, còn <i>big, live, city</i> đều có âm /ɪ/.' },
    { sec: 'Trọng âm', lvl: 'NB', name: 'Câu 2', pts: 1, text: 'Choose the word that has a different stress pattern from the others.', opts: o4('market', 'temple', 'museum', 'cinema'), ans: 'C', why: '<i>Museum</i> nhấn âm tiết thứ hai (mu-SE-um); <i>market, temple, cinema</i> đều nhấn âm tiết thứ nhất.' },
    { sec: 'So sánh hơn', lvl: 'NC', name: 'Câu 3', pts: 1, text: 'My new neighbourhood is ___ and ___ than the old one.', opts: o4('more quiet – more modern', 'quieter – more modern', 'quieter – moderner', 'more quieter – more modern'), ans: 'B', why: 'Tính từ ngắn <i>quiet</i> thêm đuôi -er → <i>quieter</i>; tính từ dài <i>modern</i> (hai âm tiết, không kết thúc bằng -y) dùng <i>more modern</i>. Không được vừa thêm -er vừa dùng "more".' },
    { sec: 'Từ vựng địa điểm', lvl: 'NB', name: 'Câu 4', pts: 1, text: 'A place where you can borrow books is a ___.', opts: o4('museum', 'post office', 'cathedral', 'library'), ans: 'D', why: '<i>Library</i> = thư viện, nơi mượn sách.' },
    { sec: 'Chỉ đường', lvl: 'TH', name: 'Câu 5', pts: 1, text: 'Go straight ahead and ___ left at the traffic lights.', opts: o4('turn', 'take', 'go', 'make'), ans: 'A', why: 'Cụm chỉ đường cố định là <i>turn left / turn right</i>. "Take" chỉ dùng trong "take the first turning on the left".' },
    { sec: 'So sánh hơn', lvl: 'NC', name: 'Câu 6', pts: 1, text: 'Choose the sentence that is INCORRECT.', opts: o4('My house is nearer the school than yours.', 'My house is more near the school than yours.', 'This street is quieter than that one.', 'Da Lat is cooler than Ho Chi Minh City.'), ans: 'B', why: '<i>Near</i> là tính từ ngắn một âm tiết nên phải thêm -er: <i>nearer</i>, không dùng "more near". Ba câu còn lại đều dùng đúng quy tắc.' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 7', pts: 1, text: 'Choose the underlined part that needs correction: <u>My</u> village <u>is</u> more <u>peaceful</u> than your <u>city\'s</u>.', opts: o4('My', 'is', 'peaceful', 'city\'s'), ans: 'D', why: 'Sau "than your" đã đủ nghĩa "than your city" — thêm dấu sở hữu \'s là thừa và sai. Cấu trúc "more peaceful than" hoàn toàn đúng vì <i>peaceful</i> là tính từ dài.' },
    { sec: 'Từ vựng địa điểm', lvl: 'NB', name: 'Câu 8', pts: 1, text: 'We buy stamps and send letters at the ___.', opts: o4('bakery', 'pharmacy', 'post office', 'stadium'), ans: 'C', why: '<i>Post office</i> = bưu điện. <i>Bakery</i> là tiệm bánh, <i>pharmacy</i> là hiệu thuốc, <i>stadium</i> là sân vận động.' },
    { sec: 'Từ để hỏi', lvl: 'TH', name: 'Câu 9', pts: 1, text: 'Excuse me, ___ is the nearest bus stop? — It\'s over there, next to the bank.', opts: o4('what', 'where', 'how', 'when'), ans: 'B', why: 'Câu trả lời chỉ vị trí ("over there, next to the bank") nên câu hỏi dùng <i>where</i>.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 10', pts: 1, text: 'Nam walks from his house to school at a speed of 60 metres a minute. The distance is 900 metres. He must be at school at 7.00. What is the latest time he should leave home?', opts: o4('6.45', '6.30', '6.50', '6.40'), ans: 'A', why: 'Thời gian đi bộ = 900 : 60 = 15 phút. Vậy Nam phải rời nhà muộn nhất lúc 7.00 − 15 phút = <b>6.45</b>.' },
    { sec: 'Từ vựng địa điểm', lvl: 'NB', name: 'Câu 11', pts: 1, text: 'Which place do we go to when we are ill?', opts: o4('museum', 'stadium', 'art gallery', 'hospital'), ans: 'D', why: '<i>Hospital</i> = bệnh viện, nơi khám chữa bệnh.' },
    { sec: 'So sánh bằng', lvl: 'NC', name: 'Câu 12', pts: 1, text: 'My neighbourhood is not as crowded ___ the city centre, but it is ___ convenient.', opts: o4('than – more', 'as – much', 'as – more', 'than – as'), ans: 'C', why: 'Cấu trúc so sánh bằng phủ định là <i>not as + adj + as</i>. Vế sau so sánh hơn với tính từ dài <i>convenient</i> nên dùng <i>more convenient</i>. Không dùng "much convenient".' },
    { sec: 'Giới từ chỉ nơi chốn', lvl: 'TH', name: 'Câu 13', pts: 1, text: 'The cinema is ___ the supermarket and the bank.', opts: o4('between', 'among', 'next', 'opposite'), ans: 'A', why: 'Có đúng hai địa điểm nối bằng "and" nên dùng <i>between … and …</i>.' },
    { sec: 'Từ trái nghĩa', lvl: 'NB', name: 'Câu 14', pts: 1, text: 'Which word means "not noisy"?', opts: o4('busy', 'quiet', 'modern', 'narrow'), ans: 'B', why: '<i>Quiet</i> = yên tĩnh, trái nghĩa với <i>noisy</i> (ồn ào).' },
    { sec: 'Câu đồng nghĩa', lvl: 'NC', name: 'Câu 15', pts: 1, text: 'Choose the sentence that has the closest meaning to: "My village is not as big as your town."', opts: o4('My village is bigger than your town.', 'Your town is as big as my village.', 'My village and your town are the same size.', 'Your town is bigger than my village.'), ans: 'D', why: '"A is not as big as B" nghĩa là A nhỏ hơn B, tức B lớn hơn A. Vì vậy câu tương đương là "Your town is bigger than my village."' },
    { sec: 'Lời đề nghị lịch sự', lvl: 'TH', name: 'Câu 16', pts: 1, text: '___ you tell me the way to the museum, please?', opts: o4('Could', 'Must', 'Should', 'Do'), ans: 'A', why: '<i>Could you …, please?</i> là cách hỏi đường lịch sự. "Must" mang nghĩa bắt buộc, "Should" là lời khuyên.' },
    { sec: 'Từ trái nghĩa', lvl: 'NB', name: 'Câu 17', pts: 1, text: 'The opposite of "narrow" is ___.', opts: o4('long', 'short', 'wide', 'high'), ans: 'C', why: '<i>Narrow</i> (hẹp) trái nghĩa với <i>wide</i> (rộng). <i>Short</i> là trái nghĩa của "long".' },
    { sec: 'Giao tiếp', lvl: 'NC', name: 'Câu 18', pts: 1, text: '— "Excuse me, how can I get to the museum?" — "___"', opts: o4('It\'s about two kilometres away.', 'Go straight and turn left at the corner.', 'It opens at eight every morning.', 'It is the oldest building in our town.'), ans: 'B', why: 'Câu hỏi "How can I get to…?" là hỏi ĐƯỜNG ĐI nên phải trả lời bằng lời chỉ dẫn. Phương án A trả lời cho "How far…?", C trả lời cho "What time…?".' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 19', pts: 1, text: 'A bus leaves the station every 20 minutes, starting at 6.00. Lan arrives at the station at 7.10. How long must she wait for the next bus?', opts: o4('10 minutes', '20 minutes', '15 minutes', '5 minutes'), ans: 'A', why: 'Các chuyến xe rời bến lúc 6.00; 6.20; 6.40; 7.00; 7.20… Lan đến lúc 7.10 nên phải chờ đến 7.20, tức <b>10 phút</b>.' },
    { sec: 'Tính từ mô tả nơi chốn', lvl: 'TH', name: 'Câu 20', pts: 1, text: 'There are a lot of tall buildings and new shops in my neighbourhood, so it looks very ___.', opts: o4('narrow', 'peaceful', 'historic', 'modern'), ans: 'D', why: 'Nhà cao tầng và cửa hàng mới là dấu hiệu của một khu phố <i>modern</i> (hiện đại). <i>Historic</i> lại mang nghĩa cổ kính, lâu đời.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>I live in a small town <b>(21)___</b> the north of Viet Nam. My neighbourhood is not very big, but it is <b>(22)___</b> than the city where my cousin lives. There is a market, a post office and a new supermarket. The streets are <b>(23)___</b> and there are many trees, so the air is fresh. My favourite place is the small park <b>(24)___</b> the town hall. Every evening, people <b>(25)___</b> there to walk and do exercise.<br><br><b>Câu 21.</b>', opts: o4('at', 'on', 'in', 'to'), ans: 'C', why: 'Với các vùng miền ta dùng <i>in</i>: "in the north of Viet Nam".' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> My neighbourhood is not very big, but it is <b>(22)___</b> than the city where my cousin lives.', opts: o4('quieter', 'more quiet', 'quietest', 'as quiet'), ans: 'A', why: 'Có "than" nên đây là so sánh hơn. <i>Quiet</i> là tính từ ngắn nên thêm -er: <i>quieter</i>. Dạng "quietest" là so sánh nhất, còn "as quiet" phải đi với "as" chứ không đi với "than".' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> The streets are <b>(23)___</b> and there are many trees, so the air is fresh.', opts: o4('narrow', 'clean', 'crowded', 'noisy'), ans: 'B', why: 'Vế sau "so the air is fresh" cho thấy cả câu mang ý tích cực, nên tính từ phải là <i>clean</i>. Ba tính từ còn lại đều mang nghĩa tiêu cực, mâu thuẫn với kết luận "không khí trong lành".' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> My favourite place is the small park <b>(24)___</b> the town hall.', opts: o4('between', 'among', 'in', 'opposite'), ans: 'D', why: 'Chỉ có MỘT địa điểm phía sau nên không dùng "between … and …". <i>Opposite</i> (đối diện) là giới từ phù hợp.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> Every evening, people <b>(25)___</b> there to walk and do exercise.', opts: o4('goes', 'are going', 'go', 'going'), ans: 'C', why: '"Every evening" chỉ thói quen → hiện tại đơn; chủ ngữ "people" là số nhiều nên động từ giữ nguyên <i>go</i>.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>Hoi An is an ancient town in Quang Nam Province. It is smaller and quieter than Da Nang, but many tourists love it. The streets in the old quarter are narrow and there are no cars there, so visitors walk or ride bicycles. The houses are old, with yellow walls and wooden doors. On the fourteenth day of each lunar month, the electric lights are turned off and the whole town is lit by colourful lanterns. Many families in Hoi An make lanterns and sell them to visitors.<br><br><b>Câu 26.</b> How do visitors travel in the old quarter?', opts: o4('By car or by taxi.', 'On foot or by bicycle.', 'By bus or by train.', 'By boat on the river.'), ans: 'B', why: 'Bài đọc viết: "there are no cars there, so visitors walk or ride bicycles" — tức đi bộ hoặc đi xe đạp.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> Where is Hoi An?', opts: o4('In Quang Nam Province.', 'In Da Nang City.', 'In Quang Ninh Province.', 'In Hue City.'), ans: 'A', why: 'Câu mở đầu: "Hoi An is an ancient town in Quang Nam Province." Đà Nẵng chỉ được nhắc tới để so sánh.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> Which statement is NOT true about Hoi An?', opts: o4('It is quieter than Da Nang.', 'Its old houses have yellow walls.', 'Some families there make lanterns.', 'Its streets in the old quarter are wide.'), ans: 'D', why: 'Bài đọc nói rõ "The streets in the old quarter are <b>narrow</b>" — hẹp chứ không rộng. Ba phương án còn lại đều đúng với bài.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> What happens on the fourteenth day of each lunar month?', opts: o4('All the shops in the town are closed.', 'The town is lit by colourful lanterns.', 'Tourists are not allowed to come.', 'People ride cars around the old town.'), ans: 'B', why: 'Bài đọc: "the electric lights are turned off and the whole town is lit by colourful lanterns".' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 30', pts: 1, text: '<b>Câu 30.</b> A family in Hoi An makes 15 lanterns a day and sells each one for 40000 dong. How much money do they get in three days if they sell all the lanterns?', opts: o4('600000 dong', '1200000 dong', '1800000 dong', '180000 dong'), ans: 'C', why: 'Mỗi ngày thu được 15 × 40000 = 600000 đồng; trong ba ngày là 600000 × 3 = <b>1800000 đồng</b>. (Chọn 600000 đồng là quên nhân với ba ngày.)' },
  ],
},

/* ═══════════ ĐỀ 5 — NATURAL WONDERS OF VIET NAM ═══════════ */
{
  id: 10705, title: 'Đề 5 · Natural wonders — countable/uncountable, must/mustn\'t', time: 60,
  questions: [
    { sec: 'Phát âm', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently from the others: b<u>ea</u>ch — s<u>ea</u> — br<u>ea</u>d — t<u>ea</u>', opts: o4('beach', 'sea', 'bread', 'tea'), ans: 'C', why: 'Phần "ea" trong <i>bread</i> đọc là /e/, còn <i>beach, sea, tea</i> đều đọc /iː/.' },
    { sec: 'Phát âm', lvl: 'TH', name: 'Câu 2', pts: 1, text: 'Choose the word that does NOT contain the sound /aʊ/.', opts: o4('group', 'mountain', 'cloud', 'south'), ans: 'A', why: '<i>Group</i> /ɡruːp/ có âm /uː/. Ba từ còn lại (mountain, cloud, south) đều chứa /aʊ/.' },
    { sec: 'Trọng âm', lvl: 'NC', name: 'Câu 3', pts: 1, text: 'Choose the word that has a different stress pattern from the others.', opts: o4('island', 'bamboo', 'desert', 'forest'), ans: 'B', why: '<i>Bamboo</i> nhấn âm tiết thứ hai (bam-BOO); <i>island, desert, forest</i> đều nhấn âm tiết thứ nhất. Lưu ý chữ "s" trong <i>island</i> là âm câm.' },
    { sec: 'Danh từ không đếm được', lvl: 'NB', name: 'Câu 4', pts: 1, text: 'Which of these is an uncountable noun?', opts: o4('mountain', 'island', 'bottle', 'water'), ans: 'D', why: '<i>Water</i> không đếm được nên không có dạng số nhiều và không dùng "a/an". Muốn đếm phải mượn vật chứa: "two bottles of water".' },
    { sec: 'Danh từ không đếm được', lvl: 'TH', name: 'Câu 5', pts: 1, text: 'We need some ___ for the trip.', opts: o4('breads', 'a bread', 'bread', 'many bread'), ans: 'C', why: '<i>Bread</i> là danh từ không đếm được nên không thêm -s và không đi với "a" hay "many". Sau <i>some</i> ta để nguyên: <i>some bread</i>.' },
    { sec: 'some / any', lvl: 'NC', name: 'Câu 6', pts: 1, text: 'There isn\'t ___ water left, but we still have ___ sandwiches.', opts: o4('some – any', 'any – some', 'any – any', 'some – some'), ans: 'B', why: 'Câu phủ định dùng <i>any</i>; câu khẳng định dùng <i>some</i>. Hai vế nối bằng "but" nên một vế phủ định, một vế khẳng định.' },
    { sec: 'must / mustn\'t', lvl: 'NB', name: 'Câu 7', pts: 1, text: 'You ___ wear a helmet when you ride a motorbike. It\'s the law.', opts: o4('must', 'mustn\'t', 'can\'t', 'needn\'t'), ans: 'A', why: '"It\'s the law" cho biết đây là điều BẮT BUỘC nên dùng <i>must</i>. <i>Mustn\'t</i> mang nghĩa cấm, ngược hẳn nghĩa câu.' },
    { sec: 'must / mustn\'t', lvl: 'NC', name: 'Câu 8', pts: 1, text: 'We ___ take enough water with us, and we ___ leave rubbish in the cave.', opts: o4('mustn\'t – must', 'must – must', 'mustn\'t – mustn\'t', 'must – mustn\'t'), ans: 'D', why: 'Mang đủ nước là việc cần làm → <i>must</i>. Vứt rác trong hang là việc bị cấm → <i>mustn\'t</i>. Hai vế mang hai nghĩa trái ngược nên không thể dùng cùng một từ.' },
    { sec: 'Giới từ', lvl: 'TH', name: 'Câu 9', pts: 1, text: 'Phong Nha – Ke Bang is famous ___ its beautiful caves.', opts: o4('of', 'for', 'with', 'about'), ans: 'B', why: 'Cụm cố định <i>be famous for something</i> (nổi tiếng về cái gì).' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 10', pts: 1, text: 'Fansipan is 3143 metres high and Ba Den Mountain is 986 metres high. How much higher is Fansipan than Ba Den Mountain?', opts: o4('2257 m', '4129 m', '2157 m', '2143 m'), ans: 'C', why: 'Lấy hiệu hai độ cao: 3143 − 986 = <b>2157 m</b>. (Chọn 4129 m là cộng hai số thay vì trừ.)' },
    { sec: 'Từ vựng thiên nhiên', lvl: 'NB', name: 'Câu 11', pts: 1, text: 'Which is the highest mountain in Viet Nam?', opts: o4('Ba Den', 'Bach Ma', 'Lang Biang', 'Fansipan'), ans: 'D', why: 'Fansipan cao 3143 m, là đỉnh núi cao nhất Việt Nam và được gọi là "nóc nhà Đông Dương".' },
    { sec: 'So sánh nhất', lvl: 'NC', name: 'Câu 12', pts: 1, text: 'Mount Everest is ___ mountain in the world.', opts: o4('the highest', 'the most high', 'higher', 'highest'), ans: 'A', why: '<i>High</i> là tính từ ngắn nên so sánh nhất thêm -est và BẮT BUỘC có "the": <i>the highest</i>. Không dùng "the most" với tính từ ngắn, cũng không bỏ "the".' },
    { sec: 'How much / How many', lvl: 'TH', name: 'Câu 13', pts: 1, text: 'How ___ rice do we need? — About two kilos.', opts: o4('many', 'long', 'much', 'often'), ans: 'C', why: '<i>Rice</i> là danh từ không đếm được nên hỏi bằng <i>How much</i>. <i>How many</i> chỉ đi với danh từ đếm được số nhiều.' },
    { sec: 'Từ vựng thiên nhiên', lvl: 'NB', name: 'Câu 14', pts: 1, text: 'A ___ is a large area of sand with very little water.', opts: o4('forest', 'desert', 'valley', 'waterfall'), ans: 'B', why: '<i>Desert</i> = sa mạc. <i>Forest</i> là rừng, <i>valley</i> là thung lũng, <i>waterfall</i> là thác nước.' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 15', pts: 1, text: 'Choose the underlined part that needs correction: <u>Ha Long Bay</u> <u>is</u> one of the <u>most beautiful</u> <u>place</u> in Viet Nam.', opts: o4('Ha Long Bay', 'is', 'most beautiful', 'place'), ans: 'D', why: 'Cấu trúc <i>one of the + so sánh nhất + danh từ SỐ NHIỀU</i>, nên phải sửa thành <i>places</i>. Động từ vẫn chia số ít theo "one" nên "is" là đúng.' },
    { sec: 'Danh từ đếm được', lvl: 'TH', name: 'Câu 16', pts: 1, text: 'There are some ___ in the bag.', opts: o4('apples', 'apple', 'an apple', 'a apples'), ans: 'A', why: '"There are" đòi hỏi danh từ số nhiều, và <i>some</i> đi với danh từ đếm được số nhiều: <i>some apples</i>.' },
    { sec: 'Câu đồng nghĩa', lvl: 'NC', name: 'Câu 17', pts: 1, text: 'Choose the sentence that has the closest meaning to: "Don\'t swim in this river. It\'s dangerous."', opts: o4('You must swim in this river.', 'You can swim in this river.', 'You mustn\'t swim in this river.', 'You should swim in this river.'), ans: 'C', why: 'Câu mệnh lệnh phủ định "Don\'t…" mang nghĩa CẤM, tương đương <i>mustn\'t</i>. Ba phương án còn lại đều cho phép hoặc khuyến khích bơi, trái nghĩa.' },
    { sec: 'Từ vựng thiên nhiên', lvl: 'NB', name: 'Câu 18', pts: 1, text: 'Which of these is a natural wonder?', opts: o4('museum', 'waterfall', 'hotel', 'market'), ans: 'B', why: '<i>Waterfall</i> (thác nước) do thiên nhiên tạo ra; bảo tàng, khách sạn và chợ đều do con người xây dựng.' },
    { sec: 'So sánh hơn', lvl: 'TH', name: 'Câu 19', pts: 1, text: 'Da Lat is ___ than Ho Chi Minh City.', opts: o4('the coolest', 'more cool', 'cool', 'cooler'), ans: 'D', why: 'Có "than" nên dùng so sánh hơn; <i>cool</i> là tính từ ngắn nên thêm -er: <i>cooler</i>.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 20', pts: 1, text: 'A group of 25 students visit a national park. A ticket costs 30000 dong for each student. How much do they pay in total?', opts: o4('750000 dong', '550000 dong', '75000 dong', '300000 dong'), ans: 'A', why: 'Tổng tiền = 25 × 30000 = <b>750000 đồng</b>. (Chọn 75000 đồng là quên một chữ số 0 khi nhân.)' },
    { sec: 'Đồ dùng dã ngoại', lvl: 'NB', name: 'Câu 21', pts: 1, text: 'We use a ___ to find the right direction in the forest.', opts: o4('plaster', 'sun cream', 'compass', 'torch'), ans: 'C', why: '<i>Compass</i> = la bàn, dùng để xác định phương hướng. <i>Torch</i> là đèn pin — dùng để chiếu sáng chứ không chỉ hướng.' },
    { sec: 'Đếm danh từ không đếm được', lvl: 'NC', name: 'Câu 22', pts: 1, text: '— "How many ___ of water should we bring?" — "Three ___ are enough."', opts: o4('bottle – bottle', 'bottles – bottle', 'bottle – bottles', 'bottles – bottles'), ans: 'D', why: 'Sau "How many" và sau số đếm "three" đều phải dùng danh từ số nhiều <i>bottles</i>. Ta đếm chai chứ không đếm nước, vì <i>water</i> không đếm được.' },
    { sec: 'So sánh nhất', lvl: 'TH', name: 'Câu 23', pts: 1, text: 'Son Doong is ___ cave in the world.', opts: o4('bigger', 'the biggest', 'big', 'more big'), ans: 'B', why: 'So sánh trong phạm vi "in the world" nên dùng so sánh nhất: <i>the biggest</i> (tính từ ngắn kết thúc bằng phụ âm sau nguyên âm ngắn thì gấp đôi phụ âm).' },
    { sec: 'Danh từ đếm được', lvl: 'NB', name: 'Câu 24', pts: 1, text: 'Which noun is countable?', opts: o4('island', 'sand', 'milk', 'rice'), ans: 'A', why: '<i>Island</i> đếm được (one island, two islands). Cát, sữa và gạo đều là danh từ không đếm được.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 25', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 25–27).</i><br>Ha Long Bay is one of the most beautiful <b>(25)___</b> in Viet Nam. There are about 1600 islands and islets there. Visitors <b>(26)___</b> take a boat trip to see the caves. You <b>(27)___</b> throw rubbish into the water because it harms the sea animals.<br><br><b>Câu 25.</b>', opts: o4('place', 'a place', 'places', 'the place'), ans: 'C', why: 'Cấu trúc <i>one of the + so sánh nhất + danh từ số nhiều</i> nên phải dùng <i>places</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 26', pts: 1, text: '<b>Câu 26.</b> Visitors <b>(26)___</b> take a boat trip to see the caves.', opts: o4('must to', 'can', 'musting', 'cans'), ans: 'B', why: 'Sau động từ khuyết thiếu là động từ nguyên thể KHÔNG "to", và động từ khuyết thiếu không chia theo chủ ngữ. Chỉ <i>can</i> thỏa mãn.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> You <b>(27)___</b> throw rubbish into the water because it harms the sea animals.', opts: o4('must', 'should', 'can', 'mustn\'t'), ans: 'D', why: 'Vế sau nêu tác hại ("harms the sea animals") nên đây là điều bị cấm: <i>mustn\'t</i>.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 28', pts: 1, text: '<i>Read the passage and answer the questions (Câu 28–30).</i><br>Son Doong Cave is in Quang Binh Province. A local man found it in 1991, but people only explored it in 2009. It is the largest cave in the world: in some places it is more than 200 metres high and 150 metres wide. There is a river inside the cave and even a small forest, because sunlight comes in through two big holes in the roof. Only a few hundred tourists can visit Son Doong every year, and each trip lasts four days.<br><br><b>Câu 28.</b> Why can plants grow inside Son Doong Cave?', opts: o4('Because sunlight comes in through holes in the roof.', 'Because tourists bring seeds into the cave.', 'Because the cave is very high and very wide.', 'Because there is a river running inside it.'), ans: 'A', why: 'Bài đọc nêu rõ quan hệ nhân quả bằng "because": có rừng nhỏ vì ánh nắng lọt vào qua hai lỗ lớn trên trần hang. Con sông và kích thước hang là chi tiết khác, không phải lí do cây mọc được.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> When did people first explore the cave?', opts: o4('In 1991.', 'In 2000.', 'In 2009.', 'Every year.'), ans: 'C', why: 'Năm 1991 là lúc một người dân địa phương TÌM THẤY hang; mãi đến 2009 mới có đoàn thám hiểm. Đây là bẫy phân biệt "found" và "explored".' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 30', pts: 1, text: '<b>Câu 30.</b> If 300 tourists visit Son Doong this year and each trip has 10 people, how many trips are there?', opts: o4('10 trips', '300 trips', '40 trips', '30 trips'), ans: 'D', why: 'Số chuyến = 300 : 10 = <b>30 chuyến</b>.' },
  ],
},

/* ═══════════ ĐỀ 6 — OUR TET HOLIDAY ═══════════ */
{
  id: 10706, title: 'Đề 6 · Our Tet holiday — should/shouldn\'t, will for the future', time: 60,
  questions: [
    { sec: 'Phát âm', lvl: 'TH', name: 'Câu 1', pts: 1, text: 'Choose the word that has a different vowel sound from the others.', opts: o4('peach', 'special', 'clean', 'meat'), ans: 'B', why: 'Phần "ea" trong <i>special</i> /ˈspeʃəl/ đọc là /e/, còn <i>peach, clean, meat</i> đều có /iː/.' },
    { sec: 'Trọng âm', lvl: 'NB', name: 'Câu 2', pts: 1, text: 'Choose the word that has a different stress pattern from the others.', opts: o4('firework', 'lucky', 'money', 'return'), ans: 'D', why: '<i>Return</i> nhấn âm tiết thứ hai (re-TURN); ba từ còn lại đều nhấn âm tiết thứ nhất.' },
    { sec: 'Thì tương lai đơn', lvl: 'NC', name: 'Câu 3', pts: 1, text: 'Look at those dark clouds! It ___ soon.', opts: o4('rains', 'rained', 'will rain', 'is raining'), ans: 'C', why: 'Đây là DỰ ĐOÁN về tương lai dựa trên dấu hiệu đang thấy, nên dùng <i>will + V</i>. "Is raining" nghĩa là trời đang mưa rồi — mâu thuẫn với "soon".' },
    { sec: 'should / shouldn\'t', lvl: 'TH', name: 'Câu 4', pts: 1, text: 'You ___ eat too much candy at Tet. It\'s bad for your teeth.', opts: o4('shouldn\'t', 'should', 'must', 'will'), ans: 'A', why: 'Vế sau nêu tác hại nên đây là lời khuyên KHÔNG nên làm: <i>shouldn\'t</i>.' },
    { sec: 'Từ vựng ngày Tết', lvl: 'NB', name: 'Câu 5', pts: 1, text: 'At Tet, children often get ___ from their grandparents.', opts: o4('homework', 'lucky money', 'uniforms', 'tickets'), ans: 'B', why: '<i>Lucky money</i> = tiền mừng tuổi (tiền lì xì) — phong tục quen thuộc ngày Tết.' },
    { sec: 'should / shouldn\'t', lvl: 'NC', name: 'Câu 6', pts: 1, text: '— "I have a bad cold." — "You ___ go out tonight. You ___ stay at home and rest."', opts: o4('shouldn\'t – should', 'should – shouldn\'t', 'shouldn\'t – shouldn\'t', 'should – should'), ans: 'A', why: 'Người bị cảm thì không nên ra ngoài (<i>shouldn\'t go out</i>) nhưng nên ở nhà nghỉ (<i>should stay</i>). Hai lời khuyên trái chiều nên không dùng cùng một dạng.' },
    { sec: 'So sánh nhất', lvl: 'TH', name: 'Câu 7', pts: 1, text: 'Tet is the ___ important festival in Viet Nam.', opts: o4('more', 'much', 'very', 'most'), ans: 'D', why: '<i>Important</i> là tính từ dài nên so sánh nhất dùng <i>the most important</i>. Có sẵn "the" phía trước là dấu hiệu của so sánh nhất.' },
    { sec: 'Từ vựng ngày Tết', lvl: 'NB', name: 'Câu 8', pts: 1, text: 'Which word means "a special cake made of sticky rice, green beans and pork"?', opts: o4('peach blossom', 'lucky money', 'banh chung', 'firework'), ans: 'C', why: '<i>Banh chung</i> là bánh chưng — làm từ gạo nếp, đậu xanh và thịt lợn.' },
    { sec: 'Thì tương lai đơn', lvl: 'NC', name: 'Câu 9', pts: 1, text: 'Choose the sentence that is INCORRECT.', opts: o4('We will to visit our grandparents at Tet.', 'We won\'t go to school during Tet.', 'We will clean the house before Tet.', 'Will you come to my house at Tet?'), ans: 'A', why: 'Sau <i>will</i> phải là động từ nguyên thể KHÔNG "to". Ba câu còn lại đều đúng: dạng phủ định "won\'t + V", khẳng định "will + V" và nghi vấn "Will + S + V?".' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 10', pts: 1, text: 'Tet starts on 29 January this year. A family cleans the house three days before Tet. On which date do they clean the house?', opts: o4('25 January', '26 January', '1 February', '27 January'), ans: 'B', why: 'Lùi ba ngày từ 29 tháng Một: 29 − 3 = ngày <b>26 tháng Một</b>. (Chọn 1 February là cộng thêm ba ngày thay vì trừ.)' },
    { sec: 'Câu hỏi với will', lvl: 'NC', name: 'Câu 11', pts: 1, text: '— "What ___ you ___ at Tet?" — "I\'ll visit my relatives."', opts: o4('do – do', 'are – doing', 'will – do', 'will – doing'), ans: 'C', why: 'Câu trả lời "I\'ll visit…" cho biết đang hỏi về tương lai, nên dùng <i>Will + S + V(nguyên thể)</i>: "What will you do…?". Sau "will" không dùng V-ing.' },
    { sec: 'should / shouldn\'t', lvl: 'TH', name: 'Câu 12', pts: 1, text: 'We shouldn\'t ___ rubbish in the street during the festival.', opts: o4('throwing', 'to throw', 'throws', 'throw'), ans: 'D', why: 'Sau <i>should/shouldn\'t</i> là động từ nguyên thể không "to" và không chia: <i>throw</i>.' },
    { sec: 'Câu hỏi với will', lvl: 'NB', name: 'Câu 13', pts: 1, text: '___ you help me decorate the house? — Sure.', opts: o4('Will', 'Are', 'Do you will', 'Shall to'), ans: 'A', why: 'Câu hỏi về việc sắp làm, theo sau là động từ nguyên thể "help", nên bắt đầu bằng <i>Will</i>.' },
    { sec: 'Từ vựng ngày Tết', lvl: 'TH', name: 'Câu 14', pts: 1, text: 'In the north of Viet Nam, people often buy ___ blossom at Tet.', opts: o4('apricot', 'peach', 'lotus', 'sunflower'), ans: 'B', why: 'Miền Bắc chơi hoa đào (<i>peach blossom</i>), còn miền Nam chơi hoa mai (<i>apricot blossom</i>).' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 15', pts: 1, text: 'Choose the underlined part that needs correction: <u>You</u> <u>should</u> <u>wear</u> your <u>new clothe</u> on the first day of Tet.', opts: o4('You', 'should', 'wear', 'new clothe'), ans: 'D', why: 'Danh từ chỉ quần áo luôn ở dạng số nhiều <i>clothes</i>, không có dạng số ít "clothe" với nghĩa này. Cấu trúc "should + wear" hoàn toàn đúng.' },
    { sec: 'Từ vựng ngày Tết', lvl: 'NB', name: 'Câu 16', pts: 1, text: 'Tet usually falls in ___ or February.', opts: o4('August', 'June', 'January', 'April'), ans: 'C', why: 'Tết Nguyên đán rơi vào khoảng cuối tháng Một hoặc trong tháng Hai dương lịch.' },
    { sec: 'should / shouldn\'t', lvl: 'TH', name: 'Câu 17', pts: 1, text: 'We ___ sweep the floor on the first day of Tet because it may sweep away the good luck.', opts: o4('shouldn\'t', 'should', 'will', 'can'), ans: 'A', why: 'Mệnh đề "because…" nêu hậu quả xấu nên đây là lời khuyên không nên làm: <i>shouldn\'t</i>.' },
    { sec: 'Câu đồng nghĩa', lvl: 'NC', name: 'Câu 18', pts: 1, text: 'Choose the sentence that has the closest meaning to: "It\'s a good idea to visit your teacher at Tet."', opts: o4('You must visit your teacher at Tet.', 'You mustn\'t visit your teacher at Tet.', 'You will visit your teacher at Tet.', 'You should visit your teacher at Tet.'), ans: 'D', why: '"It\'s a good idea to…" là LỜI KHUYÊN nên chuyển thành <i>should</i>. Dùng <i>must</i> sẽ thành bắt buộc, mạnh hơn hẳn ý câu gốc.' },
    { sec: 'Từ vựng ngày Tết', lvl: 'NB', name: 'Câu 19', pts: 1, text: 'The evening before the first day of Tet is called ___.', opts: o4('New Year\'s Day', 'New Year\'s Eve', 'Mid-Autumn Festival', 'the weekend'), ans: 'B', why: '<i>New Year\'s Eve</i> = đêm giao thừa; <i>New Year\'s Day</i> mới là ngày mồng Một.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 20', pts: 1, text: 'Nam gets 200000 dong of lucky money from his aunt and 150000 dong from his uncle. He puts half of the total into his piggy bank. How much does he save?', opts: o4('100000 dong', '350000 dong', '175000 dong', '75000 dong'), ans: 'C', why: 'Tổng tiền: 200000 + 150000 = 350000 đồng. Một nửa là 350000 : 2 = <b>175000 đồng</b>. (Chọn 350000 là quên bước chia đôi.)' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–24).</i><br>Tet is the most important holiday in Viet Nam. A few days before Tet, families clean and <b>(21)___</b> their houses. On New Year\'s Eve, they cook special food <b>(22)___</b> banh chung and boiled chicken. Children <b>(23)___</b> new clothes and receive lucky money. People believe that they <b>(24)___</b> say bad things during the first days of the year, because it may bring bad luck.<br><br><b>Câu 21.</b>', opts: o4('decorate', 'decorating', 'decorates', 'to decorate'), ans: 'A', why: 'Hai động từ "clean and ___" cùng chia theo chủ ngữ "families" (số nhiều) nên giữ nguyên thể: <i>decorate</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> … they cook special food <b>(22)___</b> banh chung and boiled chicken.', opts: o4('so', 'because', 'such as', 'but'), ans: 'C', why: 'Bánh chưng và gà luộc là VÍ DỤ cho "special food" nên dùng <i>such as</i> (chẳng hạn như). Ba từ còn lại đều là liên từ nối mệnh đề, không dùng để liệt kê ví dụ.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> Children <b>(23)___</b> new clothes and receive lucky money.', opts: o4('wears', 'wear', 'wearing', 'to wear'), ans: 'B', why: '<i>Children</i> là dạng số nhiều bất quy tắc của "child" nên động từ giữ nguyên: <i>wear</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> … they <b>(24)___</b> say bad things during the first days of the year, because it may bring bad luck.', opts: o4('should', 'will', 'must', 'shouldn\'t'), ans: 'D', why: 'Mệnh đề "because it may bring bad luck" cho biết đây là điều nên TRÁNH, nên phải chọn dạng phủ định <i>shouldn\'t</i>.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 25', pts: 1, text: '<i>Read the passage and answer the questions (Câu 25–30).</i><br>In my family, Tet begins a week early. My mother and I go to the flower market to buy a kumquat tree. My father repaints the gate, and my grandmother makes banh chung with my aunt. On the last night of the old year, we all sit together and watch the special TV programme. At midnight, my grandfather gives a short speech and wishes everyone good health. On the first morning, our neighbours come to our house and my little sister gets a lot of lucky money. I like Tet because the whole family is together.<br><br><b>Câu 25.</b> How early does Tet begin in the writer\'s family?', opts: o4('A week before the holiday.', 'Three days before the holiday.', 'On New Year\'s Eve.', 'On the first morning.'), ans: 'A', why: 'Câu đầu bài: "In my family, Tet begins a week early." — sớm một tuần.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 26', pts: 1, text: '<b>Câu 26.</b> Who makes banh chung?', opts: o4('The writer and his mother.', 'The writer\'s father.', 'The grandmother and the aunt.', 'The neighbours.'), ans: 'C', why: 'Bài đọc: "my grandmother makes banh chung with my aunt". Mẹ và người viết đi chợ hoa, còn bố sơn lại cổng.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> Which activity is NOT mentioned in the passage?', opts: o4('Buying a kumquat tree.', 'Repainting the gate.', 'Watching a TV programme.', 'Setting off fireworks at midnight.'), ans: 'D', why: 'Bài chỉ nói lúc nửa đêm ông nội phát biểu và chúc sức khỏe, hoàn toàn không nhắc tới pháo hoa. Ba hoạt động kia đều có trong bài.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> What does the grandfather do at midnight?', opts: o4('He gives lucky money to everyone.', 'He gives a speech and wishes good health.', 'He goes to the flower market.', 'He visits the neighbours.'), ans: 'B', why: 'Bài đọc: "At midnight, my grandfather gives a short speech and wishes everyone good health." Người nhận tiền mừng tuổi là em gái, vào sáng mồng Một.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> Why does the writer like Tet?', opts: o4('Because the whole family is together.', 'Because he gets a lot of lucky money.', 'Because he doesn\'t have to do homework.', 'Because he can watch TV all night.'), ans: 'A', why: 'Câu cuối bài nói rõ: "I like Tet because the whole family is together."' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 30', pts: 1, text: '<b>Câu 30.</b> If Tet is on 10 February, on which date does the writer\'s family begin preparing?', opts: o4('17 February', '5 February', '3 February', '1 February'), ans: 'C', why: 'Gia đình chuẩn bị sớm một tuần, tức lùi 7 ngày: 10 − 7 = ngày <b>3 tháng Hai</b>. (Chọn 17 February là cộng thêm một tuần.)' },
  ],
},

/* ═══════════ ĐỀ 7 — TELEVISION ═══════════ */
{
  id: 10707, title: 'Đề 7 · Television — câu hỏi Wh-, liên từ', time: 60,
  questions: [
    { sec: 'Phát âm', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently from the others: w<u>a</u>tch — <u>a</u>ctor — ch<u>a</u>nnel — f<u>a</u>mous', opts: o4('watch', 'actor', 'channel', 'famous'), ans: 'D', why: 'Chữ "a" trong <i>famous</i> đọc /eɪ/; <i>watch, actor, channel</i> đều đọc /æ/.' },
    { sec: 'Phát âm', lvl: 'TH', name: 'Câu 2', pts: 1, text: 'Choose the word whose final <b>-s</b> is pronounced differently from the others.', opts: o4('sports', 'shows', 'films', 'programmes'), ans: 'A', why: 'Đuôi -s trong <i>sports</i> đọc /s/ vì đứng sau âm vô thanh /t/. Ba từ còn lại kết thúc bằng âm hữu thanh nên -s đọc /z/.' },
    { sec: 'Trọng âm', lvl: 'NC', name: 'Câu 3', pts: 1, text: 'Choose the word that has a different stress pattern from the others.', opts: o4('viewer', 'cartoon', 'weather', 'programme'), ans: 'B', why: '<i>Cartoon</i> nhấn âm tiết thứ hai (car-TOON) — một trong số ít danh từ hai âm tiết nhấn âm sau. <i>Viewer, weather, programme</i> đều nhấn âm tiết đầu. Bẫy ở <i>programme</i>: từ trông dài nhưng vẫn nhấn âm đầu.' },
    { sec: 'Câu hỏi Wh-', lvl: 'NB', name: 'Câu 4', pts: 1, text: '___ is your favourite TV programme? — Tom and Jerry.', opts: o4('What', 'Where', 'When', 'Who'), ans: 'A', why: 'Hỏi về tên chương trình (một sự vật) nên dùng <i>What</i>.' },
    { sec: 'Câu hỏi Wh-', lvl: 'TH', name: 'Câu 5', pts: 1, text: '___ do you watch TV? — After dinner.', opts: o4('What', 'Who', 'When', 'Why'), ans: 'C', why: 'Câu trả lời "After dinner" chỉ thời điểm nên hỏi bằng <i>When</i>.' },
    { sec: 'Từ vựng truyền hình', lvl: 'NB', name: 'Câu 6', pts: 1, text: 'A ___ is a person who reads the news on television.', opts: o4('viewer', 'comedian', 'character', 'newsreader'), ans: 'D', why: '<i>Newsreader</i> = phát thanh viên bản tin. <i>Viewer</i> = khán giả, <i>comedian</i> = diễn viên hài, <i>character</i> = nhân vật.' },
    { sec: 'Câu hỏi Wh-', lvl: 'NC', name: 'Câu 7', pts: 1, text: 'Choose the question for the <u>underlined</u> part: "My brother watches TV <u>for two hours</u> every evening."', opts: o4('How often does your brother watch TV?', 'How long does your brother watch TV?', 'When does your brother watch TV?', 'Why does your brother watch TV?'), ans: 'B', why: '"For two hours" là KHOẢNG THỜI GIAN kéo dài nên phải hỏi bằng <i>How long</i>. Bẫy lớn nhất là phương án A: <i>How often</i> hỏi về TẦN SUẤT và câu trả lời phải là "twice a week", "every evening"…' },
    { sec: 'Liên từ', lvl: 'NC', name: 'Câu 8', pts: 1, text: 'I wanted to watch the football match, ___ my sister wanted to watch a cartoon, ___ we watched them in two different rooms.', opts: o4('but – so', 'so – but', 'and – because', 'because – so'), ans: 'A', why: 'Hai ý ĐỐI LẬP (tôi muốn xem bóng đá / em gái muốn xem hoạt hình) nối bằng <i>but</i>; vế cuối là KẾT QUẢ của mâu thuẫn đó nên nối bằng <i>so</i>. Bẫy ở phương án B: đảo ngược hai liên từ khiến câu mất logic — không thể nêu kết quả trước rồi mới nêu sự tương phản.' },
    { sec: 'Liên từ', lvl: 'TH', name: 'Câu 9', pts: 1, text: 'I like this game show ___ it is very funny.', opts: o4('but', 'so', 'because', 'and'), ans: 'C', why: 'Vế sau nêu LÍ DO nên dùng <i>because</i>. Dùng <i>so</i> sẽ đảo ngược quan hệ nhân – quả.' },
    { sec: 'Từ vựng truyền hình', lvl: 'NB', name: 'Câu 10', pts: 1, text: 'We use a ___ to change TV channels.', opts: o4('remote control', 'microphone', 'loudspeaker', 'keyboard'), ans: 'A', why: '<i>Remote control</i> = điều khiển từ xa, dùng để chuyển kênh.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 11', pts: 1, text: 'Look at the VTV3 schedule: <b>18.00</b> Cartoons · <b>18.30</b> The News · <b>19.00</b> A game show · <b>20.15</b> A film. The film lasts 95 minutes. What time does it finish?', opts: o4('21.35', '21.45', '22.05', '21.50'), ans: 'D', why: '95 phút = 1 giờ 35 phút. 20.15 + 1 giờ 35 phút = <b>21.50</b>. (Chọn 21.35 là chỉ cộng 1 giờ 20 phút; chọn 22.05 là cộng nhầm thành 1 giờ 50 phút.)' },
    { sec: 'Hiện tại tiếp diễn', lvl: 'TH', name: 'Câu 12', pts: 1, text: 'Look! My little brother ___ a cartoon on TV now.', opts: o4('watches', 'is watching', 'watch', 'watching'), ans: 'B', why: 'Có "Look!" và "now" nên dùng hiện tại tiếp diễn: <i>is watching</i>.' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 13', pts: 1, text: 'Choose the underlined part that needs correction: <u>How many</u> hours a day <u>does</u> your sister <u>watches</u> <u>television</u>?', opts: o4('How many', 'does', 'watches', 'television'), ans: 'C', why: 'Sau trợ động từ <i>does</i>, động từ chính phải trở về nguyên thể: <i>watch</i>. Lỗi "chia -s hai lần" là lỗi phổ biến nhất ở lớp 6. "How many hours" và "television" (dùng như danh từ không đếm được khi nói về truyền hình nói chung) đều đúng.' },
    { sec: 'Câu hỏi Wh-', lvl: 'NB', name: 'Câu 14', pts: 1, text: '___ is on TV tonight? — A new film.', opts: o4('Who', 'Where', 'Which', 'What'), ans: 'D', why: 'Hỏi về nội dung chương trình (sự vật) nên dùng <i>What</i>.' },
    { sec: 'Từ vựng truyền hình', lvl: 'TH', name: 'Câu 15', pts: 1, text: 'Which word does NOT name a kind of TV programme?', opts: o4('comedy', 'cartoon', 'remote', 'documentary'), ans: 'C', why: '<i>Comedy, cartoon, documentary</i> đều là thể loại chương trình; <i>remote</i> là cái điều khiển từ xa.' },
    { sec: 'Giới từ thời gian', lvl: 'NB', name: 'Câu 16', pts: 1, text: 'The news is on ___ seven o\'clock every evening.', opts: o4('at', 'in', 'on', 'to'), ans: 'A', why: 'Dùng <i>at</i> với giờ đồng hồ.' },
    { sec: 'Giao tiếp', lvl: 'NC', name: 'Câu 17', pts: 1, text: '— "Shall we watch the new game show tonight?" — "___"', opts: o4('That sounds great. What time is it on?', 'Yes, it is. I watch it every day.', 'No, thanks. I have got one already.', 'Sorry, I do not know the way there.'), ans: 'A', why: '"Shall we…?" là lời RỦ CÙNG LÀM nên phải đáp bằng lời nhận lời và hỏi thêm thông tin. Bẫy ở phương án B: "Yes, it is" chỉ dùng để trả lời câu hỏi Yes/No với <i>be</i>, không đáp được cho "Shall we…?". Phương án C là từ chối một món đồ, D là lời đáp khi được hỏi đường.' },
    { sec: 'Trạng từ tần suất', lvl: 'TH', name: 'Câu 18', pts: 1, text: 'Which sentence is correct?', opts: o4('My father watches always the news at 7 p.m.', 'My father always watches the news at 7 p.m.', 'Always my father watches the news at 7 p.m.', 'My father watches the news always at 7 p.m.'), ans: 'B', why: 'Trạng từ tần suất <i>always</i> đứng TRƯỚC động từ thường và sau chủ ngữ.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 19', pts: 1, text: 'Mai watches television from 8.00 to 9.30 every evening from Monday to Friday. How long does she watch television in those five days?', opts: o4('Six hours and a half.', 'Seven hours only.', 'Eight hours and a half.', 'Seven hours and a half.'), ans: 'D', why: 'Mỗi tối 1 giờ 30 phút = 1,5 giờ. Năm tối: 1,5 × 5 = <b>7,5 giờ</b> = bảy tiếng rưỡi. (Chọn "seven hours only" là làm tròn xuống, bỏ mất 30 phút lẻ.)' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 20', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 20–24).</i><br>Television is very popular in Viet Nam. Almost every family <b>(20)___</b> a TV set. My grandmother likes the news best <b>(21)___</b> it tells her what is happening in the country. My father often watches sports programmes, <b>(22)___</b> my mother does not like them at all. She prefers films and game shows. My little sister is only five, so she watches cartoons <b>(23)___</b> the afternoon. In my family we have one rule: we <b>(24)___</b> watch TV during dinner.<br><br><b>Câu 20.</b> Almost every family <b>(20)___</b> a TV set.', opts: o4('have', 'has', 'having', 'are'), ans: 'B', why: 'Chủ ngữ là "every family": <i>every</i> luôn đi với danh từ số ít và động từ chia ngôi thứ ba số ít → <i>has</i>. Bẫy ở phương án A: thấy nghĩa "hầu như mọi gia đình" mang tính số nhiều nên học sinh chọn <i>have</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 21', pts: 1, text: '<b>Câu 21.</b> My grandmother likes the news best <b>(21)___</b> it tells her what is happening in the country.', opts: o4('because', 'so', 'but', 'and'), ans: 'A', why: 'Vế sau giải thích LÍ DO bà thích bản tin nên dùng <i>because</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> My father often watches sports programmes, <b>(22)___</b> my mother does not like them at all.', opts: o4('and', 'so', 'but', 'because'), ans: 'C', why: 'Bố thích thể thao còn mẹ hoàn toàn không thích — hai ý trái ngược nên dùng <i>but</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> … so she watches cartoons <b>(23)___</b> the afternoon.', opts: o4('in', 'on', 'at', 'to'), ans: 'A', why: 'Dùng <i>in</i> với các buổi trong ngày: <i>in the morning / in the afternoon / in the evening</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> In my family we have one rule: we <b>(24)___</b> watch TV during dinner.', opts: o4('always', 'usually', 'never', 'sometimes'), ans: 'C', why: 'Đây là một "rule" (quy định) cấm xem TV trong bữa ăn, nên tần suất phải là <i>never</i>. Bẫy ở <i>sometimes</i>: nếu "thỉnh thoảng vẫn xem" thì đó không còn là một quy định nữa. Phải suy ra từ cụm "one rule" chứ không có dấu hiệu ngữ pháp nào.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 25', pts: 1, text: '<i>Read the passage and answer the questions (Câu 25–29).</i><br>Nam is twelve years old. He loves watching television, but his parents only let him watch it for one hour a day. On school days, Nam watches TV after he finishes his homework, usually from 8 p.m. to 9 p.m. His favourite programme is a science show. Its name is "Why and How". It is on VTV2 every Tuesday and Thursday evening. Nam\'s sister Linh does not like science shows; she thinks they are boring. She loves music programmes and she often sings along with the singers. Their father enjoys the news, and their mother likes cooking programmes because she learns new recipes from them.<br><br><b>Câu 25.</b> How long does Nam watch television every day?', opts: o4('For two hours.', 'For half an hour.', 'For three hours.', 'For one hour.'), ans: 'D', why: 'Bài đọc viết: "his parents only let him watch it for one hour a day".' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 26', pts: 1, text: '<b>Câu 26.</b> Why doesn\'t Linh watch "Why and How"?', opts: o4('Because she has much homework.', 'Because it is on too late.', 'Because she finds it boring.', 'Because her father watches the news.'), ans: 'C', why: 'Phải nối hai thông tin ở hai câu khác nhau: "Why and How" là một science show, và "Linh does not like science shows; she thinks they are boring". Bẫy ở phương án B: bài có nhắc giờ chiếu buổi tối nhưng không hề nói Linh thấy muộn.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> The word "recipes" in the passage is closest in meaning to ___.', opts: o4('ways of cooking food', 'kinds of music shows', 'names of TV channels', 'times of TV programmes'), ans: 'A', why: '<i>Recipe</i> = công thức nấu ăn; mẹ học được điều đó từ các chương trình dạy nấu ăn.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> How many times a week is "Why and How" on TV?', opts: o4('Once.', 'Twice.', 'Three times.', 'Every evening.'), ans: 'B', why: 'Chương trình chiếu "every Tuesday and Thursday evening" — hai lần một tuần.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> Which statement is TRUE about Nam\'s family?', opts: o4('Nam watches television before doing his homework.', 'Nam and Linh like the same TV programme.', 'Nam\'s mother watches TV to learn something new.', 'Nam\'s father does not watch television at all.'), ans: 'C', why: 'Mẹ xem chương trình nấu ăn "because she learns new recipes from them" — tức là xem để học điều mới. Bẫy ở phương án A: bài viết "watches TV AFTER he finishes his homework", đảo thứ tự là sai; phương án D trái với câu "their father enjoys the news".' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 30', pts: 1, text: 'On Tuesday evening: the news is from 19.00 to 19.45, a cooking programme from 19.45 to 20.15, and "Why and How" from 20.15 to 21.00. Nam may watch TV for only one hour a day. He watches "Why and How" from the beginning to the end. How many more minutes can he still watch TV that evening?', opts: o4('10 minutes.', '20 minutes.', '30 minutes.', '15 minutes.'), ans: 'D', why: '"Why and How" kéo dài từ 20.15 đến 21.00 = 45 phút. Nam được xem 60 phút một ngày nên còn lại 60 − 45 = <b>15 phút</b>. (Chọn 30 phút là nhầm sang độ dài chương trình nấu ăn.)' },
  ],
},
/* ═══════════ ĐỀ 8 — SPORTS AND GAMES ═══════════ */
{
  id: 10708, title: 'Đề 8 · Sports and games — past simple (có quy tắc & bất quy tắc)', time: 60,
  questions: [
    { sec: 'Phát âm', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Choose the word whose final <b>-ed</b> is pronounced differently from the others.', opts: o4('played', 'watched', 'opened', 'called'), ans: 'B', why: 'Đuôi -ed trong <i>watched</i> đọc /t/ vì đứng sau âm vô thanh /tʃ/. Ba từ còn lại đứng sau âm hữu thanh nên -ed đọc /d/.' },
    { sec: 'Phát âm', lvl: 'TH', name: 'Câu 2', pts: 1, text: 'Choose the word whose final <b>-ed</b> is pronounced differently from the others: want<b>ed</b> — start<b>ed</b> — walk<b>ed</b> — need<b>ed</b>', opts: o4('wanted', 'started', 'walked', 'needed'), ans: 'C', why: '<i>Walked</i> có -ed đọc /t/. <i>Wanted, started, needed</i> kết thúc bằng /t/ hoặc /d/ nên -ed đọc thành một âm tiết riêng /ɪd/.' },
    { sec: 'Trọng âm', lvl: 'NB', name: 'Câu 3', pts: 1, text: 'Choose the word that has a different stress pattern from the others.', opts: o4('football', 'tennis', 'badminton', 'aerobics'), ans: 'D', why: '<i>Aerobics</i> nhấn âm tiết thứ hai (ae-RO-bics); ba từ còn lại đều nhấn âm tiết đầu.' },
    { sec: 'Quá khứ đơn', lvl: 'NC', name: 'Câu 4', pts: 1, text: 'Yesterday Nam ___ to the stadium, but he ___ the first half because he arrived late.', opts: o4('went – didn\'t see', 'goes – didn\'t see', 'went – didn\'t saw', 'went – doesn\'t see'), ans: 'A', why: 'Cả câu ở quá khứ (yesterday, arrived) nên vế đầu là <i>went</i>. Vế phủ định dùng <i>didn\'t</i> + động từ NGUYÊN THỂ → <i>didn\'t see</i>. Bẫy ở phương án C: học sinh hay chia quá khứ hai lần thành "didn\'t saw".' },
    { sec: 'was / were', lvl: 'TH', name: 'Câu 5', pts: 1, text: 'There ___ many people at the football match last Sunday.', opts: o4('was', 'were', 'is', 'are'), ans: 'B', why: '"Many people" là số nhiều và câu ở quá khứ ("last Sunday") nên dùng <i>There were</i>.' },
    { sec: 'So sánh hơn', lvl: 'NC', name: 'Câu 6', pts: 1, text: 'Choose the sentence that has the closest meaning to: "Mai is a better swimmer than Lan."', opts: o4('Lan swims better than Mai.', 'Mai and Lan swim equally well.', 'Lan is the best swimmer in her class.', 'Mai swims better than Lan.'), ans: 'D', why: 'Phải chuyển cụm danh từ "a better swimmer" sang cụm động từ "swims better": người bơi giỏi hơn vẫn là Mai. Bẫy ở phương án A: đảo chủ ngữ khiến nghĩa trái ngược hẳn; phương án C nhầm so sánh hơn thành so sánh nhất.' },
    { sec: 'Từ vựng thể thao', lvl: 'NB', name: 'Câu 7', pts: 1, text: 'People play football on a ___.', opts: o4('pitch', 'pool', 'court', 'track'), ans: 'A', why: 'Sân bóng đá là <i>pitch</i>. <i>Pool</i> là bể bơi, <i>court</i> là sân tennis/cầu lông, <i>track</i> là đường chạy.' },
    { sec: 'Collocation do / play / go', lvl: 'TH', name: 'Câu 8', pts: 1, text: 'My sister ___ aerobics twice a week.', opts: o4('plays', 'does', 'goes', 'makes'), ans: 'B', why: 'Với môn không có bóng và không kết thúc bằng -ing ta dùng <i>do</i>: <i>do aerobics, do karate</i>. <i>Play</i> đi với môn có bóng, <i>go</i> đi với môn có đuôi -ing (go swimming).' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 9', pts: 1, text: 'A football match has two halves of 45 minutes and a 15-minute break between them. The match started at 19.30. What time did it finish?', opts: o4('21.00', '21.30', '21.15', '20.15'), ans: 'C', why: 'Tổng thời gian: 45 + 15 + 45 = 105 phút = 1 giờ 45 phút. 19.30 + 1 giờ 45 phút = <b>21.15</b>. (Chọn 21.00 là quên 15 phút nghỉ giữa hiệp.)' },
    { sec: 'Quá khứ đơn', lvl: 'NB', name: 'Câu 10', pts: 1, text: 'We ___ volleyball in the school yard last week.', opts: o4('play', 'plays', 'playing', 'played'), ans: 'D', why: 'Có "last week" nên dùng quá khứ đơn: <i>played</i>.' },
    { sec: 'can / could', lvl: 'NC', name: 'Câu 11', pts: 1, text: 'Last year Linh ___ swim at all, but now she ___ swim very well.', opts: o4('can\'t – can', 'couldn\'t – can', 'couldn\'t – could', 'didn\'t can – can'), ans: 'B', why: '"Last year" là mốc quá khứ → <i>couldn\'t</i>; "now" là hiện tại → <i>can</i>. Bẫy ở phương án C: dùng <i>could</i> cho vế "now" là sai thì; phương án D mắc lỗi "didn\'t + can" — sau <i>didn\'t</i> không bao giờ có động từ khuyết thiếu.' },
    { sec: 'Câu hỏi Wh- quá khứ', lvl: 'TH', name: 'Câu 12', pts: 1, text: '___ did your team play against last Saturday? — Class 6B.', opts: o4('Who', 'What', 'Where', 'When'), ans: 'A', why: 'Câu trả lời là một đội gồm người ("Class 6B") nên hỏi bằng <i>Who</i>.' },
    { sec: 'Từ vựng thể thao', lvl: 'NB', name: 'Câu 13', pts: 1, text: 'A person who watches a sports match is a ___.', opts: o4('player', 'coach', 'spectator', 'referee'), ans: 'C', why: '<i>Spectator</i> = khán giả. <i>Player</i> = cầu thủ, <i>coach</i> = huấn luyện viên, <i>referee</i> = trọng tài.' },
    { sec: 'So sánh hơn / nhất', lvl: 'NC', name: 'Câu 14', pts: 1, text: 'Our team scored three goals, ___ their team scored only one. We were the ___ team on that day.', opts: o4('but – better', 'and – best', 'but – best', 'so – better'), ans: 'C', why: 'Hai kết quả đối lập nên nối bằng <i>but</i>. Chỗ trống sau có mạo từ "the" và phạm vi "on that day" (so với mọi đội hôm đó) nên phải dùng so sánh NHẤT: <i>the best team</i>. Bẫy ở phương án A: đúng liên từ nhưng "the better" chỉ dùng khi so với đúng một đối tượng và phải có "than".' },
    { sec: 'Giao tiếp', lvl: 'NC', name: 'Câu 15', pts: 1, text: '— "Would you like to play table tennis with me this afternoon?" — "___"', opts: o4('I\'d love to, but I have to help my mum.', 'Yes, I did. It was a great match.', 'No, I am not. I am quite busy now.', 'You are welcome. It is my pleasure.'), ans: 'A', why: '"Would you like to…?" là lời MỜI, nên cách đáp lịch sự là nhận lời hoặc từ chối kèm lí do: "I\'d love to, but…". Bẫy ở phương án B: "Yes, I did" là câu đáp cho câu hỏi ở quá khứ, không hợp với lời mời cho buổi chiều nay.' },
    { sec: 'Giới từ', lvl: 'TH', name: 'Câu 16', pts: 1, text: 'The match takes place ___ Sunday morning ___ the school stadium.', opts: o4('in – at', 'on – at', 'at – in', 'on – in'), ans: 'B', why: 'Dùng <i>on</i> với buổi của một ngày cụ thể ("on Sunday morning") và <i>at</i> với địa điểm được coi là nơi diễn ra hoạt động ("at the stadium").' },
    { sec: 'Từ vựng thể thao', lvl: 'NB', name: 'Câu 17', pts: 1, text: 'Which sport do you need a racket for?', opts: o4('swimming', 'running', 'cycling', 'badminton'), ans: 'D', why: '<i>Badminton</i> (cầu lông) cần vợt — <i>racket</i>.' },
    { sec: 'Quá khứ đơn phủ định', lvl: 'TH', name: 'Câu 18', pts: 1, text: 'Which sentence is correct?', opts: o4('He did not went to the gym last night.', 'He not went to the gym last night.', 'He didn\'t go to the gym last night.', 'He doesn\'t went to the gym last night.'), ans: 'C', why: 'Phủ định quá khứ đơn: <i>didn\'t</i> + động từ nguyên thể. Câu A chia quá khứ hai lần, câu B thiếu trợ động từ, câu D sai thì của trợ động từ.' },
    { sec: 'Câu hỏi Wh- quá khứ', lvl: 'NC', name: 'Câu 19', pts: 1, text: 'Choose the question for the <u>underlined</u> part: "My father played football <u>at the stadium</u> last Sunday."', opts: o4('When did your father play football?', 'Where did your father play football?', 'Who did your father play football with?', 'Why did your father play football there?'), ans: 'B', why: '"At the stadium" chỉ NƠI CHỐN nên hỏi bằng <i>Where</i>. Bẫy ở phương án A: thấy "last Sunday" trong câu gốc nên học sinh chọn <i>When</i>, nhưng chỉ phần được gạch chân mới là phần cần hỏi.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 20', pts: 1, text: 'Minh runs 400 metres in one round of the school track. On Monday he ran five rounds and on Tuesday he ran seven rounds. How many kilometres did he run in these two days?', opts: o4('2 km', '4.2 km', '5.2 km', '4.8 km'), ans: 'D', why: 'Tổng số vòng: 5 + 7 = 12. Quãng đường: 12 × 400 = 4800 m = <b>4,8 km</b>. (Chọn 2 km là chỉ tính 5 vòng của ngày thứ Hai.)' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>Sports are very important for our health. Last year my school <b>(21)___</b> a sports festival in April. Students from every class took part in it. My friend Phong <b>(22)___</b> in the 100-metre race and he won the first prize. I did not run <b>(23)___</b> I was not good at running, so I played badminton with a girl from Class 6C. The match was hard, <b>(24)___</b> I lost it. After the festival our teacher told us: "You <b>(25)___</b> do sports every day to stay healthy."<br><br><b>Câu 21.</b> Last year my school <b>(21)___</b> a sports festival in April.', opts: o4('organised', 'organises', 'organise', 'is organising'), ans: 'A', why: 'Có mốc thời gian "Last year" nên dùng quá khứ đơn: <i>organised</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> My friend Phong <b>(22)___</b> in the 100-metre race and he won the first prize.', opts: o4('runs', 'running', 'ran', 'run'), ans: 'C', why: 'Vế sau dùng "won" (quá khứ) nên vế trước cũng phải ở quá khứ: <i>ran</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> I did not run <b>(23)___</b> I was not good at running, so I played badminton.', opts: o4('but', 'so', 'because', 'and'), ans: 'C', why: 'Vế sau nêu LÍ DO người viết không chạy nên dùng <i>because</i>. Bẫy ở <i>so</i>: câu đã có sẵn một "so" ở vế cuối; nếu dùng thêm "so" ở đây thì hai kết quả nối tiếp nhau và câu mất hẳn phần lí do.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> The match was hard, <b>(24)___</b> I lost it.', opts: o4('so', 'but', 'because', 'and'), ans: 'A', why: 'Trận đấu khó là NGUYÊN NHÂN, thua trận là KẾT QUẢ nên dùng <i>so</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> "You <b>(25)___</b> do sports every day to stay healthy."', opts: o4('shouldn\'t', 'should', 'mustn\'t', 'won\'t'), ans: 'B', why: 'Đây là LỜI KHUYÊN của thầy cô nên dùng <i>should</i>. Ba phương án còn lại đều mang nghĩa phủ định, trái với ý "để giữ sức khoẻ".' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>Last Saturday, Class 6A had a football match against Class 6B. The match began at 3 p.m. on the school pitch and many students came to watch it. In the first half, Class 6B scored two goals and Class 6A scored none. The players of Class 6A were very tired. During the break, their coach gave them water and some good advice. In the second half, Class 6A played much better. They scored three goals in twenty minutes. The final score was 3–2 for Class 6A. After the match, the two classes had a small party together.<br><br><b>Câu 26.</b> What was the score at the end of the first half?', opts: o4('0–2 for Class 6B.', '2–3 for Class 6A.', '3–2 for Class 6A.', '1–1 for both classes.'), ans: 'A', why: 'Hiệp một: 6B ghi hai bàn, 6A không ghi bàn nào → 0–2 nghiêng về Class 6B.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> Why did Class 6A play better in the second half?', opts: o4('Because Class 6B had fewer players.', 'Because they rested and got advice.', 'Because the match began at 3 p.m.', 'Because many students watched them.'), ans: 'B', why: 'Phải SUY RA từ câu "During the break, their coach gave them water and some good advice": nghỉ giải lao và nghe lời khuyên đã giúp họ chơi hay hơn. Bẫy ở phương án D: bài có nói nhiều học sinh đến xem, nhưng đó không phải nguyên nhân được nêu.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> Which statement is NOT true about the match?', opts: o4('Class 6A scored three goals in the second half.', 'The match took place on the school pitch.', 'The two classes had a party after the match.', 'Class 6B won the match at the end.'), ans: 'D', why: 'Tỉ số cuối cùng là 3–2 nghiêng về Class 6A nên nói Class 6B thắng là SAI. Bẫy nằm ở chỗ hiệp một 6B dẫn 2–0, học sinh đọc lướt dễ tưởng 6B thắng chung cuộc.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> The word "advice" in the passage means ___.', opts: o4('a long rest at home', 'money for a new ball', 'useful things to say', 'a prize for the winner'), ans: 'C', why: '<i>Advice</i> = lời khuyên — những điều hữu ích mà huấn luyện viên nói với cầu thủ.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 30', pts: 1, text: 'The match began at 3 p.m. Each half lasted 30 minutes and the break lasted 10 minutes. Class 6A scored their first goal 5 minutes after the second half began. What time was that goal?', opts: o4('3.35 p.m.', '3.40 p.m.', '4.05 p.m.', '3.45 p.m.'), ans: 'D', why: 'Hiệp hai bắt đầu lúc 3.00 + 30 phút + 10 phút = 3.40. Bàn thắng đến sau đó 5 phút → <b>3.45 p.m.</b> (Chọn 3.35 là quên 10 phút nghỉ giữa hiệp.)' },
  ],
},
/* ═══════════ ĐỀ 9 — CITIES OF THE WORLD ═══════════ */
{
  id: 10709, title: 'Đề 9 · Cities of the world — so sánh nhất, địa danh nổi tiếng', time: 60,
  questions: [
    { sec: 'Phát âm', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently from the others: c<u>i</u>ty — b<u>i</u>g — <u>i</u>sland — br<u>i</u>dge', opts: o4('city', 'big', 'island', 'bridge'), ans: 'C', why: 'Chữ "i" trong <i>island</i> đọc /aɪ/ (và chữ "s" câm); ba từ còn lại đều đọc /ɪ/.' },
    { sec: 'Trọng âm', lvl: 'NC', name: 'Câu 2', pts: 1, text: 'Choose the word that has a different stress pattern from the others.', opts: o4('museum', 'building', 'expensive', 'exciting'), ans: 'B', why: '<i>Building</i> nhấn âm tiết thứ nhất (BUIL-ding); <i>museum, expensive, exciting</i> đều nhấn âm tiết thứ hai. Bẫy ở <i>museum</i>: từ này viết ngắn nhưng trọng âm lại rơi vào âm giữa (mu-SE-um).' },
    { sec: 'Phát âm', lvl: 'TH', name: 'Câu 3', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently from the others.', opts: o4('<u>th</u>ose', '<u>th</u>eatre', '<u>th</u>ree', '<u>th</u>ank'), ans: 'A', why: '<i>Those</i> có âm /ð/ (hữu thanh); <i>theatre, three, thank</i> đều có âm /θ/ (vô thanh).' },
    { sec: 'So sánh nhất', lvl: 'NB', name: 'Câu 4', pts: 1, text: 'Ho Chi Minh City is ___ city in Viet Nam.', opts: o4('a big', 'bigger', 'big', 'the biggest'), ans: 'D', why: 'So sánh với TẤT CẢ các thành phố trong cả nước nên dùng so sánh nhất: <i>the biggest</i>.' },
    { sec: 'So sánh hơn / nhất', lvl: 'NC', name: 'Câu 5', pts: 1, text: 'Ha Noi is ___ than Hai Phong, but Ho Chi Minh City is ___ city in our country.', opts: o4('big – biggest', 'bigger – the biggest', 'the biggest – bigger', 'more big – the most big'), ans: 'B', why: 'Có "than" ở vế đầu → so sánh HƠN <i>bigger</i>; vế sau so với cả nước → so sánh NHẤT có mạo từ <i>the biggest</i>. Bẫy ở phương án C: đảo ngược hai dạng; bẫy ở D: <i>big</i> là tính từ ngắn nên không dùng "more/most".' },
    { sec: 'Viết lại câu', lvl: 'NC', name: 'Câu 6', pts: 1, text: 'Choose the sentence that has the closest meaning to: "No city in Japan is larger than Tokyo."', opts: o4('Tokyo is larger than every city.', 'Tokyo is not the largest city in Japan.', 'Tokyo is the largest city in Japan.', 'Some cities in Japan are larger than Tokyo.'), ans: 'C', why: '"Không thành phố nào lớn hơn Tokyo" nghĩa là Tokyo LỚN NHẤT Nhật Bản. Bẫy ở phương án A: bỏ mất giới hạn "in Japan" nên câu trở thành sai sự thật; phương án B và D đều ngược nghĩa.' },
    { sec: 'Giới từ', lvl: 'TH', name: 'Câu 7', pts: 1, text: 'London is famous ___ Big Ben and Tower Bridge.', opts: o4('for', 'of', 'with', 'about'), ans: 'A', why: 'Cụm cố định <i>be famous for something</i> = nổi tiếng về/vì cái gì.' },
    { sec: 'Từ vựng thành phố', lvl: 'NB', name: 'Câu 8', pts: 1, text: 'A ___ is a place where people can see old and valuable things.', opts: o4('stadium', 'market', 'cathedral', 'museum'), ans: 'D', why: '<i>Museum</i> = bảo tàng. <i>Stadium</i> = sân vận động, <i>market</i> = chợ, <i>cathedral</i> = nhà thờ lớn.' },
    { sec: 'So sánh nhất', lvl: 'TH', name: 'Câu 9', pts: 1, text: 'Which is the correct superlative form of the adjective "beautiful"?', opts: o4('beautifuler', 'beautifullest', 'the beautifulest', 'the most beautiful'), ans: 'D', why: '<i>Beautiful</i> là tính từ dài (ba âm tiết) nên so sánh nhất là <i>the most beautiful</i>, không thêm đuôi -est.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 10', pts: 1, text: 'A plane leaves Ha Noi for Singapore at 9.45 and the flight lasts 3 hours 20 minutes. Singapore time is one hour ahead of Viet Nam time. What is the local time in Singapore when the plane lands?', opts: o4('13.05', '13.45', '14.05', '15.05'), ans: 'C', why: 'Giờ hạ cánh theo giờ Việt Nam: 9.45 + 3 giờ 20 phút = 13.05. Singapore đi trước 1 giờ nên giờ địa phương là <b>14.05</b>. (Chọn 13.05 là quên cộng chênh lệch múi giờ.)' },
    { sec: 'Từ vựng thành phố', lvl: 'NB', name: 'Câu 11', pts: 1, text: 'Sydney is a big city in ___.', opts: o4('Australia', 'England', 'Canada', 'Japan'), ans: 'A', why: 'Sydney là thành phố lớn của <i>Australia</i> (Ô-xtrây-li-a).' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 12', pts: 1, text: 'Ha Noi has about 8 million people, Bangkok about 10 million, and Tokyo about 37 million. Which sentence is TRUE?', opts: o4('Bangkok is the most crowded of the three.', 'Ha Noi has the smallest population.', 'Tokyo has fewer people than Bangkok.', 'Ha Noi is bigger than the other two.'), ans: 'B', why: '8 < 10 < 37 nên Hà Nội có dân số nhỏ nhất trong ba thành phố. Bẫy ở phương án A: Bangkok chỉ đứng giữa, thành phố đông nhất là Tokyo; phương án C đảo ngược con số.' },
    { sec: 'So sánh hơn', lvl: 'TH', name: 'Câu 13', pts: 1, text: 'Which sentence is correct?', opts: o4('Paris is the more beautiful than Lyon.', 'Paris is more beautiful than Lyon.', 'Paris is beautifuler than Lyon.', 'Paris is most beautiful than Lyon.'), ans: 'B', why: 'Tính từ dài so sánh hơn: <i>more + adj + than</i>, không thêm "the" và không thêm đuôi -er.' },
    { sec: 'Câu hỏi Wh-', lvl: 'NB', name: 'Câu 14', pts: 1, text: '___ is the capital of France? — Paris.', opts: o4('What', 'Who', 'Where', 'Which'), ans: 'A', why: 'Hỏi tên thủ đô (một sự vật/địa danh) nên dùng <i>What</i>: "What is the capital of…?".' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 15', pts: 1, text: 'Choose the underlined part that needs correction: Tokyo <u>is</u> <u>one of</u> the <u>most busy</u> cities <u>in</u> the world.', opts: o4('is', 'one of', 'most busy', 'in'), ans: 'C', why: '<i>Busy</i> là tính từ hai âm tiết kết thúc bằng "-y" nên so sánh nhất là <i>the busiest</i> (đổi y thành i, thêm -est), không dùng "most busy". Cấu trúc "one of the + so sánh nhất + danh từ số nhiều" ở các phần còn lại là đúng.' },
    { sec: 'Giới từ chỉ nơi chốn', lvl: 'TH', name: 'Câu 16', pts: 1, text: 'The Eiffel Tower is ___ Paris, ___ the bank of the Seine.', opts: o4('at – in', 'in – at', 'on – in', 'in – on'), ans: 'D', why: 'Với tên thành phố dùng <i>in Paris</i>; với bờ sông dùng cụm cố định <i>on the bank of…</i>.' },
    { sec: 'Từ vựng thành phố', lvl: 'NB', name: 'Câu 17', pts: 1, text: 'Which word means a very tall modern building in a big city?', opts: o4('cottage', 'skyscraper', 'palace', 'temple'), ans: 'B', why: '<i>Skyscraper</i> = toà nhà chọc trời. <i>Cottage</i> = nhà tranh nhỏ, <i>palace</i> = cung điện, <i>temple</i> = đền/chùa.' },
    { sec: 'Mạo từ', lvl: 'TH', name: 'Câu 18', pts: 1, text: 'New York is ___ exciting city, and it is ___ biggest city in the USA.', opts: o4('an – the', 'a – the', 'the – a', 'an – a'), ans: 'A', why: '"Exciting" bắt đầu bằng nguyên âm nên dùng <i>an</i>; trước so sánh nhất luôn dùng <i>the</i>.' },
    { sec: 'Giao tiếp', lvl: 'NC', name: 'Câu 19', pts: 1, text: '— "What do you think of Da Nang?" — "___"', opts: o4('Yes, I think so. It is quite far.', 'I am going there by plane next week.', 'It is about 800 kilometres away.', 'I love it. The beaches are wonderful.'), ans: 'D', why: '"What do you think of…?" hỏi Ý KIẾN nên phải đáp bằng một nhận xét. Bẫy ở phương án A: câu hỏi bắt đầu bằng "What" (câu hỏi Wh-) nên không thể trả lời "Yes/No"; phương án C là đáp cho "How far…?".' },
    { sec: 'So sánh nhất', lvl: 'NC', name: 'Câu 20', pts: 1, text: 'Ha Long Bay is ___ place I know, ___ I want to go there again.', opts: o4('a more beautiful – but', 'the most beautiful – but', 'the most beautiful – so', 'more beautiful – so'), ans: 'C', why: 'Cụm "place I know" bao hàm mọi nơi người nói biết nên dùng so sánh NHẤT <i>the most beautiful</i>; vế sau là KẾT QUẢ (đẹp nhất nên muốn quay lại) nên nối bằng <i>so</i>. Bẫy ở phương án B: dùng <i>but</i> làm hai vế mâu thuẫn vô lí.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>Singapore is a small country in Southeast Asia, but it is one of <b>(21)___</b> cities in the world. It is clean, modern and safe. Millions of tourists <b>(22)___</b> there every year. They come to see the Merlion, the Gardens by the Bay and the night zoo. Life in Singapore is quite expensive, <b>(23)___</b> many people still want to live there. The streets are very clean <b>(24)___</b> people mustn\'t throw rubbish on them. Tourists <b>(25)___</b> try the food in the hawker centres — it is delicious and cheap.<br><br><b>Câu 21.</b> … it is one of <b>(21)___</b> cities in the world.', opts: o4('the busier', 'busier', 'the busiest', 'most busy'), ans: 'C', why: 'Cấu trúc "one of + the + so sánh nhất + danh từ số nhiều" nên chọn <i>the busiest</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> Millions of tourists <b>(22)___</b> there every year.', opts: o4('go', 'goes', 'going', 'went'), ans: 'A', why: 'Chủ ngữ "Millions of tourists" số nhiều và có "every year" (thói quen, hiện tại đơn) nên dùng <i>go</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> Life in Singapore is quite expensive, <b>(23)___</b> many people still want to live there.', opts: o4('so', 'and', 'because', 'but'), ans: 'D', why: 'Chữ "still" (vẫn) là dấu hiệu của sự TƯƠNG PHẢN: đắt đỏ nhưng người ta vẫn muốn sống ở đó → <i>but</i>. Bẫy ở <i>so</i>: nếu dùng "so" thì câu thành "đắt nên người ta muốn sống ở đó" — phi lí.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> The streets are very clean <b>(24)___</b> people mustn\'t throw rubbish on them.', opts: o4('but', 'so', 'because', 'and'), ans: 'C', why: 'Vế sau nêu LÍ DO đường phố sạch (vì có quy định cấm xả rác) nên dùng <i>because</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> Tourists <b>(25)___</b> try the food in the hawker centres — it is delicious and cheap.', opts: o4('mustn\'t', 'should', 'shouldn\'t', 'needn\'t'), ans: 'B', why: 'Vế sau khen món ăn ngon và rẻ nên đây là một LỜI KHUYÊN nên làm: <i>should</i>.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>Linh\'s family lives in Hue, an old city in central Viet Nam. Hue is smaller than Ha Noi and Da Nang, but it is very famous for its history. The Perfume River runs through the middle of the city. On the north bank there is the Imperial City, the home of the old kings. On the south bank there are hotels, schools and shops. Every two years the city holds a big festival. Thousands of visitors come to Hue at that time, so the hotels are always full. Linh\'s father works as a tour guide, and in festival weeks he is the busiest man in the family.<br><br><b>Câu 26.</b> Why are the hotels in Hue always full during the festival?', opts: o4('Because a lot of visitors come to the city.', 'Because the city has only a few hotels.', 'Because the hotels are on the south bank.', 'Because Linh\'s father works as a guide.'), ans: 'A', why: 'Bài viết "Thousands of visitors come to Hue at that time, SO the hotels are always full" — chữ "so" chỉ rõ quan hệ nhân quả. Bẫy ở phương án B: bài không hề nói Huế có ít khách sạn; phương án C chỉ nêu vị trí chứ không phải nguyên nhân.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> Where is the Imperial City?', opts: o4('In the middle of the Perfume River.', 'On the south bank of the river.', 'Outside the city of Hue.', 'On the north bank of the river.'), ans: 'D', why: 'Bài đọc viết: "On the north bank there is the Imperial City".' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> How often does Hue hold the big festival?', opts: o4('Every year.', 'Every two years.', 'Twice a year.', 'Every month.'), ans: 'B', why: 'Bài đọc viết "Every two years the city holds a big festival" — hai năm một lần.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> Which statement is TRUE about Hue?', opts: o4('It is smaller than Da Nang but well known.', 'It is the biggest city in central Viet Nam.', 'It has no hotels for foreign visitors.', 'Its festival takes place every single year.'), ans: 'A', why: 'Câu thứ hai của bài: "Hue is smaller than Ha Noi and Da Nang, but it is very famous". Bẫy ở phương án B: nhầm so sánh hơn (nhỏ hơn Đà Nẵng) thành so sánh nhất; bẫy ở D: "every two years" chứ không phải hằng năm.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 30', pts: 1, text: 'A city tour of Hue costs 250000 dong for an adult. A child pays half that price. Linh\'s family has two adults and three children. How much does the family pay for the tour?', opts: o4('750000 dong', '875000 dong', '1000000 dong', '625000 dong'), ans: 'B', why: 'Người lớn: 2 × 250000 = 500000 đồng. Trẻ em: 3 × 125000 = 375000 đồng. Tổng cộng <b>875000 đồng</b>. (Chọn 625000 là chỉ tính một người lớn.)' },
  ],
},

/* ═══════════ ĐỀ 10 — OUR HOUSES IN THE FUTURE ═══════════ */
{
  id: 10710, title: 'Đề 10 · Our houses in the future — will / might', time: 60,
  questions: [
    { sec: 'Phát âm', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently from the others: c<u>ou</u>ntry — h<u>ou</u>se — m<u>ou</u>ntain — <u>ou</u>r', opts: o4('country', 'house', 'mountain', 'our'), ans: 'A', why: '"ou" trong <i>country</i> đọc /ʌ/; ba từ còn lại đều có âm đôi /aʊ/.' },
    { sec: 'Phát âm', lvl: 'TH', name: 'Câu 2', pts: 1, text: 'Choose the word that does NOT contain the sound /uː/.', opts: o4('m<u>oo</u>n', 'r<u>oo</u>m', 'sch<u>oo</u>l', 'b<u>oo</u>k'), ans: 'D', why: '<i>Book</i> có nguyên âm ngắn /ʊ/; <i>moon, room, school</i> đều có nguyên âm dài /uː/.' },
    { sec: 'Trọng âm', lvl: 'NC', name: 'Câu 3', pts: 1, text: 'Choose the word that has a different stress pattern from the others.', opts: o4('future', 'machine', 'building', 'modern'), ans: 'B', why: '<i>Machine</i> nhấn âm tiết thứ hai (ma-CHINE); <i>future, building, modern</i> đều nhấn âm tiết đầu. Bẫy ở <i>modern</i>: tuy có gốc giống tiếng Pháp nhưng trong tiếng Anh vẫn nhấn âm đầu.' },
    { sec: 'Thì tương lai với will', lvl: 'NC', name: 'Câu 4', pts: 1, text: 'In 2050 people ___ in tall buildings, and robots ___ all the housework for them.', opts: o4('live – will do', 'will live – do', 'will live – will do', 'will live – will make'), ans: 'C', why: 'Mốc "In 2050" là tương lai nên CẢ HAI vế đều phải dùng <i>will</i>. Bẫy ở phương án D: đúng thì nhưng sai collocation — tiếng Anh nói <i>do the housework</i>, không nói "make the housework".' },
    { sec: 'Thì tương lai với will', lvl: 'NB', name: 'Câu 5', pts: 1, text: 'I think my house ___ have a smart TV in ten years.', opts: o4('will', 'is', 'was', 'does'), ans: 'A', why: '"In ten years" chỉ thời gian tương lai nên dùng <i>will</i> + động từ nguyên thể.' },
    { sec: 'might', lvl: 'TH', name: 'Câu 6', pts: 1, text: 'It ___ rain this afternoon, but I am not sure.', opts: o4('will', 'won\'t', 'must', 'might'), ans: 'D', why: 'Vế sau nói "I am not sure" nên phải dùng <i>might</i> (có thể, không chắc chắn) thay vì <i>will</i> (chắc chắn).' },
    { sec: 'Từ vựng nhà ở', lvl: 'NB', name: 'Câu 7', pts: 1, text: 'Which type of home floats on water?', opts: o4('apartment', 'houseboat', 'villa', 'palace'), ans: 'B', why: '<i>Houseboat</i> = nhà thuyền, nổi trên mặt nước.' },
    { sec: 'Viết lại câu', lvl: 'NC', name: 'Câu 8', pts: 1, text: 'Choose the sentence that has the closest meaning to: "Perhaps we will have a robot in the kitchen."', opts: o4('We will certainly have a robot in the kitchen.', 'We might have a robot in the kitchen.', 'We must have a robot in the kitchen.', 'We never have a robot in the kitchen.'), ans: 'B', why: '<i>Perhaps</i> diễn tả điều KHÔNG CHẮC CHẮN, tương đương với <i>might</i>. Bẫy ở phương án A: "certainly" biến câu thành chắc chắn 100%, mạnh hơn hẳn câu gốc; phương án C nói về sự bắt buộc.' },
    { sec: 'There will be', lvl: 'TH', name: 'Câu 9', pts: 1, text: 'There ___ be flying cars in our city in the future.', opts: o4('will', 'wills', 'is going', 'are'), ans: 'A', why: 'Cấu trúc tương lai của "there is/are" là <i>there will be</i>. Động từ khuyết thiếu <i>will</i> không bao giờ thêm -s.' },
    { sec: 'Từ vựng đồ dùng', lvl: 'NB', name: 'Câu 10', pts: 1, text: 'We keep our clothes in a ___.', opts: o4('fridge', 'dishwasher', 'cooker', 'wardrobe'), ans: 'D', why: '<i>Wardrobe</i> = tủ quần áo. <i>Fridge</i> = tủ lạnh, <i>dishwasher</i> = máy rửa bát, <i>cooker</i> = bếp nấu.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 11', pts: 1, text: 'A smart fridge costs 24 million dong. This week the shop gives a discount of 25%. How much does a customer pay for it now?', opts: o4('16 million dong', '20 million dong', '18 million dong', '21 million dong'), ans: 'C', why: 'Giảm 25% nghĩa là còn phải trả 75%: 24 × 75 : 100 = <b>18 triệu đồng</b>. (Chọn 21 triệu là nhầm mức giảm thành 12,5%.)' },
    { sec: 'Câu hỏi với will', lvl: 'TH', name: 'Câu 12', pts: 1, text: '___ your house have a garden in the future? — Yes, it will.', opts: o4('Does', 'Is', 'Will', 'Do'), ans: 'C', why: 'Câu trả lời "Yes, it will" cho biết câu hỏi phải bắt đầu bằng <i>Will</i>.' },
    { sec: 'will + liên từ', lvl: 'NC', name: 'Câu 13', pts: 1, text: 'My future house ___ be in the countryside ___ I love fresh air and quiet places.', opts: o4('will – because', 'will – so', 'might – but', 'won\'t – because'), ans: 'A', why: 'Người nói đang mơ về ngôi nhà tương lai của mình nên dùng <i>will</i> (khẳng định), và vế sau nêu LÍ DO nên dùng <i>because</i>. Bẫy ở phương án B: <i>so</i> đảo ngược nhân quả — không thể nói "nhà ở nông thôn nên tôi yêu không khí trong lành".' },
    { sec: 'Câu hỏi Wh- tương lai', lvl: 'NB', name: 'Câu 14', pts: 1, text: '___ will your future house be? — In the mountains.', opts: o4('What', 'Who', 'When', 'Where'), ans: 'D', why: 'Câu trả lời chỉ nơi chốn ("In the mountains") nên hỏi bằng <i>Where</i>.' },
    { sec: 'Từ vựng nhà ở', lvl: 'TH', name: 'Câu 15', pts: 1, text: 'A future house has solar panels on the roof. Solar panels take energy from ___.', opts: o4('the wind', 'the water', 'the sun', 'the earth'), ans: 'C', why: '<i>Solar</i> nghĩa là thuộc về mặt trời, nên tấm pin mặt trời lấy năng lượng từ <i>the sun</i>.' },
    { sec: 'Từ vựng đồ dùng', lvl: 'NB', name: 'Câu 16', pts: 1, text: 'Which appliance washes plates and bowls?', opts: o4('washing machine', 'dishwasher', 'cooker', 'air conditioner'), ans: 'B', why: '<i>Dishwasher</i> = máy rửa bát. <i>Washing machine</i> là máy giặt quần áo.' },
    { sec: 'Giao tiếp', lvl: 'NC', name: 'Câu 17', pts: 1, text: '— "I think robots will do all our homework in 2050." — "___"', opts: o4('I don\'t agree. We should learn by ourselves.', 'Yes, they did. It was really helpful.', 'No, they are not. They are in my house.', 'You are welcome. That is very kind of you.'), ans: 'A', why: 'Câu nói là một Ý KIẾN về tương lai nên cách đáp tự nhiên là đồng ý hoặc phản đối kèm lí do. Bẫy ở phương án B: "Yes, they did" là thì quá khứ trong khi câu gốc nói về năm 2050; phương án D là lời đáp cho một lời khen hoặc cảm ơn.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 18', pts: 1, text: 'Nam\'s future house will have 4 bedrooms. Each bedroom needs 2 light bulbs and each bulb uses 9 watts. The lights are on for 5 hours every evening. How many watt-hours do the bedroom lights use in one evening?', opts: o4('180', '270', '320', '360'), ans: 'D', why: 'Số bóng đèn: 4 × 2 = 8. Công suất: 8 × 9 = 72 W. Trong 5 giờ: 72 × 5 = <b>360</b> watt-giờ. (Chọn 180 là quên nhân với số phòng.)' },
    { sec: 'Thì tương lai với will', lvl: 'TH', name: 'Câu 19', pts: 1, text: 'Which sentence is correct?', opts: o4('My house will has a swimming pool.', 'My house will have a swimming pool.', 'My house will to have a swimming pool.', 'My house will having a swimming pool.'), ans: 'B', why: 'Sau <i>will</i> luôn là động từ NGUYÊN THỂ không "to": <i>will have</i>.' },
    { sec: 'Từ trái nghĩa', lvl: 'NB', name: 'Câu 20', pts: 1, text: 'The opposite of the adjective "modern" is ___.', opts: o4('new', 'smart', 'old', 'tall'), ans: 'C', why: '<i>Modern</i> (hiện đại) trái nghĩa với <i>old</i> (cũ, cổ).' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>What will our houses be like in 2050? Some people think we <b>(21)___</b> in tall buildings in big cities. Others think we will live under the sea, <b>(22)___</b> I don\'t believe that. My dream house will be a small villa in the countryside. It will be near a river, <b>(23)___</b> I can swim every morning. In the kitchen there <b>(24)___</b> be a robot cook, so my mother will not be tired after work. I know my dream house is expensive, but I <b>(25)___</b> work hard to make it come true.<br><br><b>Câu 21.</b> Some people think we <b>(21)___</b> in tall buildings in big cities.', opts: o4('will living', 'will to live', 'are live', 'will live'), ans: 'D', why: 'Sau <i>will</i> phải là động từ nguyên thể KHÔNG "to" và KHÔNG thêm -ing: <i>will live</i>. Bẫy ở phương án A: học sinh hay lẫn tương lai đơn với hiện tại tiếp diễn nên viết "will living".' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> Others think we will live under the sea, <b>(22)___</b> I don\'t believe that.', opts: o4('but', 'and', 'so', 'because'), ans: 'A', why: 'Người viết nêu ý kiến của người khác rồi PHẢN ĐỐI ("I don\'t believe that") nên phải nối bằng <i>but</i>. Bẫy ở <i>so</i>: dùng "so" sẽ thành "họ nghĩ vậy nên tôi không tin" — không có quan hệ nhân quả nào ở đây.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> It will be near a river, <b>(23)___</b> I can swim every morning.', opts: o4('but', 'so', 'because', 'or'), ans: 'B', why: 'Nhà ở gần sông là nguyên nhân, việc bơi mỗi sáng là KẾT QUẢ nên dùng <i>so</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> In the kitchen there <b>(24)___</b> be a robot cook.', opts: o4('is', 'are', 'will', 'won\'t'), ans: 'C', why: 'Cả đoạn nói về ngôi nhà mơ ước trong tương lai nên dùng <i>there will be</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> I know my dream house is expensive, but I <b>(25)___</b> work hard to make it come true.', opts: o4('mustn\'t', 'shouldn\'t', 'can\'t', 'will'), ans: 'D', why: 'Người viết quyết tâm thực hiện ước mơ nên dùng <i>will</i>. Ba phương án còn lại đều mang nghĩa phủ định, trái hẳn với ý "làm cho ước mơ thành sự thật".' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>Minh is twelve. He often draws pictures of his future house. In his drawing, the house is a big UFO. It will fly above the clouds, so Minh will see the sun every day. There will be five rooms in it: two bedrooms, a kitchen, a living room and a study. Minh will not have a garden, but he will grow flowers and small trees on the roof. There will also be a robot in the house. Its name will be Bibi. Bibi will cook meals, clean the floor and water the plants. Minh\'s mother says the house is only a dream, but Minh says: "Dreams come true when people work hard."<br><br><b>Câu 26.</b> Why will Minh see the sun every day?', opts: o4('Because his house will fly above the clouds.', 'Because his house will have five rooms.', 'Because the robot will clean the windows.', 'Because he will grow flowers on the roof.'), ans: 'A', why: 'Bài viết "It will fly above the clouds, SO Minh will see the sun every day" — bay trên mây thì không bị mây che nắng. Bẫy ở phương án D: trồng hoa trên mái là chi tiết có thật trong bài nhưng không phải nguyên nhân.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> How many rooms will there be in Minh\'s house?', opts: o4('Two.', 'Four.', 'Five.', 'Six.'), ans: 'C', why: 'Bài đọc viết rõ: "There will be five rooms in it".' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> What will Bibi do in the house?', opts: o4('It will fly the house above the clouds.', 'It will cook, clean and water the plants.', 'It will draw pictures of the future house.', 'It will grow flowers and trees on the roof.'), ans: 'B', why: 'Bài đọc liệt kê: "Bibi will cook meals, clean the floor and water the plants".' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> Which statement is NOT true about Minh\'s future house?', opts: o4('It will have a study for Minh.', 'It will move above the clouds.', 'There will be plants on its roof.', 'It will have a garden behind it.'), ans: 'D', why: 'Bài viết "Minh will not have a garden, BUT he will grow flowers and small trees on the roof" — nhà không có vườn. Bẫy nằm ở chỗ vẫn có cây cối, nên học sinh đọc lướt dễ tưởng là có vườn.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 30', pts: 1, text: 'Minh\'s UFO house will fly at 600 kilometres an hour. The distance from Ha Noi to Da Nang is 800 kilometres. How long will the house take to fly there?', opts: o4('1 hour 20 minutes', '1 hour 30 minutes', '2 hours 20 minutes', '48 minutes'), ans: 'A', why: 'Thời gian = 800 : 600 = 4/3 giờ = <b>1 giờ 20 phút</b>. (Chọn 48 phút là lấy 600 : 800 — chia ngược.)' },
  ],
},
/* ═══════════ ĐỀ 11 — OUR GREENER WORLD ═══════════ */
{
  id: 10711, title: 'Đề 11 · Our greener world — reduce, reuse, recycle', time: 60,
  questions: [
    { sec: 'Phát âm', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Choose the word whose final <b>-s</b> is pronounced differently from the others.', opts: o4('bottles', 'plants', 'bags', 'trees'), ans: 'B', why: 'Đuôi -s trong <i>plants</i> đọc /s/ vì đứng sau âm vô thanh /t/. Ba từ còn lại đứng sau âm hữu thanh nên đọc /z/.' },
    { sec: 'Trọng âm', lvl: 'NC', name: 'Câu 2', pts: 1, text: 'Choose the word that has a different stress pattern from the others.', opts: o4('rubbish', 'plastic', 'water', 'pollution'), ans: 'D', why: '<i>Pollution</i> nhấn âm tiết thứ hai (pol-LU-tion) — quy tắc: từ có đuôi "-tion" luôn nhấn vào âm tiết ngay TRƯỚC đuôi. Ba từ còn lại đều nhấn âm tiết đầu.' },
    { sec: 'Phát âm', lvl: 'TH', name: 'Câu 3', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently from the others.', opts: o4('pl<u>a</u>stic', 'p<u>a</u>per', 'w<u>a</u>ste', 's<u>a</u>ve'), ans: 'A', why: 'Chữ "a" trong <i>plastic</i> đọc /æ/; <i>paper, waste, save</i> đều đọc /eɪ/.' },
    { sec: 'Từ vựng môi trường', lvl: 'NB', name: 'Câu 4', pts: 1, text: 'We should put our rubbish in the ___.', opts: o4('fridge', 'wardrobe', 'bin', 'cupboard'), ans: 'C', why: '<i>Bin</i> = thùng rác. Ba từ còn lại là tủ lạnh, tủ quần áo và tủ chén bát.' },
    { sec: 'should / shouldn\'t', lvl: 'TH', name: 'Câu 5', pts: 1, text: 'We ___ turn off the lights when we leave the room.', opts: o4('mustn\'t', 'should', 'shouldn\'t', 'needn\'t'), ans: 'B', why: 'Tắt đèn khi ra khỏi phòng là việc NÊN làm để tiết kiệm điện nên dùng <i>should</i>. Ba phương án còn lại đều mang nghĩa phủ định.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 6', pts: 1, text: 'A family uses 6 plastic bags every day. They decide to use cloth bags instead. How many plastic bags will they save in four weeks?', opts: o4('120', '144', '156', '168'), ans: 'D', why: 'Bốn tuần có 4 × 7 = 28 ngày. Số túi ni lông tiết kiệm được: 6 × 28 = <b>168</b> túi. (Chọn 120 là nhầm bốn tuần thành 20 ngày làm việc.)' },
    { sec: 'Liên từ', lvl: 'NC', name: 'Câu 7', pts: 1, text: 'We should use both sides of our paper, ___ we can save trees, ___ we shouldn\'t throw old notebooks away either.', opts: o4('because – and', 'but – so', 'so – and', 'so – but'), ans: 'C', why: 'Dùng giấy hai mặt là nguyên nhân, cứu được cây là KẾT QUẢ → <i>so</i>. Vế thứ ba nêu thêm một việc nên làm nữa, cùng chiều ý nghĩa, lại có chữ "either" → nối bằng <i>and</i>. Bẫy ở phương án D: <i>but</i> đòi hỏi hai ý trái chiều, trong khi cả hai vế đều là lời khuyên bảo vệ môi trường.' },
    { sec: 'Từ vựng môi trường', lvl: 'NB', name: 'Câu 8', pts: 1, text: 'The word "recycle" means ___.', opts: o4('to make new things from old ones', 'to throw old things away', 'to buy many new things', 'to use less water at home'), ans: 'A', why: '<i>Recycle</i> = tái chế, tức là làm ra đồ mới từ đồ cũ. Phương án D là nghĩa của <i>reduce</i>.' },
    { sec: 'Đếm được / không đếm được', lvl: 'TH', name: 'Câu 9', pts: 1, text: 'There is too ___ rubbish in the river and too ___ fish in it.', opts: o4('many – much', 'much – few', 'much – little', 'many – few'), ans: 'B', why: '<i>Rubbish</i> là danh từ không đếm được → <i>much</i>. <i>Fish</i> ở đây chỉ những con cá đếm được → <i>few</i>. Bẫy ở phương án C: <i>little</i> chỉ dùng với danh từ không đếm được.' },
    { sec: 'Viết lại câu', lvl: 'NC', name: 'Câu 10', pts: 1, text: 'Choose the sentence that has the closest meaning to: "It is a bad idea to throw batteries into the bin."', opts: o4('You should throw batteries into the bin.', 'You can throw batteries into the bin.', 'You must throw batteries into the bin.', 'You shouldn\'t throw batteries into the bin.'), ans: 'D', why: '"It is a bad idea to…" = đó là việc KHÔNG NÊN làm → <i>shouldn\'t</i>. Bẫy ở phương án B: <i>can</i> nói về khả năng hoặc sự cho phép, không phải lời khuyên, nên không diễn đạt được ý "bad idea".' },
    { sec: 'Quá khứ và tương lai', lvl: 'NC', name: 'Câu 11', pts: 1, text: 'Last year our school ___ 2000 trees, and next year we ___ 3000 more.', opts: o4('planted – will plant', 'plants – will plant', 'planted – planted', 'will plant – planted'), ans: 'A', why: '"Last year" là quá khứ → <i>planted</i>; "next year" là tương lai → <i>will plant</i>. Bẫy ở phương án C: chia cả hai vế ở quá khứ là bỏ qua mốc thời gian "next year"; phương án D thì đảo ngược hai mốc.' },
    { sec: 'Từ vựng môi trường', lvl: 'NB', name: 'Câu 12', pts: 1, text: 'Which of these things is made of glass?', opts: o4('a paper bag', 'a plastic straw', 'a milk bottle', 'a cotton shirt'), ans: 'C', why: 'Chai sữa (<i>milk bottle</i>) thường làm bằng thuỷ tinh — <i>glass</i>. Ba vật còn lại làm bằng giấy, nhựa và vải bông.' },
    { sec: 'Dạng từ', lvl: 'TH', name: 'Câu 13', pts: 1, text: 'Air ___ in big cities is a serious problem.', opts: o4('polluted', 'pollute', 'polluting', 'pollution'), ans: 'D', why: 'Chỗ trống đứng sau danh từ "air" và làm chủ ngữ cho động từ "is" nên cần một DANH TỪ: <i>air pollution</i> (ô nhiễm không khí).' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 14', pts: 1, text: 'A shop sells cloth bags at 15000 dong each. For every four bags a customer buys, the shop gives one more bag free. Mrs Lan wants to take home 10 bags. How much does she pay?', opts: o4('100000 dong', '120000 dong', '135000 dong', '150000 dong'), ans: 'B', why: 'Mua 8 túi thì được tặng 2 túi (8 : 4 = 2), tổng cộng vừa đủ 10 túi. Số tiền phải trả: 8 × 15000 = <b>120000 đồng</b>. (Chọn 150000 là mua đủ 10 túi, quên mất phần quà tặng.)' },
    { sec: 'Từ vựng môi trường', lvl: 'NB', name: 'Câu 15', pts: 1, text: 'We can ___ old glass jars to keep pens and pencils.', opts: o4('reuse', 'pollute', 'waste', 'throw'), ans: 'A', why: '<i>Reuse</i> = dùng lại một vật cho mục đích khác, đúng với việc lấy lọ cũ đựng bút.' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 16', pts: 1, text: 'Choose the underlined part that needs correction: <u>Everybody</u> <u>must</u> <u>to protect</u> the environment <u>every day</u>.', opts: o4('Everybody', 'must', 'to protect', 'every day'), ans: 'C', why: 'Sau động từ khuyết thiếu <i>must</i> phải là động từ nguyên thể KHÔNG "to": <i>must protect</i>. Bẫy ở phương án A: <i>everybody</i> tuy mang nghĩa "mọi người" nhưng vẫn là đại từ số ít và ở đây đứng trước <i>must</i> nên hoàn toàn đúng.' },
    { sec: 'Giới từ', lvl: 'TH', name: 'Câu 17', pts: 1, text: 'Plastic bags are bad ___ the environment.', opts: o4('to', 'of', 'with', 'for'), ans: 'D', why: 'Cụm cố định <i>be bad for something</i> = có hại cho cái gì (ngược lại là <i>be good for</i>).' },
    { sec: 'Từ vựng môi trường', lvl: 'NB', name: 'Câu 18', pts: 1, text: 'Which word means "to use less of something"?', opts: o4('reuse', 'reduce', 'recycle', 'repeat'), ans: 'B', why: '<i>Reduce</i> = giảm bớt, dùng ít đi. <i>Reuse</i> là dùng lại, <i>recycle</i> là tái chế.' },
    { sec: 'Giao tiếp', lvl: 'NC', name: 'Câu 19', pts: 1, text: '— "Let\'s clean the beach this Sunday morning." — "___"', opts: o4('That\'s a good idea. I will join you.', 'Yes, I did. The beach was clean.', 'No, it isn\'t. The beach is far away.', 'Not at all. You are very welcome.'), ans: 'A', why: '"Let\'s…" là lời RỦ cùng làm nên phải đáp bằng lời đồng ý hoặc từ chối. Bẫy ở phương án B: "Yes, I did" ở thì quá khứ, trong khi lời rủ hướng tới Chủ nhật sắp tới; phương án D là lời đáp cho câu cảm ơn.' },
    { sec: 'Đếm được / không đếm được', lvl: 'TH', name: 'Câu 20', pts: 1, text: 'Which sentence is correct?', opts: o4('There are much rubbish in the yard.', 'There is many rubbish in the yard.', 'There is a lot of rubbish in the yard.', 'There are a lot of rubbish in the yard.'), ans: 'C', why: '<i>Rubbish</i> là danh từ không đếm được nên đi với động từ số ít <i>is</i> và lượng từ <i>a lot of</i> hoặc <i>much</i> — không dùng <i>many</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>Our school has a green club. The club <b>(21)___</b> every Saturday afternoon. Last month the members collected old paper and plastic bottles <b>(22)___</b> sold them to a recycling centre. With that money they bought young trees <b>(23)___</b> the school garden. Our teacher says that every student <b>(24)___</b> do one green action every day: turn off the lights, close the tap, or use a cloth bag. These actions are small, <b>(25)___</b> they can change the world.<br><br><b>Câu 21.</b> The club <b>(21)___</b> every Saturday afternoon.', opts: o4('meet', 'is meeting', 'met', 'meets'), ans: 'D', why: '"Every Saturday afternoon" chỉ thói quen lặp lại nên dùng hiện tại đơn; chủ ngữ "The club" là số ít → <i>meets</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> … the members collected old paper and plastic bottles <b>(22)___</b> sold them to a recycling centre.', opts: o4('but', 'and', 'so', 'because'), ans: 'B', why: 'Hai hành động nối tiếp nhau, cùng chiều ý nghĩa (thu gom rồi bán) nên nối bằng <i>and</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> With that money they bought young trees <b>(23)___</b> the school garden.', opts: o4('for', 'to', 'at', 'of'), ans: 'A', why: 'Mua cây ĐỂ DÀNH CHO vườn trường nên dùng <i>for</i>: <i>buy something for somewhere/somebody</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> … every student <b>(24)___</b> do one green action every day: turn off the lights, close the tap, or use a cloth bag.', opts: o4('mustn\'t', 'can\'t', 'should', 'shouldn\'t'), ans: 'C', why: 'Ba ví dụ đi sau dấu hai chấm đều là những việc TỐT, nên chỗ trống phải mang nghĩa khuyên NÊN làm: <i>should</i>. Bẫy ở <i>mustn\'t</i>: nhiều học sinh thấy lời thầy cô là nghĩ tới sự bắt buộc mà quên rằng "mustn\'t" nghĩa là CẤM.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> These actions are small, <b>(25)___</b> they can change the world.', opts: o4('so', 'and', 'because', 'but'), ans: 'D', why: '"Nhỏ bé" và "thay đổi được thế giới" là hai ý TRÁI NGƯỢC nên nối bằng <i>but</i>. Bẫy ở <i>so</i>: dùng "so" sẽ thành "vì nhỏ nên thay đổi được thế giới" — hoàn toàn vô lí.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>Green Street is a small street in Hue. Five years ago it was dirty. People threw rubbish on the ground and the air smelled bad. Then Mrs Hoa, an old teacher, had an idea. Every Sunday morning she cleaned the street with her grandchildren. Soon other families joined them. They planted flowers in front of every house and put three big bins at the end of the street: one for paper, one for plastic and one for food waste. Now Green Street is the cleanest street in the area, and last year it won a prize from the city. Mrs Hoa says: "One person cannot do everything, but everyone can do something."<br><br><b>Câu 26.</b> How often did Mrs Hoa clean the street?', opts: o4('Every evening.', 'Every Sunday morning.', 'Twice a week.', 'Every two weeks.'), ans: 'B', why: 'Bài đọc viết: "Every Sunday morning she cleaned the street with her grandchildren".' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> How many bins are there at the end of the street?', opts: o4('Three.', 'Two.', 'Five.', 'One.'), ans: 'A', why: 'Bài đọc nói có "three big bins": một cho giấy, một cho nhựa và một cho rác thức ăn.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> What can we learn from Mrs Hoa\'s words at the end of the passage?', opts: o4('Only teachers can protect the environment.', 'One person must do all the work alone.', 'Every person can help in a small way.', 'Cleaning a street takes only one day.'), ans: 'C', why: 'Câu "One person cannot do everything, but everyone can do something" nhấn mạnh rằng ai cũng góp được một phần nhỏ. Bẫy ở phương án B: đó chính là điều bà Hoa PHỦ ĐỊNH ở nửa đầu câu nói.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> The word "prize" in the passage means ___.', opts: o4('a kind of rubbish bin', 'a reward for good work', 'a name of a new street', 'a group of families'), ans: 'B', why: '<i>Prize</i> = giải thưởng — phần thưởng cho việc làm tốt; ở đây là phần thưởng thành phố trao cho con phố sạch.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 30', pts: 1, text: 'Green Street has 20 houses. Each family puts out 3 kilos of food waste a week. The city collects food waste once every two weeks. How many kilos does the city collect from the street each time?', opts: o4('60 kilos', '90 kilos', '100 kilos', '120 kilos'), ans: 'D', why: 'Mỗi tuần cả phố thải ra 20 × 3 = 60 kg. Hai tuần mới thu một lần nên mỗi lần thu 60 × 2 = <b>120 kg</b>. (Chọn 60 kg là quên nhân với hai tuần.)' },
  ],
},

/* ═══════════ ĐỀ 12 — ROBOTS ═══════════ */
{
  id: 10712, title: 'Đề 12 · Robots — can/could, will be able to', time: 60,
  questions: [
    { sec: 'Phát âm', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently from the others: r<u>o</u>bot — <u>o</u>pen — d<u>o</u> — h<u>o</u>me', opts: o4('robot', 'open', 'do', 'home'), ans: 'C', why: 'Chữ "o" trong <i>do</i> đọc /uː/; <i>robot, open, home</i> đều có âm đôi /əʊ/.' },
    { sec: 'Phát âm', lvl: 'TH', name: 'Câu 2', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently from the others.', opts: o4('ma<u>ch</u>ine', '<u>ch</u>ildren', 'tea<u>ch</u>', '<u>ch</u>air'), ans: 'A', why: '"ch" trong <i>machine</i> đọc /ʃ/ (giống "sh"); ba từ còn lại đều đọc /tʃ/.' },
    { sec: 'Trọng âm', lvl: 'NB', name: 'Câu 3', pts: 1, text: 'Choose the word that has a different stress pattern from the others.', opts: o4('doctor', 'teacher', 'worker', 'machine'), ans: 'D', why: '<i>Machine</i> nhấn âm tiết thứ hai; ba từ còn lại đều nhấn âm tiết đầu.' },
    { sec: 'can / could', lvl: 'NC', name: 'Câu 4', pts: 1, text: 'Ten years ago this robot ___ only walk, but now it ___ talk and dance.', opts: o4('can – could', 'could – can', 'can – can', 'could – could'), ans: 'B', why: '"Ten years ago" là mốc quá khứ → <i>could</i>; "now" là hiện tại → <i>can</i>. Bẫy ở phương án A: đảo ngược hai thì; bẫy ở D: dùng <i>could</i> cho cả vế "now" là sai thì.' },
    { sec: 'will be able to', lvl: 'NC', name: 'Câu 5', pts: 1, text: 'Choose the sentence that has the closest meaning to: "Robots will be able to build houses in 2050."', opts: o4('Robots must build houses in 2050.', 'Robots cannot build houses in 2050.', 'Robots will know how to build houses in 2050.', 'Robots built houses in 2050.'), ans: 'C', why: '<i>will be able to</i> diễn tả KHẢ NĂNG trong tương lai, tương đương "sẽ biết cách / sẽ làm được". Bẫy ở phương án A: <i>must</i> nói về sự bắt buộc chứ không phải khả năng; phương án D lại chia ở quá khứ trong khi năm 2050 chưa tới.' },
    { sec: 'Câu hỏi với can', lvl: 'TH', name: 'Câu 6', pts: 1, text: '___ your robot make coffee? — Yes, it can.', opts: o4('Can', 'Does', 'Is', 'Will'), ans: 'A', why: 'Câu trả lời "Yes, it can" cho biết câu hỏi phải bắt đầu bằng <i>Can</i>.' },
    { sec: 'Từ vựng robot', lvl: 'NB', name: 'Câu 7', pts: 1, text: 'Which kind of robot helps doctors in a hospital?', opts: o4('a home robot', 'a teaching robot', 'a space robot', 'a doctor robot'), ans: 'D', why: 'Robot làm việc trong bệnh viện, giúp bác sĩ được gọi là <i>doctor robot</i>.' },
    { sec: 'Liên từ', lvl: 'TH', name: 'Câu 8', pts: 1, text: 'Robots can do the housework, ___ they cannot feel happy or sad.', opts: o4('so', 'but', 'because', 'and'), ans: 'B', why: 'Hai vế đối lập (làm được việc nhà / không có cảm xúc) nên nối bằng <i>but</i>.' },
    { sec: 'can / could', lvl: 'NC', name: 'Câu 9', pts: 1, text: 'Two years ago my grandmother ___ use a smartphone, but my little brother ___ use one when he was four.', opts: o4('can\'t – can', 'couldn\'t – can', 'couldn\'t – could', 'didn\'t can – could'), ans: 'C', why: 'Cả hai vế đều nói về quá khứ ("Two years ago" và "when he was four") nên phải dùng <i>couldn\'t</i> và <i>could</i>. Bẫy ở phương án B: vế sau có "was" nên không thể dùng <i>can</i> ở hiện tại; bẫy ở D: sau <i>didn\'t</i> không bao giờ có động từ khuyết thiếu.' },
    { sec: 'Động từ nguyên thể', lvl: 'NB', name: 'Câu 10', pts: 1, text: 'Robots can help us ___ the house.', opts: o4('clean', 'cleans', 'cleaned', 'to cleaning'), ans: 'A', why: 'Cấu trúc <i>help somebody (to) do something</i> — dùng động từ nguyên thể <i>clean</i>.' },
    { sec: 'will be able to', lvl: 'TH', name: 'Câu 11', pts: 1, text: 'In fifty years, people ___ travel to Mars easily.', opts: o4('can to', 'will can', 'are able', 'will be able to'), ans: 'D', why: 'Không bao giờ có hai động từ khuyết thiếu đứng cạnh nhau ("will can" sai). Khả năng trong tương lai diễn đạt bằng <i>will be able to</i>.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 12', pts: 1, text: 'A robot can wash 8 plates in one minute. A person can wash 3 plates in one minute. There are 48 plates. How many minutes more does the person need than the robot?', opts: o4('6 minutes', '10 minutes', '16 minutes', '22 minutes'), ans: 'B', why: 'Robot cần 48 : 8 = 6 phút; người cần 48 : 3 = 16 phút. Chênh lệch: 16 − 6 = <b>10 phút</b>. (Chọn 16 phút là chỉ tính thời gian của người mà quên trừ đi thời gian của robot.)' },
    { sec: 'Từ vựng robot', lvl: 'NB', name: 'Câu 13', pts: 1, text: 'Which word means "a machine that can do work like a person"?', opts: o4('robot', 'remote', 'rocket', 'racket'), ans: 'A', why: '<i>Robot</i> = người máy. <i>Remote</i> là điều khiển, <i>rocket</i> là tên lửa, <i>racket</i> là cái vợt.' },
    { sec: 'Hiện tại đơn', lvl: 'TH', name: 'Câu 14', pts: 1, text: 'Robots ___ in factories all over the world today.', opts: o4('works', 'worked', 'work', 'working'), ans: 'C', why: 'Chủ ngữ "Robots" là số nhiều và có "today" (sự thật hiện tại) nên dùng <i>work</i>, không thêm -s.' },
    { sec: 'can + liên từ', lvl: 'NC', name: 'Câu 15', pts: 1, text: 'My father bought a robot last week. It ___ speak English, ___ it cannot speak Vietnamese yet.', opts: o4('can – and', 'could – but', 'can – so', 'can – but'), ans: 'D', why: 'Con robot đang ở trong nhà nên khả năng của nó là ở HIỆN TẠI → <i>can</i> (dù câu trước ở quá khứ). Hai vế trái chiều (nói được tiếng Anh / chưa nói được tiếng Việt) nên nối bằng <i>but</i>. Bẫy ở phương án B: thấy "bought" ở quá khứ nên vội chọn <i>could</i>.' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 16', pts: 1, text: 'Choose the underlined part that needs correction: Robots <u>in the future</u> <u>will can</u> <u>teach</u> children <u>at school</u>.', opts: o4('in the future', 'will can', 'teach', 'at school'), ans: 'B', why: 'Hai động từ khuyết thiếu không đứng liền nhau, nên "will can" phải sửa thành <i>will be able to</i>. Các phần còn lại đều đúng: sau <i>will</i> là động từ nguyên thể <i>teach</i>, và <i>at school</i> là cụm giới từ chuẩn.' },
    { sec: 'Câu hỏi Wh-', lvl: 'NB', name: 'Câu 17', pts: 1, text: '___ can your robot do? — It can carry heavy things.', opts: o4('What', 'Who', 'Where', 'When'), ans: 'A', why: 'Hỏi về hành động/việc làm (sự vật) nên dùng <i>What</i>.' },
    { sec: 'can', lvl: 'TH', name: 'Câu 18', pts: 1, text: 'Which sentence is correct?', opts: o4('My robot can to sing a song.', 'My robot cans sing a song.', 'My robot can sing a song.', 'My robot can singing a song.'), ans: 'C', why: 'Sau <i>can</i> là động từ nguyên thể không "to"; bản thân <i>can</i> không bao giờ thêm -s.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 19', pts: 1, text: 'A factory has 5 robots. Each robot makes 24 toys an hour and the factory works 8 hours a day. How many toys do the robots make in one day?', opts: o4('600', '840', '900', '960'), ans: 'D', why: 'Một giờ cả năm robot làm 5 × 24 = 120 đồ chơi. Trong 8 giờ: 120 × 8 = <b>960</b> đồ chơi. (Chọn 600 là nhân 5 × 120 mà quên số giờ.)' },
    { sec: 'Giao tiếp', lvl: 'NC', name: 'Câu 20', pts: 1, text: '— "Do you think robots will teach us in the future?" — "___"', opts: o4('Yes, they did. It was very interesting.', 'I don\'t think so. We need real teachers.', 'No, they aren\'t. They are in the factory.', 'Yes, please. That is very kind of you.'), ans: 'B', why: '"Do you think…?" hỏi Ý KIẾN về tương lai nên phải đáp bằng "I think so / I don\'t think so" kèm lí do. Bẫy ở phương án A: "Yes, they did" ở quá khứ, mâu thuẫn với "in the future"; phương án D là lời nhận một lời mời giúp đỡ.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>Robots are not new. The first simple robots <b>(21)___</b> in factories more than fifty years ago. At that time they could only move their arms, <b>(22)___</b> they could not see or hear. Today\'s robots are much <b>(23)___</b>. Some of them can play football and some can talk with people in many languages. Scientists say that in twenty years robots <b>(24)___</b> able to do most of the housework. But a robot <b>(25)___</b> never be able to love its owner like a dog or a cat.<br><br><b>Câu 21.</b> The first simple robots <b>(21)___</b> in factories more than fifty years ago.', opts: o4('worked', 'work', 'works', 'working'), ans: 'A', why: 'Có mốc "more than fifty years ago" nên dùng quá khứ đơn: <i>worked</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> At that time they could only move their arms, <b>(22)___</b> they could not see or hear.', opts: o4('so', 'because', 'and', 'or'), ans: 'C', why: 'Hai ý cùng chiều, cùng mô tả sự hạn chế của robot thời xưa, nên nối bằng <i>and</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> Today\'s robots are much <b>(23)___</b>.', opts: o4('smarter than', 'the smartest', 'more smart', 'smarter'), ans: 'D', why: 'Câu ngầm so sánh robot ngày nay với robot ngày xưa, nhưng KHÔNG viết ra vế "than…" nên chỉ dùng dạng so sánh hơn đứng một mình: <i>much smarter</i>. Bẫy ở phương án A: đã có "than" thì bắt buộc phải có đối tượng đi kèm ngay sau; phương án C sai dạng vì <i>smart</i> là tính từ ngắn.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> Scientists say that in twenty years robots <b>(24)___</b> able to do most of the housework.', opts: o4('are', 'will be', 'can', 'were'), ans: 'B', why: '"In twenty years" là tương lai nên dùng <i>will be able to</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> But a robot <b>(25)___</b> never be able to love its owner like a dog or a cat.', opts: o4('can', 'must', 'will', 'should'), ans: 'C', why: 'Trước cụm "be able to" chỉ có thể dùng <i>will</i>; các động từ khuyết thiếu khác không kết hợp được với "be able to" trong câu này.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>Sophia is a famous robot. Scientists in Hong Kong made her in 2015. She looks like a woman: she has a face, two arms and two hands. Sophia can see people with her camera eyes and she can remember their faces. She can answer questions in English, and she can make more than sixty different faces, so she can look happy, sad or surprised. Sophia cannot walk very well, and she cannot run at all. In 2017 Saudi Arabia gave her a passport. Many people love Sophia, but some are afraid of robots like her. They think that robots will take our jobs one day.<br><br><b>Câu 26.</b> When did scientists make Sophia?', opts: o4('In 2015.', 'In 2017.', 'In 2005.', 'In 2020.'), ans: 'A', why: 'Bài đọc viết: "Scientists in Hong Kong made her in 2015". Năm 2017 là năm cô nhận hộ chiếu.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> Why can Sophia look happy or sad?', opts: o4('Because she can remember people\'s faces.', 'Because she can answer many questions.', 'Because scientists gave her a passport.', 'Because she can make many different faces.'), ans: 'D', why: 'Bài viết "she can make more than sixty different faces, SO she can look happy, sad or surprised" — chữ "so" chỉ rõ nguyên nhân. Bẫy ở phương án A: "remember faces" (nhớ khuôn mặt người khác) và "make faces" (tạo biểu cảm) dùng chung từ "faces" nhưng khác hẳn nghĩa.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> Which statement is NOT true about Sophia?', opts: o4('She can speak English with people.', 'She can run faster than a person.', 'She has a passport from Saudi Arabia.', 'She cannot walk very well.'), ans: 'B', why: 'Bài viết rõ "she cannot run at all" nên nói cô chạy nhanh hơn người là SAI. Bẫy ở phương án D: câu này nghe như một nhược điểm nên dễ bị chọn nhầm là "không đúng", nhưng nó lại đúng y hệt bài đọc.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> The word "afraid" in the passage is closest in meaning to ___.', opts: o4('frightened', 'excited', 'pleased', 'interested'), ans: 'A', why: '<i>Afraid</i> = sợ hãi, đồng nghĩa với <i>frightened</i>. Ba từ còn lại đều mang sắc thái tích cực.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 30', pts: 1, text: 'A new robot can make 180 different faces and it needs 2 seconds for each face. How long does it need to show all of its faces?', opts: o4('2 minutes', '3 minutes', '6 minutes', '12 minutes'), ans: 'C', why: 'Tổng thời gian: 180 × 2 = 360 giây = <b>6 phút</b>. (Chọn 3 phút là quên nhân với 2 giây mỗi khuôn mặt.)' },
  ],
},


/* ═══════════ ĐỀ 13 — ÔN TẬP CÁC THÌ HIỆN TẠI ═══════════ */
{
  id: 10713, title: 'Đề 13 · Ôn tập các thì hiện tại — hiện tại đơn ↔ hiện tại tiếp diễn', time: 60,
  questions: [
    { sec: 'Phát âm', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Choose the word whose final <b>-s/-es</b> is pronounced differently from the others.', opts: o4('cooks', 'watches', 'sleeps', 'writes'), ans: 'B', why: 'Đuôi -es trong <i>watches</i> đọc /ɪz/ vì đứng sau âm gió /tʃ/. Ba từ còn lại kết thúc bằng âm vô thanh /k/, /p/, /t/ nên -s đọc /s/.' },
    { sec: 'Phát âm', lvl: 'TH', name: 'Câu 2', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently from the others: r<u>ea</u>ding — s<u>ea</u>son — br<u>ea</u>kfast — t<u>ea</u>cher', opts: o4('reading', 'season', 'breakfast', 'teacher'), ans: 'C', why: 'Chữ "ea" trong <i>breakfast</i> đọc /e/; trong <i>reading, season, teacher</i> đều đọc /iː/.' },
    { sec: 'Trọng âm', lvl: 'NB', name: 'Câu 3', pts: 1, text: 'Choose the word that has a different stress pattern from the others.', opts: o4('enjoy', 'watching', 'open', 'busy'), ans: 'A', why: '<i>Enjoy</i> nhấn âm tiết thứ hai (en-JOY); <i>watching, open, busy</i> đều nhấn âm tiết thứ nhất.' },
    { sec: 'Hai thì hiện tại', lvl: 'NC', name: 'Câu 4', pts: 1, text: 'Every Sunday my sister ___ to the market, but look — she ___ the flowers in the garden now.', opts: o4('goes – waters', 'is going – waters', 'goes – is watering', 'is going – is watering'), ans: 'C', why: 'Vế đầu có "Every Sunday" — thói quen lặp lại → hiện tại đơn <i>goes</i>. Vế sau có "look" và "now" — việc đang diễn ra → hiện tại tiếp diễn <i>is watering</i>. Bẫy ở phương án B và D: học sinh thấy chữ "now" rồi chia cả hai vế sang tiếp diễn, quên rằng mỗi vế có dấu hiệu thời gian riêng.' },
    { sec: 'Hiện tại tiếp diễn', lvl: 'TH', name: 'Câu 5', pts: 1, text: 'Listen! The baby ___ in the next room.', opts: o4('is crying', 'cries', 'cry', 'are crying'), ans: 'A', why: '"Listen!" là dấu hiệu của hiện tại tiếp diễn; "the baby" số ít nên dùng <i>is crying</i>.' },
    { sec: 'Hiện tại đơn', lvl: 'NB', name: 'Câu 6', pts: 1, text: 'My father usually ___ coffee in the morning.', opts: o4('drink', 'is drinking', 'drinking', 'drinks'), ans: 'D', why: 'Có trạng từ tần suất "usually" → hiện tại đơn; chủ ngữ "my father" ngôi thứ ba số ít nên thêm -s: <i>drinks</i>.' },
    { sec: 'Động từ trạng thái', lvl: 'NC', name: 'Câu 7', pts: 1, text: 'Which sentence is correct?', opts: o4('They are not watching TV at the moment.', 'I am liking this song very much.', 'She is wanting a new bike now.', 'We are not understanding the lesson.'), ans: 'A', why: 'Các động từ chỉ trạng thái <i>like, want, understand</i> không dùng ở thì tiếp diễn, nên B, C, D đều sai; phải nói "I like…", "She wants…", "We don\'t understand…". Chỉ câu A dùng động từ hành động <i>watch</i> với "at the moment" nên đúng.' },
    { sec: 'Câu hỏi hiện tại đơn', lvl: 'TH', name: 'Câu 8', pts: 1, text: '___ your sister do her homework in the evening?', opts: o4('Do', 'Is', 'Are', 'Does'), ans: 'D', why: 'Động từ chính là "do" (làm bài) ở thì hiện tại đơn, chủ ngữ "your sister" số ít nên trợ động từ là <i>Does</i>.' },
    { sec: 'Hiện tại đơn', lvl: 'NB', name: 'Câu 9', pts: 1, text: 'They ___ in Ha Noi with their grandparents.', opts: o4('lives', 'is living', 'live', 'living'), ans: 'C', why: 'Chủ ngữ "They" số nhiều nên động từ giữ nguyên thể: <i>live</i>.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 10', pts: 1, text: 'Mai\'s online English class starts at 19.30 and lasts 90 minutes. After the class she always does her homework for 30 minutes. What time does she finish her homework?', opts: o4('21.00', '20.30', '21.30', '22.00'), ans: 'C', why: 'Lớp học kết thúc lúc 19.30 + 90 phút = 21.00. Làm bài thêm 30 phút nữa → <b>21.30</b>. Chọn 21.00 là quên phần làm bài tập; chọn 20.30 là cộng nhầm 90 phút thành 60 phút.' },
    { sec: 'Dạng V-ing', lvl: 'NC', name: 'Câu 11', pts: 1, text: 'Choose the word with the correct <b>-ing</b> form.', opts: o4('writeing', 'siting', 'swiming', 'running'), ans: 'D', why: '<i>Run</i> kết thúc bằng một nguyên âm + một phụ âm và nhấn âm cuối nên phải gấp đôi phụ âm: <i>running</i>. Cùng quy tắc đó, "sit" và "swim" phải thành <i>sitting, swimming</i> (B, C viết thiếu một phụ âm). "Write" bỏ -e trước khi thêm -ing → <i>writing</i>, nên A sai.' },
    { sec: 'Hiện tại tiếp diễn', lvl: 'NB', name: 'Câu 12', pts: 1, text: 'Now my mother ___ dinner in the kitchen.', opts: o4('cooks', 'is cooking', 'cook', 'cooking'), ans: 'B', why: '"Now" là dấu hiệu của hiện tại tiếp diễn; chủ ngữ số ít nên dùng <i>is cooking</i>.' },
    { sec: 'Nhận diện lỗi', lvl: 'NC', name: 'Câu 13', pts: 1, text: 'Which sentence is NOT correct?', opts: o4('At the moment they are having lunch.', 'She goes to school by bus every day.', 'We are usually watching cartoons on Sunday.', 'He is doing his homework now.'), ans: 'C', why: 'Trạng từ tần suất "usually" đi với thói quen nên phải dùng hiện tại đơn: "We usually watch cartoons on Sunday". Bẫy ở đây là học sinh thấy dạng "are + V-ing" quen mắt nên tưởng đúng; ba câu còn lại đều khớp dấu hiệu thời gian ("at the moment", "every day", "now").' },
    { sec: 'Hiện tại tiếp diễn', lvl: 'TH', name: 'Câu 14', pts: 1, text: 'Look! It ___. Take your umbrella.', opts: o4('rains', 'is raining', 'rain', 'rained'), ans: 'B', why: '"Look!" báo hiệu sự việc đang xảy ra ngay lúc nói → <i>is raining</i>.' },
    { sec: 'Từ để hỏi', lvl: 'NB', name: 'Câu 15', pts: 1, text: '___ is your brother doing? — He is playing chess.', opts: o4('What', 'Where', 'When', 'Who'), ans: 'A', why: 'Câu trả lời cho biết hành động ("playing chess") nên phải hỏi bằng <i>What</i>.' },
    { sec: 'Trạng từ tần suất', lvl: 'TH', name: 'Câu 16', pts: 1, text: 'My best friend ___ late for school.', opts: o4('never is', 'is never', 'is not never', 'never be'), ans: 'B', why: 'Với động từ <i>to be</i>, trạng từ tần suất đứng SAU động từ: <i>is never</i>. Phương án C dùng hai lần phủ định, phương án D không chia động từ.' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 17', pts: 1, text: 'Choose the underlined part that needs correction: My <u>friends</u> and I <u>am playing</u> badminton <u>in</u> the school yard <u>now</u>.', opts: o4('friends', 'am playing', 'in', 'now'), ans: 'B', why: 'Chủ ngữ là "My friends and I" tức là "we" (số nhiều) nên phải dùng <i>are playing</i>. Bẫy là chữ "I" đứng ngay trước động từ khiến học sinh chia theo "I am". Ba phần còn lại đều đúng.' },
    { sec: 'Hiện tại đơn', lvl: 'NB', name: 'Câu 18', pts: 1, text: 'She ___ her teeth twice a day.', opts: o4('brush', 'brushs', 'brushes', 'is brushing'), ans: 'C', why: 'Động từ tận cùng bằng -sh thêm -es ở ngôi thứ ba số ít: <i>brushes</i>.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 19', pts: 1, text: 'A notebook costs 12000 dong and a pen costs 8000 dong. Lan buys three notebooks and two pens. How much does she pay?', opts: o4('52000 dong', '48000 dong', '56000 dong', '44000 dong'), ans: 'A', why: 'Ba quyển vở: 3 × 12000 = 36000 đồng. Hai cái bút: 2 × 8000 = 16000 đồng. Tổng cộng <b>52000 đồng</b>. Chọn 44000 là nhầm mua hai vở ba bút.' },
    { sec: 'Câu hỏi tần suất', lvl: 'TH', name: 'Câu 20', pts: 1, text: 'How often ___ you play sports? — Three times a week.', opts: o4('do', 'does', 'are', 'is'), ans: 'A', why: 'Câu hỏi ở hiện tại đơn với chủ ngữ "you" nên trợ động từ là <i>do</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>Hi! My name is Minh. I <b>(21)___</b> in a small town near Da Nang. Every morning my mother <b>(22)___</b> breakfast for the family at six o\'clock. My sister and I <b>(23)___</b> to school at half past six. Today is Saturday, so we don\'t go to school. Look! My sister <b>(24)___</b> her bike in the yard, and I <b>(25)___</b> this letter to you at my desk.<br><br><b>Câu 21.</b> I <b>(21)___</b> in a small town near Da Nang.', opts: o4('lives', 'live', 'am living', 'living'), ans: 'B', why: 'Chủ ngữ "I" nên động từ giữ nguyên thể <i>live</i>, không thêm -s.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> Every morning my mother <b>(22)___</b> breakfast for the family at six o\'clock.', opts: o4('cook', 'is cooking', 'cooks', 'are cooking'), ans: 'C', why: 'Cụm "Every morning" báo hiệu việc lặp lại hằng ngày → hiện tại đơn, và "my mother" là ngôi thứ ba số ít nên thêm -s: <i>cooks</i>. Bẫy ở phương án B: đoạn văn có chỗ dùng tiếp diễn nên học sinh dễ chọn "is cooking", nhưng mốc "every morning" loại bỏ khả năng này.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> My sister and I <b>(23)___</b> to school at half past six.', opts: o4('goes', 'go', 'are going', 'is going'), ans: 'B', why: 'Chủ ngữ "My sister and I" là số nhiều, lại nói về giờ giấc hằng ngày nên dùng hiện tại đơn <i>go</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> Look! My sister <b>(24)___</b> her bike in the yard.', opts: o4('rides', 'is riding', 'ride', 'riding'), ans: 'B', why: 'Câu trước cho biết "Today is Saturday" và câu này mở đầu bằng "Look!" — sự việc đang xảy ra trước mắt → <i>is riding</i>. Phương án A đúng ngữ pháp nhưng sai ngữ cảnh: "rides" chỉ thói quen, không hợp với "Look!".' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> … and I <b>(25)___</b> this letter to you at my desk.', opts: o4('write', 'writes', 'writing', 'am writing'), ans: 'D', why: 'Minh đang viết thư ngay lúc này nên dùng hiện tại tiếp diễn với chủ ngữ "I": <i>am writing</i>.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>Mr Hung is a farmer in Thai Binh. He gets up at half past four every morning and goes to the rice field at five. He works there until eleven o\'clock, then he comes home for lunch. In the afternoon he takes care of his chickens and ducks. His wife, Mrs Lan, sells vegetables at the market from six to ten in the morning. They have two children. At the moment the children are on holiday, so they are helping their parents on the farm. In the evening the whole family watches TV together.<br><br><b>Câu 26.</b> What time does Mr Hung get up?', opts: o4('At 4.30.', 'At 5.00.', 'At 11.00.', 'At 6.00.'), ans: 'A', why: '"He gets up at half past four" nghĩa là 4 giờ 30 phút.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> What does Mrs Lan do?', opts: o4('She works in a rice field.', 'She teaches at a school.', 'She sells vegetables.', 'She looks after ducks.'), ans: 'C', why: 'Bài đọc viết rõ "Mrs Lan sells vegetables at the market". Việc chăm gà vịt là của ông Hùng.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> Which sentence is true about the children?', opts: o4('They go to school every day now.', 'They work at the market with their mother.', 'They are watching TV in the morning.', 'They are not at school these days.'), ans: 'D', why: 'Câu "the children are on holiday" cho biết các em đang nghỉ, tức là những ngày này không đến trường → D đúng và A sai. B sai vì các em giúp bố mẹ ở trang trại chứ không ra chợ; C sai vì cả nhà xem TV vào buổi tối.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> How many hours does Mr Hung work in the rice field every morning?', opts: o4('Six hours.', 'Five hours.', 'Seven hours.', 'Four hours.'), ans: 'A', why: 'Ông ra đồng lúc 5 giờ và làm đến 11 giờ: 11 − 5 = <b>6 giờ</b>. Chọn "Seven hours" là tính nhầm từ lúc ngủ dậy (4.30).' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 30', pts: 1, text: '<b>Câu 30.</b> Which information is NOT mentioned in the passage?', opts: o4('The time Mrs Lan starts selling vegetables.', 'The number of children in the family.', 'What Mr Hung does in the afternoon.', 'The names of the two children.'), ans: 'D', why: 'Bài chỉ nói "They have two children" mà không nêu tên các em → D không được nhắc đến. Giờ bà Lan bán hàng ("from six"), số con ("two children") và việc buổi chiều ("takes care of his chickens and ducks") đều có trong bài.' },
  ],
},

/* ═══════════ ĐỀ 14 — ÔN TẬP THÌ QUÁ KHỨ VÀ TƯƠNG LAI ═══════════ */
{
  id: 10714, title: 'Đề 14 · Ôn tập quá khứ và tương lai — past simple, will', time: 60,
  questions: [
    { sec: 'Phát âm', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Choose the word whose final <b>-ed</b> is pronounced differently from the others.', opts: o4('watched', 'stopped', 'wanted', 'washed'), ans: 'C', why: 'Đuôi -ed trong <i>wanted</i> đọc /ɪd/ vì gốc từ kết thúc bằng /t/. Ba từ còn lại kết thúc bằng âm vô thanh nên -ed đọc /t/.' },
    { sec: 'Trọng âm', lvl: 'NC', name: 'Câu 2', pts: 1, text: 'Choose the word that has a different stress pattern from the others.', opts: o4('tomorrow', 'yesterday', 'holiday', 'festival'), ans: 'A', why: '<i>Tomorrow</i> nhấn âm tiết thứ hai (to-MOR-row); <i>yesterday, holiday, festival</i> đều ba âm tiết nhưng nhấn âm tiết thứ nhất. Bẫy là học sinh thấy cả bốn từ đều ba âm tiết nên đoán bừa; phải nhớ riêng trọng âm của <i>tomorrow</i>.' },
    { sec: 'Phát âm', lvl: 'TH', name: 'Câu 3', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently from the others: w<u>e</u>nt — s<u>e</u>nt — m<u>e</u>t — m<u>e</u>', opts: o4('went', 'sent', 'met', 'me'), ans: 'D', why: 'Chữ "e" trong <i>me</i> đọc /iː/; trong <i>went, sent, met</i> đều đọc /e/.' },
    { sec: 'Quá khứ đơn', lvl: 'NB', name: 'Câu 4', pts: 1, text: 'Last night I ___ to bed at ten o\'clock.', opts: o4('go', 'went', 'goes', 'going'), ans: 'B', why: '"Last night" là dấu hiệu quá khứ đơn; <i>go</i> là động từ bất quy tắc, quá khứ là <i>went</i>.' },
    { sec: 'Tương lai đơn', lvl: 'TH', name: 'Câu 5', pts: 1, text: 'She ___ to the zoo with her cousins tomorrow.', opts: o4('will go', 'goes', 'went', 'going'), ans: 'A', why: '"Tomorrow" là dấu hiệu tương lai nên dùng <i>will + V nguyên thể</i>.' },
    { sec: 'Quá khứ đơn', lvl: 'NC', name: 'Câu 6', pts: 1, text: 'We ___ at home last Sunday because it ___ heavily all day.', opts: o4('stayed – rain', 'stay – rained', 'stayed – rained', 'will stay – rains'), ans: 'C', why: 'Mốc "last Sunday" chi phối CẢ HAI vế nên cả hai động từ đều phải ở quá khứ: <i>stayed – rained</i>. Bẫy ở A và B là chỉ chia quá khứ cho một vế rồi để vế kia ở hiện tại.' },
    { sec: 'Câu hỏi quá khứ', lvl: 'NB', name: 'Câu 7', pts: 1, text: '___ you watch the match yesterday? — Yes, I did.', opts: o4('Do', 'Did', 'Will', 'Are'), ans: 'B', why: 'Câu trả lời "Yes, I did" cho biết trợ động từ là <i>Did</i> (quá khứ đơn).' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 8', pts: 1, text: 'Today is Friday 12 June. Nam will come back from Hue in five days. On which day of the week will he come back?', opts: o4('Tuesday', 'Thursday', 'Monday', 'Wednesday'), ans: 'D', why: 'Từ thứ Sáu ngày 12 cộng thêm 5 ngày là ngày 17, và thứ trong tuần chạy: 13 thứ Bảy, 14 Chủ nhật, 15 thứ Hai, 16 thứ Ba, 17 <b>thứ Tư</b>. Chọn "Tuesday" là đếm thiếu một ngày.' },
    { sec: 'Nhận diện câu đúng', lvl: 'NC', name: 'Câu 9', pts: 1, text: 'Which sentence is correct?', opts: o4('They will visit us next week.', 'He didn\'t went to school yesterday.', 'She will goes home soon.', 'We buyed some books last week.'), ans: 'A', why: 'Sau <i>will</i> luôn là động từ nguyên thể nên A đúng và C sai. B sai vì sau <i>didn\'t</i> phải dùng nguyên thể "go". D sai vì <i>buy</i> là động từ bất quy tắc, quá khứ là <i>bought</i> chứ không thêm -ed.' },
    { sec: 'Quá khứ đơn', lvl: 'TH', name: 'Câu 10', pts: 1, text: 'My father ___ a new car last month.', opts: o4('buys', 'bought', 'will buy', 'buying'), ans: 'B', why: '"Last month" là mốc quá khứ; dạng quá khứ của <i>buy</i> là <i>bought</i>.' },
    { sec: 'Động từ bất quy tắc', lvl: 'NB', name: 'Câu 11', pts: 1, text: 'What is the past simple form of the verb "see"?', opts: o4('seed', 'seen', 'saw', 'sawed'), ans: 'C', why: 'Quá khứ đơn của <i>see</i> là <i>saw</i>. <i>Seen</i> là quá khứ phân từ, không dùng một mình ở quá khứ đơn.' },
    { sec: 'Tương lai đơn', lvl: 'TH', name: 'Câu 12', pts: 1, text: 'They ___ the homework tomorrow morning.', opts: o4('will do', 'did', 'do', 'does'), ans: 'A', why: '"Tomorrow morning" là mốc tương lai nên dùng <i>will do</i>.' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 13', pts: 1, text: 'Choose the underlined part that needs correction: <u>Tomorrow</u> my sister <u>will</u> be twelve, <u>so</u> we <u>had</u> a party for her.', opts: o4('Tomorrow', 'will', 'so', 'had'), ans: 'D', why: 'Cả câu nói về ngày mai nên vế sau cũng phải ở tương lai: <i>we will have a party</i>. Bẫy là học sinh chỉ nhìn vế đầu thấy "will" đã đúng rồi bỏ qua vế sau bị chia quá khứ.' },
    { sec: 'There was / There were', lvl: 'NB', name: 'Câu 14', pts: 1, text: 'There ___ a big tree in front of my house ten years ago.', opts: o4('is', 'are', 'was', 'were'), ans: 'C', why: '"Ten years ago" là quá khứ và "a big tree" là số ít nên dùng <i>There was</i>.' },
    { sec: 'Quá khứ và hiện tại', lvl: 'NC', name: 'Câu 15', pts: 1, text: 'Nam ___ his homework last night, so his teacher ___ happy today.', opts: o4('doesn\'t do – isn\'t', 'didn\'t do – isn\'t', 'didn\'t did – wasn\'t', 'didn\'t do – wasn\'t'), ans: 'B', why: 'Vế đầu có "last night" → <i>didn\'t do</i> (sau <i>didn\'t</i> là nguyên thể, nên C sai). Vế sau có "today" → thì hiện tại <i>isn\'t</i>. Bẫy ở D: thấy vế đầu là quá khứ nên chia luôn vế sau thành "wasn\'t", trong khi "today" bắt buộc dùng hiện tại.' },
    { sec: 'Was / Were', lvl: 'TH', name: 'Câu 16', pts: 1, text: 'When ___ you born? — In 2012.', opts: o4('were', 'was', 'did', 'are'), ans: 'A', why: 'Cấu trúc cố định <i>be born</i>; với chủ ngữ "you" ở quá khứ dùng <i>were</i>.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 17', pts: 1, text: 'Last week Lan had 100000 dong. She bought a book for 45000 dong and a pen for 15000 dong. Then her mother gave her 20000 dong. How much money does Lan have now?', opts: o4('40000 dong', '80000 dong', '55000 dong', '60000 dong'), ans: 'D', why: 'Lan tiêu 45000 + 15000 = 60000 đồng, còn lại 100000 − 60000 = 40000 đồng, sau đó được cho thêm 20000 đồng → <b>60000 đồng</b>. Chọn 40000 là quên khoản mẹ cho.' },
    { sec: 'Tương lai đơn', lvl: 'NB', name: 'Câu 18', pts: 1, text: 'He ___ play football next Sunday.', opts: o4('is', 'will', 'was', 'did'), ans: 'B', why: 'Trước động từ nguyên thể "play" và có mốc "next Sunday" nên dùng <i>will</i>.' },
    { sec: 'Câu đồng nghĩa', lvl: 'NC', name: 'Câu 19', pts: 1, text: 'Choose the sentence that has the closest meaning to: "I think it will rain tomorrow."', opts: o4('It rained very hard yesterday morning.', 'It is raining outside at the moment.', 'Perhaps it will rain tomorrow.', 'It never rains in this city.'), ans: 'C', why: '"I think it will rain" diễn tả dự đoán chưa chắc chắn, tương đương với <i>Perhaps it will rain</i>. Bẫy ở B: học sinh thấy chữ "rain" rồi chọn câu đang mưa, nhưng câu gốc nói về NGÀY MAI chứ không phải lúc này.' },
    { sec: 'Câu hỏi quá khứ', lvl: 'TH', name: 'Câu 20', pts: 1, text: 'Where ___ you go last summer?', opts: o4('did', 'do', 'will', 'were'), ans: 'A', why: '"Last summer" là quá khứ và động từ chính "go" ở nguyên thể nên trợ động từ là <i>did</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>Last summer my family <b>(21)___</b> to Nha Trang. We <b>(22)___</b> there by train. The weather was sunny, so we <b>(23)___</b> a lot of time on the beach. My brother <b>(24)___</b> not swim well, so my father taught him every morning. We all loved the trip. Next summer we <b>(25)___</b> to Da Nang.<br><br><b>Câu 21.</b> Last summer my family <b>(21)___</b> to Nha Trang.', opts: o4('go', 'went', 'will go', 'goes'), ans: 'B', why: '"Last summer" là mốc quá khứ nên dùng <i>went</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> We <b>(22)___</b> there by train.', opts: o4('go', 'will go', 'are going', 'went'), ans: 'D', why: 'Câu này vẫn kể về chuyến đi hè năm ngoái nên tiếp tục dùng quá khứ đơn <i>went</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> The weather was sunny, so we <b>(23)___</b> a lot of time on the beach.', opts: o4('paid', 'cost', 'spent', 'took'), ans: 'C', why: 'Collocation đúng là <i>spend time</i> (dành thời gian) — quá khứ là <i>spent</i>. Bẫy ở D: học sinh nhớ cấu trúc "It takes me ten minutes" rồi dùng "took", nhưng <i>take</i> chỉ dùng với chủ ngữ giả "it", không nói "we took a lot of time on the beach".' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> My brother <b>(24)___</b> not swim well, so my father taught him every morning.', opts: o4('did', 'was', 'does', 'will'), ans: 'A', why: 'Động từ chính "swim" ở nguyên thể và cả câu ở quá khứ nên trợ động từ phủ định là <i>did</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> Next summer we <b>(25)___</b> to Da Nang.', opts: o4('went', 'will go', 'go', 'was going'), ans: 'B', why: 'Đoạn văn chuyển sang mốc "Next summer" nên phải dùng tương lai đơn <i>will go</i>. Bẫy ở A: cả đoạn trước đó đều ở quá khứ nên học sinh theo quán tính chọn "went", quên rằng câu cuối đã đổi mốc thời gian.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>Yesterday was Sunday. Hoa got up late, at eight o\'clock. After breakfast she helped her mother clean the house. At ten her cousin Mai came and they played badminton in the garden for an hour. In the afternoon they went to the bookshop and Hoa bought two English books. In the evening Hoa\'s family had dinner at a small restaurant near their house. Hoa was very happy. Next Sunday she will visit her grandparents in the countryside.<br><br><b>Câu 26.</b> What time did Hoa get up yesterday?', opts: o4('At seven.', 'At nine.', 'At eight.', 'At ten.'), ans: 'C', why: 'Bài viết rõ "Hoa got up late, at eight o\'clock".' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> Which sentence is NOT true about Hoa\'s Sunday?', opts: o4('Hoa cleaned the house with her mother.', 'Mai came to Hoa\'s house at ten.', 'Hoa\'s family ate out in the evening.', 'Hoa bought two books in the morning.'), ans: 'D', why: 'Hoa mua sách vào BUỔI CHIỀU ("In the afternoon they went to the bookshop"), nên D sai. Bẫy là chi tiết "two English books" đúng khiến học sinh vội cho cả câu là đúng mà không để ý mốc thời gian.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> What will Hoa do next Sunday?', opts: o4('She will visit her grandparents.', 'She will play badminton with Mai.', 'She will go to the bookshop again.', 'She will clean the house.'), ans: 'A', why: 'Câu cuối bài: "Next Sunday she will visit her grandparents in the countryside."' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> Hoa and Mai started playing badminton at ten and played for an hour. Hoa had lunch 90 minutes after the game finished. What time did she have lunch?', opts: o4('11.30', '12.00', '12.30', '13.00'), ans: 'C', why: 'Trận cầu lông kết thúc lúc 10.00 + 1 giờ = 11.00. Ăn trưa sau đó 90 phút → <b>12.30</b>. Chọn 11.30 là quên cộng đủ 90 phút, chọn 12.00 là chỉ cộng 60 phút.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 30', pts: 1, text: '<b>Câu 30.</b> The word "cousin" in the passage means ___.', opts: o4('a child of your teacher', 'a child of your uncle or aunt', 'a sister of your mother', 'a friend at your school'), ans: 'B', why: '<i>Cousin</i> nghĩa là anh/chị/em họ — con của cô, dì, chú, bác.' },
  ],
},

/* ═══════════ ĐỀ 15 — ÔN TẬP SO SÁNH HƠN VÀ SO SÁNH NHẤT ═══════════ */
{
  id: 10715, title: 'Đề 15 · Ôn tập so sánh — tính từ ngắn, tính từ dài, bất quy tắc', time: 60,
  questions: [
    { sec: 'Phát âm', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently from the others: t<u>a</u>ller — sm<u>a</u>ller — w<u>a</u>rmer — f<u>a</u>ster', opts: o4('taller', 'smaller', 'warmer', 'faster'), ans: 'D', why: 'Chữ "a" trong <i>faster</i> đọc /ɑː/; trong <i>taller, smaller, warmer</i> đều đọc /ɔː/.' },
    { sec: 'Trọng âm', lvl: 'TH', name: 'Câu 2', pts: 1, text: 'Choose the word that has a different stress pattern from the others.', opts: o4('better', 'expensive', 'bigger', 'heavy'), ans: 'B', why: '<i>Expensive</i> có ba âm tiết và nhấn âm tiết thứ hai (ex-PEN-sive); ba từ còn lại đều hai âm tiết, nhấn âm tiết thứ nhất.' },
    { sec: 'So sánh kép', lvl: 'NC', name: 'Câu 3', pts: 1, text: 'Ha Long Bay is ___ than I thought. In fact, it is one of ___ places in Viet Nam.', opts: o4('more beautiful – the most beautiful', 'beautifuler – the beautifulest', 'more beautiful – the more beautiful', 'the most beautiful – more beautiful'), ans: 'A', why: 'Vế đầu có "than" → so sánh hơn của tính từ dài: <i>more beautiful</i>. Vế sau có cấu trúc "one of the + so sánh nhất + danh từ số nhiều" → <i>the most beautiful</i>. Bẫy ở B: tính từ dài không thêm -er/-est. Bẫy ở C: "the more" không phải dạng so sánh nhất.' },
    { sec: 'So sánh hơn', lvl: 'NB', name: 'Câu 4', pts: 1, text: 'My brother is ___ than me.', opts: o4('tall', 'the tallest', 'taller', 'more tall'), ans: 'C', why: 'Có "than" nên dùng so sánh hơn; <i>tall</i> là tính từ ngắn nên thêm -er: <i>taller</i>.' },
    { sec: 'So sánh hơn', lvl: 'TH', name: 'Câu 5', pts: 1, text: 'This book is ___ interesting than that one.', opts: o4('the most', 'more', 'most', 'much'), ans: 'B', why: '<i>Interesting</i> là tính từ dài nên so sánh hơn dùng <i>more + adj + than</i>.' },
    { sec: 'Nhận diện câu đúng', lvl: 'NC', name: 'Câu 6', pts: 1, text: 'Which sentence is correct?', opts: o4('She is the most tall girl in my class.', 'My bag is more heavy than yours.', 'Today is hotter as yesterday.', 'This is the best film of the year.'), ans: 'D', why: '<i>Good</i> là tính từ bất quy tắc: good – better – the best, nên D đúng. A và B sai vì <i>tall</i> và <i>heavy</i> là tính từ ngắn, phải dùng "the tallest" và "heavier". C sai vì so sánh hơn đi với <i>than</i>, không phải "as".' },
    { sec: 'So sánh nhất', lvl: 'NB', name: 'Câu 7', pts: 1, text: 'The Mekong is the ___ river in Viet Nam.', opts: o4('longest', 'longer', 'long', 'more long'), ans: 'A', why: 'Có "the" và phạm vi "in Viet Nam" nên dùng so sánh nhất của tính từ ngắn: <i>the longest</i>.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 8', pts: 1, text: 'Nam is 150 cm tall. Ba is 8 cm taller than Nam, and Minh is 5 cm shorter than Ba. Who is the tallest and how tall is he?', opts: o4('Nam, 150 cm', 'Minh, 153 cm', 'Ba, 158 cm', 'Ba, 155 cm'), ans: 'C', why: 'Ba cao 150 + 8 = 158 cm; Minh cao 158 − 5 = 153 cm. Vậy <b>Ba cao nhất với 158 cm</b>. Chọn "Minh, 153 cm" là nhầm người cao nhất.' },
    { sec: 'So sánh nhất', lvl: 'TH', name: 'Câu 9', pts: 1, text: 'Mount Fansipan is ___ mountain in Viet Nam.', opts: o4('higher', 'the highest', 'high', 'more high'), ans: 'B', why: 'So sánh trong một phạm vi ("in Viet Nam") nên dùng so sánh nhất: <i>the highest</i>.' },
    { sec: 'Suy luận so sánh', lvl: 'NC', name: 'Câu 10', pts: 1, text: 'Da Lat is cooler than Ha Noi, and Sa Pa is cooler than Da Lat. Which sentence is true?', opts: o4('Sa Pa is the coolest of the three places.', 'Ha Noi is cooler than Sa Pa.', 'Da Lat is the coolest of the three places.', 'Ha Noi is the coolest of the three places.'), ans: 'A', why: 'Xếp theo độ mát: Sa Pa > Đà Lạt > Hà Nội, nên Sa Pa mát nhất. Bẫy ở C: học sinh chỉ đọc vế đầu ("Da Lat is cooler than Ha Noi") rồi kết luận Đà Lạt mát nhất mà bỏ qua vế thứ hai.' },
    { sec: 'Tính từ bất quy tắc', lvl: 'NB', name: 'Câu 11', pts: 1, text: 'Complete the series: good – better – ___', opts: o4('goodest', 'the goodest', 'more good', 'the best'), ans: 'D', why: '<i>Good</i> là tính từ bất quy tắc: good – better – <i>the best</i>.' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 12', pts: 1, text: 'Choose the underlined part that needs correction: <u>My</u> new school <u>is</u> <u>more big</u> than <u>my old one</u>.', opts: o4('My', 'is', 'more big', 'my old one'), ans: 'C', why: '<i>Big</i> là tính từ ngắn một âm tiết nên so sánh hơn phải gấp đôi phụ âm và thêm -er: <i>bigger</i>. Bẫy là học sinh quen dùng "more + adj" cho mọi tính từ. Ba phần còn lại đều đúng.' },
    { sec: 'So sánh nhất', lvl: 'TH', name: 'Câu 13', pts: 1, text: 'Of the three brothers, Tuan is ___.', opts: o4('the youngest', 'younger', 'young', 'more young'), ans: 'A', why: 'So sánh trong nhóm ba người nên dùng so sánh nhất: <i>the youngest</i>.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 14', pts: 1, text: 'Lan\'s schoolbag costs 180000 dong. Mai\'s bag is 45000 dong cheaper than Lan\'s. How much does Mai\'s bag cost?', opts: o4('225000 dong', '135000 dong', '145000 dong', '125000 dong'), ans: 'B', why: '"Cheaper than" nghĩa là rẻ hơn nên phải TRỪ: 180000 − 45000 = <b>135000 đồng</b>. Chọn 225000 là cộng nhầm vì hiểu ngược nghĩa "cheaper".' },
    { sec: 'Dạng so sánh', lvl: 'NB', name: 'Câu 15', pts: 1, text: 'Which word is the comparative form of "happy"?', opts: o4('happyer', 'more happy', 'happiest', 'happier'), ans: 'D', why: 'Tính từ hai âm tiết tận cùng bằng -y đổi y thành i rồi thêm -er: <i>happier</i>.' },
    { sec: 'Câu đồng nghĩa', lvl: 'NC', name: 'Câu 16', pts: 1, text: 'Choose the sentence that has the closest meaning to: "No student in my class is taller than Nam."', opts: o4('Nam is taller than some students.', 'Nam is shorter than many students.', 'Nam is the tallest student in my class.', 'Nam is as tall as the other students.'), ans: 'C', why: '"Không học sinh nào cao hơn Nam" nghĩa là Nam cao nhất lớp. Bẫy ở A: câu này cũng đúng một phần nhưng yếu hơn nhiều — nó chỉ nói Nam cao hơn MỘT SỐ bạn, trong khi câu gốc khẳng định không ai cao hơn Nam.' },
    { sec: 'So sánh hơn', lvl: 'TH', name: 'Câu 17', pts: 1, text: 'My sister is two years ___ than me.', opts: o4('older', 'oldest', 'more old', 'the older'), ans: 'A', why: 'Có "than" nên dùng so sánh hơn của tính từ ngắn: <i>older</i>.' },
    { sec: 'Tính từ bất quy tắc', lvl: 'NB', name: 'Câu 18', pts: 1, text: 'Which is the superlative form of "bad"?', opts: o4('baddest', 'the worst', 'worse', 'more bad'), ans: 'B', why: '<i>Bad</i> là tính từ bất quy tắc: bad – worse – <i>the worst</i>.' },
    { sec: 'So sánh kép', lvl: 'NC', name: 'Câu 19', pts: 1, text: 'The Red River is long, the Mekong is ___, but the Nile is ___ river in the world.', opts: o4('longer – longest', 'the longest – longer', 'more long – the longest', 'longer – the longest'), ans: 'D', why: 'Vế giữa so sánh hai con sông → <i>longer</i>; vế cuối so sánh trong phạm vi "in the world" → <i>the longest</i> (bắt buộc có "the"). Bẫy ở A: viết "longest" mà thiếu mạo từ "the" nên sai; bẫy ở B là đảo ngược thứ tự hai dạng so sánh.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 20', pts: 1, text: 'Look at the price list: a pen 9000 dong, a ruler 6000 dong, a notebook 14000 dong, an eraser 4000 dong. Which item is the most expensive, and how much more does it cost than the cheapest one?', opts: o4('The pen, 5000 dong more.', 'The notebook, 8000 dong more.', 'The notebook, 10000 dong more.', 'The pen, 3000 dong more.'), ans: 'C', why: 'Đắt nhất là quyển vở (14000 đồng), rẻ nhất là cục tẩy (4000 đồng): 14000 − 4000 = <b>10000 đồng</b>. Chọn "8000 dong more" là trừ nhầm với cái thước 6000 đồng.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>My town is small, but it is <b>(21)___</b> beautiful place I know. The streets here are <b>(22)___</b> than the streets in the city, and the air is much <b>(23)___</b>. People are friendly too. My best friend Hoa lives in a big city. She says life there is <b>(24)___</b> than life in my town, but it is also noisier. Next month she <b>(25)___</b> come and stay with me for a week.<br><br><b>Câu 21.</b> … it is <b>(21)___</b> beautiful place I know.', opts: o4('a more', 'the most', 'more', 'most'), ans: 'B', why: 'Trước danh từ "place" và có mệnh đề giới hạn "I know" nên dùng so sánh nhất đầy đủ: <i>the most beautiful place</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> The streets here are <b>(22)___</b> than the streets in the city.', opts: o4('quieter', 'quietest', 'more quiet', 'the quietest'), ans: 'A', why: 'Có "than" nên dùng so sánh hơn; <i>quiet</i> là tính từ ngắn nên thêm -er: <i>quieter</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> … and the air is much <b>(23)___</b>.', opts: o4('cleaner than', 'the cleanest', 'cleaner', 'more clean'), ans: 'C', why: 'Câu kết thúc ngay sau chỗ trống, không có vế "than…" nên chỉ dùng <i>cleaner</i> (đã ngầm hiểu là sạch hơn không khí thành phố). Bẫy ở A: thêm "than" mà không có gì đứng sau thì câu bị cụt; bẫy ở B là dùng so sánh nhất trong khi chỉ đang đối chiếu hai nơi.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> She says life there is <b>(24)___</b> than life in my town.', opts: o4('excitinger', 'the most exciting', 'most exciting', 'more exciting'), ans: 'D', why: '<i>Exciting</i> là tính từ dài nên so sánh hơn dùng <i>more exciting</i>, không thêm -er.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> Next month she <b>(25)___</b> come and stay with me for a week.', opts: o4('is', 'will', 'was', 'does'), ans: 'B', why: '"Next month" là mốc tương lai, theo sau là động từ nguyên thể "come" nên dùng <i>will</i>.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>Viet Nam has many beautiful islands. Phu Quoc is the largest island in the country; it is about 574 square kilometres. Cat Ba is smaller than Phu Quoc but bigger than Ly Son. Many tourists come to Phu Quoc because the beaches there are long and clean. Cat Ba is famous for its national park, and Ly Son is famous for its garlic. The sea around Ly Son is very clear, so people love swimming there. A boat from Sa Ky port to Ly Son takes about 35 minutes.<br><br><b>Câu 26.</b> Which statement about the three islands is true?', opts: o4('Ly Son is the smallest of the three islands.', 'Cat Ba is larger than Phu Quoc.', 'Phu Quoc is smaller than Cat Ba.', 'Ly Son is bigger than Cat Ba.'), ans: 'A', why: 'Bài cho biết Phú Quốc lớn nhất, còn Cát Bà nhỏ hơn Phú Quốc nhưng lớn hơn Lý Sơn → thứ tự là Phú Quốc > Cát Bà > Lý Sơn, nên Lý Sơn nhỏ nhất. Bẫy ở D: học sinh đọc lướt câu "Cat Ba is smaller than Phu Quoc but bigger than Ly Son" rồi gán nhầm chủ ngữ cho Lý Sơn.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> Why do many tourists come to Phu Quoc?', opts: o4('Because it has a national park.', 'Because its garlic is famous.', 'Because its beaches are long and clean.', 'Because it is near Sa Ky port.'), ans: 'C', why: 'Bài viết: "Many tourists come to Phu Quoc because the beaches there are long and clean." Vườn quốc gia là của Cát Bà, tỏi là của Lý Sơn.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> Ly Son is famous for ___.', opts: o4('its national park', 'its garlic', 'its long beaches', 'its big port'), ans: 'B', why: 'Bài đọc: "Ly Son is famous for its garlic."' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> Which information is NOT given in the passage?', opts: o4('The size of Phu Quoc island.', 'The travel time from Sa Ky to Ly Son.', 'The reason why people swim near Ly Son.', 'The number of tourists in Cat Ba each year.'), ans: 'D', why: 'Bài không nêu con số du khách của Cát Bà. Diện tích Phú Quốc (574 km²), thời gian đi tàu (35 phút) và lí do người ta thích bơi ở Lý Sơn (nước rất trong) đều có trong bài.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 30', pts: 1, text: '<b>Câu 30.</b> The word "it" in "it is about 574 square kilometres" refers to ___.', opts: o4('Phu Quoc', 'Cat Ba', 'Ly Son', 'Viet Nam'), ans: 'A', why: 'Đại từ <i>it</i> thay cho hòn đảo vừa được nhắc ngay trước đó là <i>Phu Quoc</i>.' },
  ],
},

/* ═══════════ ĐỀ 16 — ÔN TẬP GIỚI TỪ THỜI GIAN VÀ NƠI CHỐN ═══════════ */
{
  id: 10716, title: 'Đề 16 · Ôn tập giới từ — in / on / at chỉ thời gian và nơi chốn', time: 60,
  questions: [
    { sec: 'Phát âm', lvl: 'TH', name: 'Câu 1', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently from the others: <u>th</u>ree — <u>th</u>ink — <u>th</u>ey — <u>th</u>ank', opts: o4('three', 'think', 'they', 'thank'), ans: 'B', why: 'Cụm "th" trong <i>they</i> đọc là âm hữu thanh /ð/; trong <i>three, think, thank</i> đều đọc âm vô thanh /θ/.' },
    { sec: 'Trọng âm', lvl: 'NB', name: 'Câu 2', pts: 1, text: 'Choose the word that has a different stress pattern from the others.', opts: o4('before', 'beside', 'below', 'opposite'), ans: 'D', why: '<i>Opposite</i> có ba âm tiết và nhấn âm tiết thứ nhất; <i>before, beside, below</i> đều nhấn âm tiết thứ hai.' },
    { sec: 'Giới từ thời gian', lvl: 'NC', name: 'Câu 3', pts: 1, text: 'We often go camping ___ the weekend, and my birthday is ___ 25 October.', opts: o4('on – in', 'at – in', 'at – on', 'in – on'), ans: 'C', why: 'Tiếng Anh Anh dùng <i>at the weekend</i>; với ngày tháng cụ thể dùng <i>on 25 October</i>. Bẫy ở B: học sinh nhớ "in October" rồi giữ luôn "in" khi đã có số ngày đứng trước — có ngày cụ thể thì phải đổi sang "on".' },
    { sec: 'Giới từ thời gian', lvl: 'TH', name: 'Câu 4', pts: 1, text: 'The meeting starts ___ 7.30 ___ Monday morning.', opts: o4('at – on', 'in – on', 'on – at', 'at – in'), ans: 'A', why: 'Giờ cụ thể dùng <i>at</i>; buổi sáng của một thứ cụ thể dùng <i>on Monday morning</i>.' },
    { sec: 'Giới từ thời gian', lvl: 'NB', name: 'Câu 5', pts: 1, text: 'My birthday is ___ May.', opts: o4('on', 'at', 'to', 'in'), ans: 'D', why: 'Với tháng ta dùng <i>in</i>: in May.' },
    { sec: 'Nhận diện câu đúng', lvl: 'NC', name: 'Câu 6', pts: 1, text: 'Which sentence is correct?', opts: o4('I was born in 15 June 2012.', 'She goes to school at seven o\'clock.', 'We play football in Sunday afternoon.', 'They have a party on the evening.'), ans: 'B', why: 'Giờ cụ thể đi với <i>at</i> nên B đúng. A sai vì ngày tháng cụ thể phải dùng "on 15 June 2012"; C sai vì buổi chiều của một thứ phải dùng "on Sunday afternoon"; D sai vì buổi tối chung chung dùng "in the evening".' },
    { sec: 'Giới từ nơi chốn', lvl: 'TH', name: 'Câu 7', pts: 1, text: 'The cat is sleeping ___ the sofa.', opts: o4('in', 'at', 'on', 'to'), ans: 'C', why: 'Nằm TRÊN bề mặt ghế nên dùng <i>on</i>.' },
    { sec: 'Giới từ nơi chốn', lvl: 'NB', name: 'Câu 8', pts: 1, text: 'My grandparents live ___ Ha Noi.', opts: o4('in', 'on', 'at', 'to'), ans: 'A', why: 'Với thành phố, tỉnh, quốc gia ta dùng <i>in</i>.' },
    { sec: 'Giới từ nơi chốn', lvl: 'NC', name: 'Câu 9', pts: 1, text: 'My uncle lives ___ 25 Le Loi Street, ___ a small town ___ the north of Viet Nam.', opts: o4('in – at – in', 'at – on – on', 'on – in – at', 'at – in – in'), ans: 'D', why: 'Địa chỉ có SỐ NHÀ dùng <i>at</i> (at 25 Le Loi Street); thị trấn dùng <i>in</i>; phương hướng của một nước dùng <i>in the north of…</i>. Bẫy là học sinh quen câu "in Le Loi Street" nên chọn "in" ngay cả khi đã có số nhà.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 10', pts: 1, text: 'The film starts at 19.45 and lasts 105 minutes. There is also a 10-minute break in the middle. What time does the film finish?', opts: o4('21.30', '21.40', '21.50', '21.35'), ans: 'B', why: 'Tổng thời gian ở rạp: 105 + 10 = 115 phút = 1 giờ 55 phút. 19.45 + 1 giờ 55 phút = <b>21.40</b>. Chọn 21.30 là quên 10 phút giải lao.' },
    { sec: 'Giới từ thời gian', lvl: 'NB', name: 'Câu 11', pts: 1, text: 'We have English ___ Tuesday and Friday.', opts: o4('on', 'in', 'at', 'of'), ans: 'A', why: 'Với thứ trong tuần ta dùng <i>on</i>.' },
    { sec: 'Giới từ nơi chốn', lvl: 'TH', name: 'Câu 12', pts: 1, text: 'The bookshop is ___ the bank and the post office.', opts: o4('among', 'in', 'between', 'next'), ans: 'C', why: 'Ở giữa HAI địa điểm nối bằng "and" thì dùng <i>between … and …</i>. <i>Among</i> dùng với nhiều vật; "next" thiếu "to".' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 13', pts: 1, text: 'Choose the underlined part that needs correction: My sister <u>was born</u> <u>on</u> 3 March 2010, <u>and</u> she often gets presents <u>in</u> her birthday.', opts: o4('was born', 'on', 'and', 'in'), ans: 'D', why: 'Cụm đúng là <i>on her birthday</i> vì sinh nhật là một NGÀY cụ thể. Bẫy là chỗ "on 3 March 2010" phía trước đã dùng đúng khiến học sinh tưởng lỗi nằm ở đó; thực ra lỗi ở giới từ cuối câu.' },
    { sec: 'Giới từ nơi chốn', lvl: 'NB', name: 'Câu 14', pts: 1, text: 'There is a clock ___ the wall.', opts: o4('on', 'in', 'at', 'under'), ans: 'A', why: 'Treo trên bề mặt tường nên dùng <i>on the wall</i>.' },
    { sec: 'Giới từ tổng hợp', lvl: 'NC', name: 'Câu 15', pts: 1, text: 'Nam waits ___ the bus stop ___ front of the school every morning ___ 6.30.', opts: o4('in – on – at', 'at – in – at', 'on – in – on', 'at – in – on'), ans: 'B', why: 'Bến xe buýt là một ĐIỂM nên dùng <i>at the bus stop</i>; cụm cố định là <i>in front of</i>; giờ cụ thể dùng <i>at 6.30</i>. Bẫy ở D: dùng "on 6.30" vì tưởng đang nói tới một ngày, nhưng 6.30 là giờ nên phải là "at".' },
    { sec: 'Giới từ thời gian', lvl: 'TH', name: 'Câu 16', pts: 1, text: 'I usually do my homework ___ the evening.', opts: o4('on', 'at', 'in', 'to'), ans: 'C', why: 'Buổi trong ngày nói chung dùng <i>in</i>: in the morning / in the afternoon / in the evening.' },
    { sec: 'Giới từ thời gian', lvl: 'NB', name: 'Câu 17', pts: 1, text: 'Students have a long holiday ___ summer.', opts: o4('on', 'at', 'to', 'in'), ans: 'D', why: 'Với mùa trong năm ta dùng <i>in</i>: in summer.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 18', pts: 1, text: 'Lan\'s train leaves at 14.15. She needs 40 minutes to get to the station and she wants to be there 25 minutes before the train leaves. What is the latest time she should leave home?', opts: o4('13.10', '13.35', '12.50', '13.00'), ans: 'A', why: 'Lan muốn có mặt ở ga lúc 14.15 − 25 phút = 13.50. Trừ tiếp 40 phút đi đường → rời nhà chậm nhất lúc <b>13.10</b>. Chọn 13.35 là quên 25 phút chờ trước giờ tàu.' },
    { sec: 'Câu đồng nghĩa', lvl: 'NC', name: 'Câu 19', pts: 1, text: 'Choose the sentence that has the closest meaning to: "My house is opposite the market."', opts: o4('The market is behind my house.', 'The market faces my house across the road.', 'My house is next to the market.', 'My house is near the market gate.'), ans: 'B', why: '<i>Opposite</i> nghĩa là đối diện, tức là hai bên đối mặt nhau qua con đường. Bẫy ở C: <i>next to</i> nghĩa là ở BÊN CẠNH, cùng một phía, khác hẳn với đối diện.' },
    { sec: 'Chỉ đường', lvl: 'TH', name: 'Câu 20', pts: 1, text: 'Turn left ___ the traffic lights and the school is ___ your right.', opts: o4('in – at', 'at – in', 'at – on', 'on – at'), ans: 'C', why: 'Ở một điểm mốc như đèn giao thông dùng <i>at</i>; chỉ phía bên phải dùng cụm cố định <i>on your right</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>Hello! I\'m Trang. I live <b>(21)___</b> a small flat <b>(22)___</b> the fifth floor of a tall building <b>(23)___</b> the centre of Ha Noi. My school is not far, so I walk there <b>(24)___</b> the morning. Classes begin <b>(25)___</b> seven o\'clock and finish at half past eleven.<br><br><b>Câu 21.</b> I live <b>(21)___</b> a small flat.', opts: o4('in', 'on', 'at', 'to'), ans: 'A', why: 'Ở bên trong một căn hộ nên dùng <i>in a flat</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> … a small flat <b>(22)___</b> the fifth floor of a tall building.', opts: o4('in', 'at', 'to', 'on'), ans: 'D', why: 'Tiếng Anh nói <i>on the fifth floor</i> — tầng được coi như một mặt sàn. Bẫy ở A: câu trước vừa dùng "in a flat" nên học sinh theo quán tính chọn "in", nhưng với TẦNG thì bắt buộc dùng "on".' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> … of a tall building <b>(23)___</b> the centre of Ha Noi.', opts: o4('at', 'in', 'on', 'under'), ans: 'B', why: 'Cụm cố định là <i>in the centre of…</i> (ở trung tâm của).' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> … so I walk there <b>(24)___</b> the morning.', opts: o4('on', 'at', 'in', 'by'), ans: 'C', why: 'Buổi sáng nói chung dùng <i>in the morning</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> Classes begin <b>(25)___</b> seven o\'clock.', opts: o4('at', 'on', 'in', 'from'), ans: 'A', why: 'Giờ cụ thể luôn đi với <i>at</i>: at seven o\'clock.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>Mr Long works at a post office in a small town. The post office is on Hung Vuong Street, next to a bank and opposite a big supermarket. It opens at seven in the morning and closes at five in the afternoon, from Monday to Saturday. On Sunday it is closed. Mr Long lives about three kilometres from the post office, so he goes to work by motorbike. It takes him about ten minutes. At lunch time he often eats at a small restaurant behind the post office.<br><br><b>Câu 26.</b> Which sentence is true about the post office?', opts: o4('It is behind a big supermarket.', 'It opens on Sunday morning.', 'It is opposite a bank.', 'There is a bank next to it.'), ans: 'D', why: 'Bài viết "next to a bank and opposite a big supermarket" nên ngân hàng ở BÊN CẠNH (D đúng) còn siêu thị mới ở đối diện. Bẫy ở C: đảo hai giới từ <i>next to</i> và <i>opposite</i> cho nhau. B sai vì Chủ nhật bưu điện đóng cửa.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> What time does the post office close?', opts: o4('At seven in the morning.', 'At five in the afternoon.', 'At six in the evening.', 'At twelve at noon.'), ans: 'B', why: 'Bài viết rõ: "closes at five in the afternoon".' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> How far does Mr Long travel to work and back every working day?', opts: o4('Three kilometres.', 'Ten kilometres.', 'Six kilometres.', 'Thirteen kilometres.'), ans: 'C', why: 'Nhà cách bưu điện 3 km, đi và về là 2 lượt: 3 × 2 = <b>6 km</b>. Bẫy ở A: chỉ lấy quãng đường một chiều; bẫy ở B là nhầm con số 10 phút thành 10 km.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> How many hours is the post office open in one week?', opts: o4('60 hours.', '50 hours.', '70 hours.', '48 hours.'), ans: 'A', why: 'Mỗi ngày mở từ 7 giờ đến 17 giờ = 10 tiếng; mở 6 ngày (thứ Hai đến thứ Bảy): 10 × 6 = <b>60 tiếng</b>. Chọn 70 là tính nhầm cả Chủ nhật.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 30', pts: 1, text: '<b>Câu 30.</b> Where does Mr Long often have lunch?', opts: o4('At home with his family.', 'In the bank next to his office.', 'In the big supermarket opposite.', 'At a small restaurant nearby.'), ans: 'D', why: 'Bài viết: "he often eats at a small restaurant behind the post office".' },
  ],
},

/* ═══════════ ĐỀ 17 — ÔN TẬP ĐẠI TỪ VÀ TÍNH TỪ SỞ HỮU ═══════════ */
{
  id: 10717, title: 'Đề 17 · Ôn tập đại từ — my/mine, đại từ tân ngữ, sở hữu cách', time: 60,
  questions: [
    { sec: 'Phát âm', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently from the others: h<u>i</u>s — m<u>i</u>ne — n<u>i</u>ne — f<u>i</u>ne', opts: o4('his', 'mine', 'nine', 'fine'), ans: 'A', why: 'Chữ "i" trong <i>his</i> đọc /ɪ/; trong <i>mine, nine, fine</i> đều đọc /aɪ/.' },
    { sec: 'Trọng âm', lvl: 'NC', name: 'Câu 2', pts: 1, text: 'Choose the word that has a different stress pattern from the others.', opts: o4('brother', 'sister', 'because', 'daughter'), ans: 'C', why: '<i>Because</i> nhấn âm tiết thứ hai (be-CAUSE); <i>brother, sister, daughter</i> đều là danh từ hai âm tiết nhấn âm tiết thứ nhất. Bẫy là học sinh quen đọc "BE-cause" theo kiểu tiếng Việt.' },
    { sec: 'Phát âm', lvl: 'TH', name: 'Câu 3', pts: 1, text: 'Choose the word whose final <b>-s/-es</b> is pronounced /ɪz/.', opts: o4('parents', 'houses', 'books', 'cats'), ans: 'B', why: '<i>Houses</i> có đuôi -es đọc /ɪz/ vì gốc từ kết thúc bằng âm /s/. Ba từ còn lại kết thúc bằng /t/, /k/ nên -s đọc /s/.' },
    { sec: 'Đại từ sở hữu', lvl: 'NB', name: 'Câu 4', pts: 1, text: 'This is my book. It is ___.', opts: o4('my', 'me', 'mine\'s', 'mine'), ans: 'D', why: 'Sau động từ "to be" và không có danh từ đứng sau thì dùng đại từ sở hữu <i>mine</i>.' },
    { sec: 'Sở hữu', lvl: 'NC', name: 'Câu 5', pts: 1, text: 'These pens are not ___. ___ pens are on the desk over there.', opts: o4('our – Our', 'ours – Ours', 'ours – Our', 'our – Ours'), ans: 'C', why: 'Chỗ trống 1 đứng cuối vế, không có danh từ theo sau → đại từ sở hữu <i>ours</i>. Chỗ trống 2 đứng TRƯỚC danh từ "pens" → tính từ sở hữu <i>Our</i>. Bẫy ở B: dùng "Ours pens" — đại từ sở hữu không bao giờ đứng trước danh từ.' },
    { sec: 'Đại từ tân ngữ', lvl: 'TH', name: 'Câu 6', pts: 1, text: 'I often help ___ with ___ homework.', opts: o4('him – his', 'he – his', 'him – him', 'his – he'), ans: 'A', why: 'Sau động từ "help" cần đại từ tân ngữ <i>him</i>; trước danh từ "homework" cần tính từ sở hữu <i>his</i>.' },
    { sec: 'Đại từ chủ ngữ', lvl: 'NB', name: 'Câu 7', pts: 1, text: '___ is my teacher. ___ name is Mrs Ha.', opts: o4('She – She', 'She – Her', 'Her – Her', 'Hers – Her'), ans: 'B', why: 'Chỗ trống 1 là chủ ngữ → <i>She</i>; chỗ trống 2 đứng trước danh từ "name" → tính từ sở hữu <i>Her</i>.' },
    { sec: 'Đại từ tân ngữ', lvl: 'TH', name: 'Câu 8', pts: 1, text: 'Can you tell ___ the way to the post office?', opts: o4('I', 'my', 'mine', 'me'), ans: 'D', why: 'Sau động từ "tell" phải dùng đại từ tân ngữ <i>me</i>.' },
    { sec: 'Nhận diện câu đúng', lvl: 'NC', name: 'Câu 9', pts: 1, text: 'Choose the correct sentence.', opts: o4('This book is hers, not mine.', 'This book is her, not my.', 'This is hers book, not my.', 'This book is she, not me.'), ans: 'A', why: 'Sau "to be" và ở cuối câu ta dùng đại từ sở hữu: <i>hers, mine</i>. B sai vì "her" và "my" là tính từ sở hữu, phải có danh từ theo sau; C sai vì "hers book" không tồn tại; D sai vì "she/me" là đại từ nhân xưng chứ không chỉ sự sở hữu.' },
    { sec: 'Tính từ sở hữu', lvl: 'NB', name: 'Câu 10', pts: 1, text: 'We love ___ school very much.', opts: o4('us', 'we', 'our', 'ours'), ans: 'C', why: 'Trước danh từ "school" cần tính từ sở hữu <i>our</i>.' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 11', pts: 1, text: 'Choose the underlined part that needs correction: <u>My</u> sister and <u>me</u> often <u>go</u> to the park with <u>our</u> dog.', opts: o4('My', 'me', 'go', 'our'), ans: 'B', why: 'Cụm "My sister and me" đang làm CHỦ NGỮ nên phải dùng đại từ chủ ngữ: <i>My sister and I</i>. Bẫy là trong giao tiếp hằng ngày nhiều người vẫn nói "me", nhưng trong bài kiểm tra ngữ pháp thì sai. Động từ "go" đúng vì chủ ngữ là số nhiều.' },
    { sec: 'its / it\'s', lvl: 'TH', name: 'Câu 12', pts: 1, text: 'Look at that dog! It is playing with ___ ball.', opts: o4('it\'s', 'him', 'its\'', 'its'), ans: 'D', why: 'Tính từ sở hữu của "it" là <i>its</i>, viết không có dấu phẩy trên. <i>It\'s</i> là viết tắt của "it is".' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 13', pts: 1, text: 'A taxi fare is 240000 dong. Five people share it equally, but Mai pays for herself and for her mother. How much does Mai pay?', opts: o4('48000 dong', '120000 dong', '96000 dong', '60000 dong'), ans: 'C', why: 'Mỗi người trả 240000 : 5 = 48000 đồng. Mai trả cho hai người: 48000 × 2 = <b>96000 đồng</b>. Chọn 48000 là quên phần của mẹ; chọn 120000 là chia đôi tổng tiền.' },
    { sec: 'Đại từ sở hữu', lvl: 'NB', name: 'Câu 14', pts: 1, text: 'Is this your pen? — No, ___ is blue.', opts: o4('mine', 'my', 'me', 'I'), ans: 'A', why: 'Chỗ trống làm chủ ngữ và mang nghĩa "cái bút của tôi" nên dùng đại từ sở hữu <i>mine</i>.' },
    { sec: 'Đại từ chủ ngữ', lvl: 'NC', name: 'Câu 15', pts: 1, text: 'Lan and ___ are good friends. ___ often study together.', opts: o4('me – Us', 'I – We', 'I – Us', 'me – We'), ans: 'B', why: 'Cả hai chỗ trống đều làm chủ ngữ nên phải dùng đại từ chủ ngữ: <i>I</i> và <i>We</i>. Bẫy ở A và D là dùng "me" — đại từ tân ngữ — ở vị trí chủ ngữ; bẫy ở C là dùng "Us" làm chủ ngữ cho động từ "study".' },
    { sec: 'Sở hữu cách', lvl: 'TH', name: 'Câu 16', pts: 1, text: 'Whose book is this? — It\'s ___.', opts: o4('Nam', 'Nam is', 'of Nam', 'Nam\'s'), ans: 'D', why: 'Với người ta dùng sở hữu cách \'s: <i>Nam\'s</i> (sách của Nam), không dùng "of" như với đồ vật.' },
    { sec: 'Đại từ tân ngữ', lvl: 'NB', name: 'Câu 17', pts: 1, text: 'They are my parents. I love ___ very much.', opts: o4('them', 'they', 'their', 'theirs'), ans: 'A', why: 'Sau động từ "love" cần đại từ tân ngữ số nhiều <i>them</i>.' },
    { sec: 'Câu đồng nghĩa', lvl: 'NC', name: 'Câu 18', pts: 1, text: 'Choose the sentence that has the closest meaning to: "This house belongs to my grandparents."', opts: o4('This house is my grandparents.', 'This is my grandparents house.', 'This house is my grandparents\'.', 'My grandparents are in this house.'), ans: 'C', why: '"Belong to" nghĩa là thuộc về, nên phải dùng sở hữu cách: danh từ số nhiều đã có -s thì chỉ thêm dấu phẩy trên → <i>my grandparents\'</i>. A và B thiếu dấu sở hữu; D nói ông bà đang ở trong nhà, hoàn toàn khác nghĩa sở hữu.' },
    { sec: 'Sở hữu', lvl: 'TH', name: 'Câu 19', pts: 1, text: 'Mai can\'t find ___ umbrella, so I give her ___.', opts: o4('her – my', 'her – mine', 'hers – mine', 'hers – my'), ans: 'B', why: 'Trước danh từ "umbrella" dùng tính từ sở hữu <i>her</i>; cuối câu không có danh từ nên dùng đại từ sở hữu <i>mine</i>.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 20', pts: 1, text: 'Class 6A has 40 students and half of them are girls. Each girl brings her own water bottle, and every two boys share one bottle. How many bottles does the class have?', opts: o4('40', '20', '25', '30'), ans: 'D', why: 'Có 20 bạn nữ → 20 chai. Có 20 bạn nam, cứ hai bạn dùng chung một chai → 20 : 2 = 10 chai. Tổng cộng 20 + 10 = <b>30 chai</b>. Chọn 40 là quên các bạn nam dùng chung.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>Hi, I\'m Phong. This is a photo of <b>(21)___</b> family. The man on the left is my father. <b>(22)___</b> name is Hoang and he is an engineer. The woman next to <b>(23)___</b> is my mother. She is a nurse. The girl in the blue dress is my sister Linh. <b>(24)___</b> favourite subject is Art. The dog in the photo is <b>(25)___</b>; we call it Lucky.<br><br><b>Câu 21.</b> This is a photo of <b>(21)___</b> family.', opts: o4('my', 'me', 'mine', 'I'), ans: 'A', why: 'Trước danh từ "family" cần tính từ sở hữu <i>my</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> <b>(22)___</b> name is Hoang and he is an engineer.', opts: o4('He', 'Him', 'His', 'He\'s'), ans: 'C', why: 'Chỗ trống đứng trước danh từ "name" nên cần tính từ sở hữu <i>His</i>. Bẫy ở D: "He\'s name" nghe gần giống khi đọc nhanh nhưng thực chất là "He is name", hoàn toàn vô nghĩa.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> The woman next to <b>(23)___</b> is my mother.', opts: o4('he', 'his', 'he\'s', 'him'), ans: 'D', why: 'Sau giới từ "next to" phải dùng đại từ tân ngữ <i>him</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> <b>(24)___</b> favourite subject is Art.', opts: o4('She', 'Her', 'Hers', 'She\'s'), ans: 'B', why: 'Trước cụm danh từ "favourite subject" dùng tính từ sở hữu <i>Her</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> The dog in the photo is <b>(25)___</b>; we call it Lucky.', opts: o4('ours', 'our', 'us', 'we'), ans: 'A', why: 'Sau "to be" và không có danh từ theo sau nên dùng đại từ sở hữu <i>ours</i>. Bẫy ở B: "our" là tính từ sở hữu, bắt buộc phải có danh từ đứng sau (our dog).' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>The Nguyens live in a small house in Hue. Mr Nguyen is a teacher and his wife is a shop assistant. They have two children, Tuan and Hanh. Tuan is fourteen and his sister is eleven. Every evening Mr Nguyen helps his children with their homework. Their grandmother lives with them too. She is seventy years old and she loves telling the children old stories. The family has a small garden behind the house. Hanh waters the flowers there because she loves them, and Tuan feeds the chickens.<br><br><b>Câu 26.</b> What is Mrs Nguyen\'s job?', opts: o4('She is a teacher.', 'She is a nurse.', 'She is a shop assistant.', 'She is a student.'), ans: 'C', why: 'Bài viết "his wife is a shop assistant" — "his wife" chính là bà Nguyễn. Nghề giáo viên là của ông Nguyễn.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> How old is Hanh?', opts: o4('Fourteen.', 'Eleven.', 'Seventy.', 'Twelve.'), ans: 'B', why: 'Bài viết "Tuan is fourteen and his sister is eleven" — em gái Hạnh mười một tuổi.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> Which sentence is true about the family?', opts: o4('Tuan waters the flowers in the garden.', 'The grandmother does the children\'s homework.', 'Hanh is older than her brother Tuan.', 'Tuan is three years older than his sister.'), ans: 'D', why: 'Tuấn 14 tuổi, Hạnh 11 tuổi nên Tuấn hơn em ba tuổi → D đúng và C sai. A sai vì Hạnh mới là người tưới hoa, Tuấn cho gà ăn. B sai vì người giúp các con làm bài là ông Nguyễn, còn bà kể chuyện.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> How many years older is the grandmother than Tuan?', opts: o4('56', '59', '45', '66'), ans: 'A', why: 'Bà 70 tuổi, Tuấn 14 tuổi: 70 − 14 = <b>56</b> tuổi. Chọn 59 là trừ nhầm tuổi của Hạnh (70 − 11).' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 30', pts: 1, text: '<b>Câu 30.</b> The word "them" in the last sentence refers to ___.', opts: o4('the children', 'the chickens', 'the flowers', 'the old stories'), ans: 'C', why: 'Câu cuối là "Hanh waters the flowers there because she loves them" — <i>them</i> thay cho <i>the flowers</i>.' },
  ],
},

/* ═══════════ ĐỀ 18 — ÔN TẬP MẠO TỪ, LƯỢNG TỪ VÀ DANH TỪ ═══════════ */
{
  id: 10718, title: 'Đề 18 · Ôn tập mạo từ và lượng từ — a/an/the, some/any, much/many', time: 60,
  questions: [
    { sec: 'Phát âm', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Choose the word whose final <b>-s/-es</b> is pronounced differently from the others.', opts: o4('cats', 'maps', 'oranges', 'books'), ans: 'C', why: 'Đuôi -es trong <i>oranges</i> đọc /ɪz/ vì gốc từ kết thúc bằng âm /dʒ/. Ba từ còn lại kết thúc bằng âm vô thanh /t/, /p/, /k/ nên -s đọc /s/.' },
    { sec: 'Phát âm', lvl: 'TH', name: 'Câu 2', pts: 1, text: 'Choose the word that contains the sound /ʌ/.', opts: o4('some', 'soap', 'sold', 'so'), ans: 'A', why: '<i>Some</i> đọc /sʌm/. <i>Soap, sold, so</i> đều chứa nguyên âm đôi /əʊ/.' },
    { sec: 'Trọng âm', lvl: 'NB', name: 'Câu 3', pts: 1, text: 'Choose the word that has a different stress pattern from the others.', opts: o4('water', 'sugar', 'coffee', 'banana'), ans: 'D', why: '<i>Banana</i> ba âm tiết và nhấn âm tiết thứ hai (ba-NA-na); ba từ còn lại hai âm tiết nhấn âm tiết thứ nhất.' },
    { sec: 'some / any', lvl: 'NC', name: 'Câu 4', pts: 1, text: 'There isn\'t ___ milk in the fridge, but there are ___ eggs on the table.', opts: o4('some – any', 'any – some', 'any – any', 'some – some'), ans: 'B', why: 'Vế đầu là câu PHỦ ĐỊNH nên dùng <i>any</i>; vế sau là câu KHẲNG ĐỊNH nên dùng <i>some</i>. Bẫy ở C: học sinh thấy vế đầu dùng "any" rồi dùng luôn "any" cho vế sau mà không để ý câu đã chuyển sang khẳng định.' },
    { sec: 'much / many', lvl: 'TH', name: 'Câu 5', pts: 1, text: 'How ___ water do you drink every day?', opts: o4('many', 'a lot', 'much', 'few'), ans: 'C', why: '<i>Water</i> là danh từ không đếm được nên hỏi số lượng bằng <i>How much</i>.' },
    { sec: 'Danh từ không đếm được', lvl: 'NC', name: 'Câu 6', pts: 1, text: 'Which sentence is correct?', opts: o4('I need a advice from you.', 'There are many rice in the bowl.', 'She bought two breads.', 'He gave me some useful information.'), ans: 'D', why: '<i>Information</i> là danh từ không đếm được, đi với <i>some</i> và không thêm -s → D đúng. A sai vì "advice" không đếm được nên không dùng "a"; B sai vì "rice" không đếm được nên phải dùng "much" và "is"; C sai vì "bread" không đếm được, phải nói "two loaves of bread".' },
    { sec: 'Mạo từ a / an', lvl: 'NB', name: 'Câu 7', pts: 1, text: 'I have ___ apple and ___ banana for breakfast.', opts: o4('an – a', 'a – an', 'an – an', 'a – a'), ans: 'A', why: '<i>Apple</i> bắt đầu bằng nguyên âm nên dùng <i>an</i>; <i>banana</i> bắt đầu bằng phụ âm nên dùng <i>a</i>.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 8', pts: 1, text: 'A box holds 12 eggs. Mrs Hoa needs 40 eggs for a party and she can only buy whole boxes. How many boxes must she buy, and how many eggs will be left over?', opts: o4('3 boxes, 4 eggs left', '4 boxes, 8 eggs left', '4 boxes, 2 eggs left', '5 boxes, 20 eggs left'), ans: 'B', why: '3 hộp chỉ có 36 quả, chưa đủ 40, nên phải mua <b>4 hộp</b> = 48 quả; dùng 40 quả thì thừa 48 − 40 = <b>8 quả</b>. Chọn "3 boxes" là quên rằng 36 quả vẫn thiếu.' },
    { sec: 'some / any', lvl: 'TH', name: 'Câu 9', pts: 1, text: 'Are there ___ oranges in the basket?', opts: o4('much', 'a', 'any', 'an'), ans: 'C', why: 'Câu hỏi với danh từ đếm được số nhiều dùng <i>any</i>.' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 10', pts: 1, text: 'Choose the underlined part that needs correction: <u>How much</u> apples <u>do</u> you <u>want</u> <u>for</u> lunch?', opts: o4('How much', 'do', 'want', 'for'), ans: 'A', why: '<i>Apples</i> là danh từ đếm được số nhiều nên phải hỏi bằng <i>How many</i>. Bẫy là học sinh quen câu "How much…?" khi hỏi về số lượng nói chung, nhưng "much" chỉ dùng với danh từ không đếm được. Ba phần còn lại đều đúng.' },
    { sec: 'Mạo từ the', lvl: 'NB', name: 'Câu 11', pts: 1, text: '___ sun rises in the east.', opts: o4('A', 'The', 'An', 'Some'), ans: 'B', why: 'Những vật duy nhất trên đời như mặt trời, mặt trăng luôn đi với mạo từ xác định <i>the</i>.' },
    { sec: 'much / many', lvl: 'TH', name: 'Câu 12', pts: 1, text: 'I don\'t have ___ money with me today.', opts: o4('many', 'a few', 'some', 'much'), ans: 'D', why: '<i>Money</i> là danh từ không đếm được, trong câu phủ định dùng <i>much</i>.' },
    { sec: 'Danh từ', lvl: 'NB', name: 'Câu 13', pts: 1, text: 'Which word is an uncountable noun?', opts: o4('water', 'book', 'chair', 'apple'), ans: 'A', why: '<i>Water</i> không đếm được (không nói "two waters"); <i>book, chair, apple</i> đều đếm được và có dạng số nhiều.' },
    { sec: 'Lượng từ và mạo từ', lvl: 'NC', name: 'Câu 14', pts: 1, text: 'We bought ___ bread and ___ tomatoes at ___ market near my house.', opts: o4('some – any – a', 'any – some – the', 'some – some – the', 'a – some – a'), ans: 'C', why: 'Câu khẳng định nên cả hai chỗ đầu dùng <i>some</i> (some bread — không đếm được; some tomatoes — đếm được số nhiều). Chỗ cuối có cụm xác định "near my house" nên dùng <i>the market</i>. Bẫy ở A: dùng "any" trong câu khẳng định; bẫy ở D: dùng "a bread" với danh từ không đếm được.' },
    { sec: 'Mạo từ', lvl: 'TH', name: 'Câu 15', pts: 1, text: 'There is ___ old tree in front of ___ school.', opts: o4('a – the', 'an – the', 'an – a', 'the – an'), ans: 'B', why: '<i>Old</i> bắt đầu bằng nguyên âm nên dùng <i>an</i>; "the school" là ngôi trường đã xác định.' },
    { sec: 'Câu đồng nghĩa', lvl: 'NC', name: 'Câu 16', pts: 1, text: 'Choose the sentence that has the closest meaning to: "There isn\'t much sugar left."', opts: o4('There is a lot of sugar left.', 'There are few sugars left.', 'We have plenty of sugar now.', 'We have only a little sugar left.'), ans: 'D', why: '"Không còn nhiều đường" nghĩa là chỉ còn một ít → <i>only a little sugar</i>. Bẫy ở B: dùng "few" và thêm -s cho "sugar", nhưng <i>sugar</i> là danh từ không đếm được nên phải dùng "a little" và không có dạng số nhiều.' },
    { sec: 'Mạo từ the', lvl: 'NB', name: 'Câu 17', pts: 1, text: 'She plays ___ piano very well.', opts: o4('a', 'an', 'the', 'some'), ans: 'C', why: 'Với nhạc cụ, sau động từ "play" ta dùng mạo từ <i>the</i>: play the piano.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 18', pts: 1, text: 'A bottle of water costs 8000 dong and a sandwich costs 22000 dong. Nam has 100000 dong. He buys two sandwiches and three bottles of water. How much money does he have left?', opts: o4('32000 dong', '28000 dong', '38000 dong', '30000 dong'), ans: 'A', why: 'Hai chiếc bánh: 2 × 22000 = 44000 đồng. Ba chai nước: 3 × 8000 = 24000 đồng. Tổng 68000 đồng, còn lại 100000 − 68000 = <b>32000 đồng</b>. Chọn 38000 là nhầm chỉ mua hai chai nước.' },
    { sec: 'Lời mời', lvl: 'TH', name: 'Câu 19', pts: 1, text: 'Would you like ___ tea?', opts: o4('many', 'a', 'an', 'some'), ans: 'D', why: 'Trong lời mời, lời đề nghị ta dùng <i>some</i> ngay cả khi câu có dạng nghi vấn.' },
    { sec: 'Lượng từ', lvl: 'NC', name: 'Câu 20', pts: 1, text: 'My mother buys ___ kilos of rice every month, but she doesn\'t buy ___ meat.', opts: o4('much – many', 'ten – much', 'any – some', 'a few – many'), ans: 'B', why: '"Kilos" là danh từ đếm được số nhiều nên đi với số đếm <i>ten</i>; <i>meat</i> không đếm được, lại ở câu phủ định nên dùng <i>much</i>. Bẫy ở D: "many meat" sai vì "many" chỉ đi với danh từ đếm được.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>Yesterday my mother and I went to <b>(21)___</b> supermarket near our house. We bought <b>(22)___</b> vegetables, two kilos of rice and <b>(23)___</b> beef. My mother also wanted to buy some fruit, but there weren\'t <b>(24)___</b> good oranges that day. At home she made <b>(25)___</b> bowl of delicious soup for each of us.<br><br><b>Câu 21.</b> … we went to <b>(21)___</b> supermarket near our house.', opts: o4('a', 'an', 'the', 'some'), ans: 'C', why: 'Siêu thị đã được xác định bằng cụm "near our house" nên dùng mạo từ <i>the</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> We bought <b>(22)___</b> vegetables, two kilos of rice …', opts: o4('some', 'much', 'a', 'an'), ans: 'A', why: 'Câu khẳng định với danh từ đếm được số nhiều "vegetables" nên dùng <i>some</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> … two kilos of rice and <b>(23)___</b> beef.', opts: o4('a few', 'half a kilo of', 'many', 'two'), ans: 'B', why: '<i>Beef</i> là danh từ không đếm được nên phải đong bằng đơn vị: <i>half a kilo of beef</i>. Bẫy ở A và C: "a few" và "many" chỉ đi với danh từ đếm được; bẫy ở D là đếm trực tiếp "two beef", điều không thể trong tiếng Anh.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> … but there weren\'t <b>(24)___</b> good oranges that day.', opts: o4('some', 'much', 'a', 'any'), ans: 'D', why: 'Câu phủ định với danh từ đếm được số nhiều nên dùng <i>any</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> At home she made <b>(25)___</b> bowl of delicious soup for each of us.', opts: o4('some', 'an', 'a', 'many'), ans: 'C', why: '<i>Bowl</i> là danh từ đếm được số ít bắt đầu bằng phụ âm nên dùng <i>a bowl of…</i>.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>In Viet Nam many families go to the market early in the morning. At the market you can buy fresh vegetables, fruit, meat and fish. The sellers put their goods on small tables or on the ground. A kilo of rice costs about 20000 dong, and a kilo of pork costs about 130000 dong. Many young people now prefer supermarkets because they are clean and cool, and the price is printed on every item. However, food at the market is often fresher and cheaper. Mrs Lan, a seller at Ben Thanh Market, says she has many customers every day, but she sells the most fruit at the weekend.<br><br><b>Câu 26.</b> Why do many young people prefer supermarkets?', opts: o4('Because they are clean and the prices are clear.', 'Because supermarket food is always cheaper.', 'Because supermarkets open very early.', 'Because they can talk to the sellers there.'), ans: 'A', why: 'Bài nêu hai lí do: siêu thị "clean and cool" và "the price is printed on every item". Bẫy ở B: bài nói ngược lại — hàng ở chợ thường RẺ HƠN ("fresher and cheaper"), nên không thể nói đồ siêu thị luôn rẻ hơn.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> How much does a kilo of pork cost?', opts: o4('About 20000 dong.', 'About 100000 dong.', 'About 150000 dong.', 'About 130000 dong.'), ans: 'D', why: 'Bài viết: "a kilo of pork costs about 130000 dong". Con số 20000 là giá một cân gạo.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> Mrs Hoa buys three kilos of rice and two kilos of pork at the market. How much does she pay?', opts: o4('300000 dong', '320000 dong', '280000 dong', '350000 dong'), ans: 'B', why: 'Gạo: 3 × 20000 = 60000 đồng. Thịt lợn: 2 × 130000 = 260000 đồng. Tổng cộng <b>320000 đồng</b>. Chọn 280000 là nhầm chỉ mua một cân gạo.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> When does Mrs Lan sell the most fruit?', opts: o4('Early in the morning.', 'On Monday.', 'At the weekend.', 'In the evening.'), ans: 'C', why: 'Câu cuối bài: "she sells the most fruit at the weekend".' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 30', pts: 1, text: '<b>Câu 30.</b> Which statement is NOT true according to the passage?', opts: o4('Food at the market is usually more expensive.', 'Sellers put their goods on tables or on the ground.', 'Supermarkets show the price of every item.', 'Mrs Lan has a lot of customers every day.'), ans: 'A', why: 'Bài khẳng định "food at the market is often fresher and cheaper", nghĩa là RẺ HƠN chứ không đắt hơn, nên A sai. Bẫy là chữ "market" xuất hiện nhiều lần khiến học sinh thấy quen mà bỏ qua từ trái nghĩa "expensive". Ba câu còn lại đều đúng với bài.' },
  ],
},

/* ═══════════ ĐỀ 19 — ÔN TẬP CÂU HỎI WH- VÀ YES/NO ═══════════ */
{
  id: 10719, title: 'Đề 19 · Ôn tập câu hỏi — chọn từ để hỏi theo câu trả lời', time: 60,
  questions: [
    { sec: 'Phát âm', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Choose the word in which the letters <b>wh</b> are pronounced /h/.', opts: o4('what', 'who', 'when', 'where'), ans: 'B', why: 'Trong <i>who</i>, "wh" đọc là /h/ (/huː/). Ba từ còn lại đọc /w/.' },
    { sec: 'Trọng âm', lvl: 'TH', name: 'Câu 2', pts: 1, text: 'Choose the word that has a different stress pattern from the others.', opts: o4('morning', 'answer', 'question', 'tonight'), ans: 'D', why: '<i>Tonight</i> nhấn âm tiết thứ hai (to-NIGHT); <i>morning, answer, question</i> đều nhấn âm tiết thứ nhất.' },
    { sec: 'Phát âm', lvl: 'NC', name: 'Câu 3', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently from the others: <u>Ch</u>ristmas — <u>ch</u>ildren — <u>ch</u>air — <u>ch</u>eese', opts: o4('Christmas', 'children', 'chair', 'cheese'), ans: 'A', why: 'Trong <i>Christmas</i>, "ch" đọc /k/; ba từ còn lại đọc /tʃ/. Bẫy là học sinh thấy "ch" thì mặc định đọc /tʃ/ mà quên nhóm từ gốc Hy Lạp như <i>Christmas, school, chemistry</i>.' },
    { sec: 'Từ để hỏi', lvl: 'NB', name: 'Câu 4', pts: 1, text: '___ are you from? — I\'m from Hue.', opts: o4('What', 'Who', 'Where', 'When'), ans: 'C', why: 'Câu trả lời chỉ nơi chốn ("from Hue") nên hỏi bằng <i>Where</i>.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 5', pts: 1, text: 'Look at Lan\'s week: Monday 15.00 English club; Wednesday 15.00 Music club; Saturday 8.00 swimming. Someone asks: "How often does Lan go to a club after school on weekdays?" Which answer is correct?', opts: o4('Once a week.', 'Twice a week.', 'Three times a week.', 'Every day.'), ans: 'B', why: 'Chỉ thứ Hai và thứ Tư là ngày trong tuần có câu lạc bộ sau giờ học → <b>twice a week</b>. Buổi bơi thứ Bảy không tính vì câu hỏi giới hạn "on weekdays" (các ngày trong tuần).' },
    { sec: 'Từ để hỏi', lvl: 'TH', name: 'Câu 6', pts: 1, text: '___ does your mother go to work? — By motorbike.', opts: o4('How', 'What', 'Where', 'Why'), ans: 'A', why: 'Câu trả lời nói về phương tiện ("By motorbike") nên hỏi bằng <i>How</i>.' },
    { sec: 'Câu hỏi Yes/No', lvl: 'NC', name: 'Câu 7', pts: 1, text: '"___ your brother study in the library yesterday?" — "No, he studied at home."', opts: o4('Does', 'Is', 'Was', 'Did'), ans: 'D', why: 'Câu trả lời dùng "studied" nên câu hỏi ở quá khứ đơn; động từ chính "study" ở nguyên thể nên trợ động từ là <i>Did</i>. Bẫy ở C: "Was" chỉ dùng khi sau nó là tính từ hoặc V-ing, không đi với động từ nguyên thể.' },
    { sec: 'Từ để hỏi', lvl: 'NB', name: 'Câu 8', pts: 1, text: '___ is your English teacher? — Mrs Hoa.', opts: o4('What', 'Where', 'Who', 'Why'), ans: 'C', why: 'Câu trả lời là tên một người nên hỏi bằng <i>Who</i>.' },
    { sec: 'Ghép câu hỏi', lvl: 'NC', name: 'Câu 9', pts: 1, text: 'Choose the correct question for this answer: "Because I want to be a doctor."', opts: o4('What do you study hard?', 'Why do you study hard?', 'How do you study hard?', 'When do you study hard?'), ans: 'B', why: 'Câu trả lời bắt đầu bằng "Because" — nêu lí do — nên câu hỏi phải dùng <i>Why</i>. Bẫy ở C: <i>How</i> hỏi CÁCH THỨC, câu trả lời sẽ phải là "By reading every day", không phải một lí do.' },
    { sec: 'How many / How much', lvl: 'TH', name: 'Câu 10', pts: 1, text: '___ books do you have? — About fifty.', opts: o4('How much', 'How often', 'How many', 'How long'), ans: 'C', why: '<i>Books</i> là danh từ đếm được số nhiều nên hỏi số lượng bằng <i>How many</i>.' },
    { sec: 'Từ để hỏi', lvl: 'NB', name: 'Câu 11', pts: 1, text: '___ is your birthday? — On 2 September.', opts: o4('When', 'Who', 'What', 'How'), ans: 'A', why: 'Câu trả lời là một ngày cụ thể nên hỏi bằng <i>When</i>.' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 12', pts: 1, text: 'Choose the underlined part that needs correction: <u>Where</u> <u>do</u> your parents <u>work</u> <u>in</u>?', opts: o4('Where', 'do', 'work', 'in'), ans: 'D', why: 'Từ để hỏi <i>Where</i> đã mang nghĩa "ở đâu" nên không được thêm giới từ "in" ở cuối câu. Bẫy là học sinh dịch từ tiếng Việt "làm việc ở đâu" rồi thêm "in" cho đủ chữ. Ba phần còn lại đều đúng.' },
    { sec: 'Từ để hỏi', lvl: 'TH', name: 'Câu 13', pts: 1, text: '___ old is your brother? — He is thirteen.', opts: o4('What', 'How', 'Who', 'Which'), ans: 'B', why: 'Hỏi tuổi dùng cấu trúc cố định <i>How old…?</i>.' },
    { sec: 'Câu hỏi Yes/No', lvl: 'NB', name: 'Câu 14', pts: 1, text: '___ you like ice cream? — Yes, I do.', opts: o4('Do', 'Are', 'Is', 'Does'), ans: 'A', why: 'Câu trả lời "Yes, I do" cho biết trợ động từ phải là <i>Do</i>.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 15', pts: 1, text: 'A shop opens at 8.00 and closes at 21.00 every day. Someone asks: "How long is the shop open each day?" Which answer is correct?', opts: o4('11 hours.', '12 hours.', '13 hours.', '14 hours.'), ans: 'C', why: 'Từ 8 giờ sáng đến 21 giờ: 21 − 8 = <b>13 tiếng</b>. Chọn 12 là nhầm tính đến 20 giờ.' },
    { sec: 'Từ để hỏi', lvl: 'TH', name: 'Câu 16', pts: 1, text: '___ is the weather like in Da Lat? — It is cool and dry.', opts: o4('How', 'Where', 'Who', 'What'), ans: 'D', why: 'Cấu trúc cố định hỏi về thời tiết là <i>What … like?</i>. Nếu dùng "How" thì phải bỏ chữ "like": "How is the weather?".' },
    { sec: 'Which / What', lvl: 'NC', name: 'Câu 17', pts: 1, text: '"___ of these two bags do you like better?" — "The red one."', opts: o4('What', 'Which', 'How', 'Whose'), ans: 'B', why: 'Khi chọn trong một số lượng HẠN CHẾ đã nêu rõ ("these two bags") thì dùng <i>Which</i>. Bẫy ở A: <i>What</i> dùng khi phạm vi lựa chọn mở, không giới hạn.' },
    { sec: 'Whose', lvl: 'NB', name: 'Câu 18', pts: 1, text: '___ pen is this? — It\'s Mai\'s.', opts: o4('Who', 'Which', 'Whose', 'What'), ans: 'C', why: 'Câu trả lời chỉ người sở hữu ("Mai\'s") nên hỏi bằng <i>Whose</i>.' },
    { sec: 'Ghép câu hỏi', lvl: 'NC', name: 'Câu 19', pts: 1, text: 'Which question goes with the answer "It takes me twenty minutes."?', opts: o4('How long does it take you to go to school?', 'How far is your school from your house?', 'How often do you go to school?', 'What time do you go to school?'), ans: 'A', why: 'Câu trả lời cho biết THỜI LƯỢNG nên câu hỏi phải là <i>How long…?</i>. Bẫy ở B: <i>How far</i> hỏi khoảng cách, câu trả lời phải là "about two kilometres"; bẫy ở D: <i>What time</i> hỏi giờ khởi hành, câu trả lời phải là "at six thirty".' },
    { sec: 'Câu hỏi Yes/No', lvl: 'TH', name: 'Câu 20', pts: 1, text: '___ your friends playing football in the yard now?', opts: o4('Do', 'Does', 'Is', 'Are'), ans: 'D', why: 'Thì hiện tại tiếp diễn với chủ ngữ số nhiều "your friends" nên dùng <i>Are</i>.' },
    { sec: 'Hoàn thành hội thoại', lvl: 'NB', name: 'Câu 21', pts: 1, text: '<i>Complete the dialogue (Câu 21–25).</i><br>Tom: Hi, Mai. <b>(21)___</b> do you live?<br>Mai: I live in Cau Giay, near the park.<br>Tom: <b>(22)___</b> do you go to school?<br>Mai: By bus. It takes about fifteen minutes.<br>Tom: <b>(23)___</b> lessons do you have every day?<br>Mai: Usually five. <b>(24)___</b> you have five lessons, too?<br>Tom: Yes, I do. <b>(25)___</b> is your favourite subject?<br>Mai: English. I love it.<br><br><b>Câu 21.</b> <b>(21)___</b> do you live?', opts: o4('What', 'Who', 'Where', 'When'), ans: 'C', why: 'Mai trả lời "I live in Cau Giay" — chỉ nơi chốn, nên hỏi bằng <i>Where</i>.' },
    { sec: 'Hoàn thành hội thoại', lvl: 'TH', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> <b>(22)___</b> do you go to school?', opts: o4('What', 'How', 'Where', 'Why'), ans: 'B', why: 'Mai trả lời "By bus" — phương tiện đi lại, nên hỏi bằng <i>How</i>.' },
    { sec: 'Hoàn thành hội thoại', lvl: 'NC', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> <b>(23)___</b> lessons do you have every day?', opts: o4('How many', 'How much', 'How often', 'How long'), ans: 'A', why: 'Câu trả lời "Usually five" là một CON SỐ tiết học, mà "lessons" đếm được nên dùng <i>How many</i>. Bẫy ở C: <i>How often</i> hỏi tần suất, câu trả lời sẽ phải là "every day" chứ không phải "five".' },
    { sec: 'Hoàn thành hội thoại', lvl: 'NB', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> <b>(24)___</b> you have five lessons, too?', opts: o4('Are', 'Is', 'Does', 'Do'), ans: 'D', why: 'Tom đáp "Yes, I do" nên câu hỏi bắt đầu bằng <i>Do</i>.' },
    { sec: 'Hoàn thành hội thoại', lvl: 'TH', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> <b>(25)___</b> is your favourite subject?', opts: o4('Who', 'What', 'Where', 'How'), ans: 'B', why: 'Câu trả lời là tên một môn học ("English") nên hỏi bằng <i>What</i>.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>Our school has a small library on the first floor. It opens from 7.30 to 16.30 from Monday to Friday. There are about 5000 books there: story books, science books, dictionaries and magazines. Each student can borrow two books at a time and keep them for one week. If you return a book late, you must pay 2000 dong for each late day. Mrs Thu, the librarian, is very kind. She helps students find the books they need. On Friday afternoon there is a reading club in the library, and about twenty students join it every week.<br><br><b>Câu 26.</b> How many books can a student borrow at a time?', opts: o4('One.', 'Three.', 'Two.', 'Five.'), ans: 'C', why: 'Bài viết: "Each student can borrow two books at a time."' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> Which question can be answered with information from the passage?', opts: o4('How much must a student pay for each late day?', 'How many students study in the school?', 'How old is Mrs Thu?', 'Where does Mrs Thu live?'), ans: 'A', why: 'Bài nêu rõ mức phạt 2000 đồng mỗi ngày trả muộn. Bẫy ở B: bài có con số "about twenty students" và "about 5000 books" khiến học sinh tưởng đã biết sĩ số trường, nhưng hai con số ấy nói về câu lạc bộ đọc sách và số sách. Tuổi và nơi ở của cô Thu hoàn toàn không được nhắc.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> What time does the library close?', opts: o4('At 7.30.', 'At 15.30.', 'At 17.30.', 'At 16.30.'), ans: 'D', why: 'Bài viết "It opens from 7.30 to 16.30", nghĩa là đóng cửa lúc 16.30.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> Nam borrowed a book on Monday 5 May and returned it on Monday 19 May. How much did he have to pay?', opts: o4('7000 dong', '14000 dong', '10000 dong', '28000 dong'), ans: 'B', why: 'Mượn một tuần nên hạn trả là ngày 12 tháng 5. Nam trả ngày 19, tức muộn 7 ngày: 7 × 2000 = <b>14000 đồng</b>. Chọn 28000 là tính muộn cả 14 ngày mà quên một tuần được mượn miễn phí.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 30', pts: 1, text: '<b>Câu 30.</b> Which statement is NOT true about the library?', opts: o4('The library is closed at the weekend.', 'Mrs Thu helps students find books.', 'The library has only story books and magazines.', 'Students pay 2000 dong for each late day.'), ans: 'C', why: 'Ngoài truyện và tạp chí, thư viện còn có sách khoa học và từ điển, nên chữ "only" làm câu C sai. Bẫy là ba loại sách đầu đều có thật trong bài khiến học sinh đọc lướt rồi cho là đúng. Câu A đúng vì thư viện chỉ mở từ thứ Hai đến thứ Sáu.' },
  ],
},

/* ═══════════ ĐỀ 20 — ÔN TẬP TRẠNG TỪ TẦN SUẤT VÀ TRẬT TỰ TỪ ═══════════ */
{
  id: 10720, title: 'Đề 20 · Ôn tập trạng từ tần suất — vị trí always/often/never, trật tự từ', time: 60,
  questions: [
    { sec: 'Phát âm', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently from the others: s<u>o</u>metimes — m<u>o</u>ther — br<u>o</u>ther — <u>o</u>pen', opts: o4('sometimes', 'mother', 'brother', 'open'), ans: 'D', why: 'Chữ "o" trong <i>open</i> đọc /əʊ/; trong <i>sometimes, mother, brother</i> đều đọc /ʌ/.' },
    { sec: 'Trọng âm', lvl: 'NC', name: 'Câu 2', pts: 1, text: 'Choose the word that has a different stress pattern from the others.', opts: o4('seldom', 'often', 'before', 'always'), ans: 'C', why: '<i>Before</i> nhấn âm tiết thứ hai (be-FORE); <i>seldom, often, always</i> đều nhấn âm tiết thứ nhất. Bẫy là cả bốn từ đều hai âm tiết nên học sinh dễ chọn bừa, phải nhớ rằng các trạng từ tần suất quen thuộc đều nhấn đầu.' },
    { sec: 'Phát âm', lvl: 'TH', name: 'Câu 3', pts: 1, text: 'Choose the word whose final <b>-s</b> is pronounced differently from the others.', opts: o4('plays', 'works', 'reads', 'goes'), ans: 'B', why: 'Đuôi -s trong <i>works</i> đọc /s/ vì đứng sau âm vô thanh /k/. Ba từ còn lại kết thúc bằng âm hữu thanh nên -s đọc /z/.' },
    { sec: 'Vị trí trạng từ', lvl: 'NC', name: 'Câu 4', pts: 1, text: 'Choose the correct sentence.', opts: o4('My father always gets up at five.', 'My father gets always up at five.', 'Always my father gets up at five.', 'My father gets up always at five.'), ans: 'A', why: 'Với động từ thường, trạng từ tần suất đứng NGAY TRƯỚC động từ. B sai vì chen vào giữa động từ và tiểu từ "up"; C sai vì trạng từ tần suất không đứng đầu câu kiểu này; D sai vì đặt sau cụm động từ.' },
    { sec: 'Trạng từ tần suất', lvl: 'NB', name: 'Câu 5', pts: 1, text: 'She is ___ late for school.', opts: o4('never is', 'not never', 'always not', 'never'), ans: 'D', why: 'Sau động từ "is" chỉ cần trạng từ tần suất <i>never</i>; bản thân "never" đã mang nghĩa phủ định.' },
    { sec: 'Trả lời tần suất', lvl: 'TH', name: 'Câu 6', pts: 1, text: 'How often do you go swimming? — ___', opts: o4('At six o\'clock.', 'Twice a week.', 'For two hours.', 'In the swimming pool.'), ans: 'B', why: '<i>How often</i> hỏi tần suất nên trả lời bằng số lần: <i>Twice a week</i>. A trả lời giờ, C trả lời thời lượng, D trả lời nơi chốn.' },
    { sec: 'Trạng từ tần suất', lvl: 'NB', name: 'Câu 7', pts: 1, text: 'We ___ go to school on Sunday because it is a day off.', opts: o4('always', 'usually', 'never', 'often'), ans: 'C', why: 'Chủ nhật là ngày nghỉ nên không bao giờ đi học: <i>never</i>.' },
    { sec: 'Trật tự từ', lvl: 'NC', name: 'Câu 8', pts: 1, text: 'Put the words in the correct order: never / is / he / at home / in the evening', opts: o4('He is never at home in the evening.', 'He never is at home in the evening.', 'Never he is at home in the evening.', 'He is at home never in the evening.'), ans: 'A', why: 'Với động từ <i>to be</i>, trạng từ tần suất đứng SAU động từ: "He is never…". Bẫy ở B: học sinh nhớ quy tắc "trạng từ đứng trước động từ" của động từ thường rồi áp dụng nhầm cho "to be".' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 9', pts: 1, text: 'Nam plays football three times a week and goes swimming twice a week. Each football game lasts 90 minutes and each swim lasts 45 minutes. How much time does he spend on these two sports in one week?', opts: o4('4 hours and 30 minutes', '5 hours', '5 hours and 30 minutes', '6 hours'), ans: 'D', why: 'Bóng đá: 3 × 90 = 270 phút. Bơi: 2 × 45 = 90 phút. Tổng 360 phút = <b>6 giờ</b>. Chọn "4 hours and 30 minutes" là quên nhân số buổi bơi.' },
    { sec: 'Câu hỏi tần suất', lvl: 'TH', name: 'Câu 10', pts: 1, text: '___ do you visit your grandparents? — Once a month.', opts: o4('How many', 'How much', 'How often', 'How long'), ans: 'C', why: 'Câu trả lời "Once a month" là tần suất nên hỏi bằng <i>How often</i>.' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 11', pts: 1, text: 'Choose the underlined part that needs correction: My sister <u>often</u> <u>is</u> tired <u>after</u> a long day <u>at school</u>.', opts: o4('often', 'is', 'after', 'at school'), ans: 'B', why: 'Trật tự đúng phải là <i>is often</i> vì trạng từ tần suất đứng SAU động từ "to be"; chỗ sai cần sửa chính là vị trí của "is". Bẫy là học sinh quen công thức "often + V" nên tưởng "often is" đúng. Các giới từ "after" và "at school" đều dùng chuẩn.' },
    { sec: 'Trạng từ tần suất', lvl: 'NB', name: 'Câu 12', pts: 1, text: 'Tom ___ has breakfast at 6.30.', opts: o4('usually', 'usual', 'use', 'usualy'), ans: 'A', why: 'Cần một trạng từ và phải viết đúng chính tả: <i>usually</i>. "Usual" là tính từ, "usualy" viết thiếu một chữ l.' },
    { sec: 'Câu đồng nghĩa', lvl: 'NC', name: 'Câu 13', pts: 1, text: 'Choose the sentence that has the closest meaning to: "Mai hardly ever watches TV."', opts: o4('Mai watches TV every evening.', 'Mai often watches TV.', 'Mai almost never watches TV.', 'Mai never watches TV at all.'), ans: 'C', why: '<i>Hardly ever</i> nghĩa là gần như không bao giờ → <i>almost never</i>. Bẫy ở D: "never … at all" là tuyệt đối không bao giờ, mạnh hơn hẳn "hardly ever" — Mai vẫn thỉnh thoảng xem TV.' },
    { sec: 'Câu hỏi với ever', lvl: 'TH', name: 'Câu 14', pts: 1, text: '___ Nam ever late for class? — No, never.', opts: o4('Does', 'Do', 'Are', 'Is'), ans: 'D', why: 'Sau chỗ trống là tính từ "late" nên cần động từ <i>to be</i>; chủ ngữ "Nam" số ít → <i>Is</i>.' },
    { sec: 'Vị trí trạng từ', lvl: 'NB', name: 'Câu 15', pts: 1, text: 'I ___ my homework in the evening.', opts: o4('am always do', 'always do', 'do always', 'always am doing'), ans: 'B', why: 'Với động từ thường, trạng từ tần suất đứng ngay trước động từ: <i>always do</i>.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 16', pts: 1, text: 'A bus to the city centre leaves every 20 minutes. The first bus leaves at 5.30. What time does the sixth bus of the day leave?', opts: o4('7.10', '6.50', '7.30', '6.30'), ans: 'A', why: 'Từ chuyến thứ nhất đến chuyến thứ sáu có 5 khoảng cách: 5 × 20 = 100 phút. 5.30 + 1 giờ 40 phút = <b>7.10</b>. Chọn 6.50 là chỉ đếm 4 khoảng cách.' },
    { sec: 'Trật tự từ', lvl: 'TH', name: 'Câu 17', pts: 1, text: 'Choose the sentence with the correct word order: she / goes / to school / by bike / every morning', opts: o4('She goes every morning to school by bike.', 'She by bike goes to school every morning.', 'She every morning goes to school by bike.', 'She goes to school by bike every morning.'), ans: 'D', why: 'Trật tự chuẩn là: chủ ngữ + động từ + nơi chốn + phương tiện + thời gian. Cụm chỉ thời gian đứng cuối câu.' },
    { sec: 'Trạng từ và liên từ', lvl: 'NC', name: 'Câu 18', pts: 1, text: 'My brother ___ plays video games, ___ he never forgets his homework.', opts: o4('never – but', 'always – so', 'sometimes – but', 'often – because'), ans: 'C', why: 'Vế sau có "never forgets his homework" mang ý tích cực, trái chiều với việc chơi điện tử, nên liên từ phải là <i>but</i> và tần suất hợp lí là <i>sometimes</i>. Bẫy ở A: nếu em ấy "never plays" thì vế "but he never forgets" mất hẳn ý tương phản; bẫy ở D: "because" đảo ngược quan hệ nhân quả.' },
    { sec: 'Trả lời tần suất', lvl: 'NB', name: 'Câu 19', pts: 1, text: 'How often is the English club meeting? — ___', opts: o4('For an hour.', 'Once a week.', 'At four o\'clock.', 'In Room 5.'), ans: 'B', why: '<i>How often</i> hỏi tần suất nên trả lời bằng số lần trong tuần: <i>Once a week</i>.' },
    { sec: 'Trật tự từ', lvl: 'TH', name: 'Câu 20', pts: 1, text: 'Put the words in the correct order to make a question: do / you / often / how / play / chess', opts: o4('How often do you play chess?', 'How often you do play chess?', 'How do you often play chess?', 'How often play you chess?'), ans: 'A', why: 'Cấu trúc câu hỏi là <i>How often + do/does + chủ ngữ + động từ nguyên thể</i>. Không tách "often" khỏi "how" và không đảo động từ chính lên trước chủ ngữ.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>My name is Duy. I <b>(21)___</b> get up at six o\'clock because my school is far from my house. I <b>(22)___</b> have breakfast at home, but on busy mornings I eat a sandwich on the way. My father <b>(23)___</b> takes me to school by motorbike; he only does it when it rains. After school I <b>(24)___</b> play badminton with my friends — about three times a week. In the evening I <b>(25)___</b> do my homework before dinner.<br><br><b>Câu 21.</b> I <b>(21)___</b> get up at six o\'clock because my school is far from my house.', opts: o4('never', 'hardly ever', 'always', 'rarely'), ans: 'C', why: 'Vế "because my school is far" giải thích lí do phải dậy sớm MỖI NGÀY nên tần suất phải là <i>always</i>. Bẫy ở A, B, D: cả ba đều mang nghĩa hiếm khi hoặc không bao giờ, mâu thuẫn với lí do nêu sau "because".' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> I <b>(22)___</b> have breakfast at home, but on busy mornings I eat a sandwich on the way.', opts: o4('never', 'not', 'seldom', 'usually'), ans: 'D', why: 'Ăn sáng ở nhà là việc thường lệ, chỉ trừ vài hôm bận nên dùng <i>usually</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> My father <b>(23)___</b> takes me to school by motorbike; he only does it when it rains.', opts: o4('seldom', 'always', 'often', 'usually'), ans: 'A', why: 'Vế sau nói rõ bố chỉ chở khi trời mưa, tức là rất ít khi → <i>seldom</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> After school I <b>(24)___</b> play badminton with my friends — about three times a week.', opts: o4('never', 'often', 'always', 'hardly ever'), ans: 'B', why: 'Ba lần một tuần là khá thường xuyên nhưng chưa phải mọi ngày, tương ứng với <i>often</i>. Bẫy ở C: <i>always</i> hàm ý ngày nào cũng chơi, không khớp với con số "three times a week".' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> In the evening I <b>(25)___</b> do my homework before dinner.', opts: o4('am', 'never', 'always', 'not'), ans: 'C', why: 'Đây là thói quen tốt hằng ngày của Duy nên dùng <i>always</i>, đặt ngay trước động từ "do".' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>Mr Tuan is a bus driver in Da Nang. He always starts work at 5.00 in the morning and finishes at 2.00 in the afternoon. He drives the same route eight times a day. He never eats breakfast at home; he usually buys a banh mi at the bus station. On Sundays he does not work, so he often takes his children to the beach. His wife sometimes goes with them, but she is usually busy at her shop. Mr Tuan says he is never bored with his job because he meets many interesting people every day.<br><br><b>Câu 26.</b> What time does Mr Tuan start work?', opts: o4('At 2.00 in the afternoon.', 'At 6.00 in the morning.', 'At 7.00 in the morning.', 'At 5.00 in the morning.'), ans: 'D', why: 'Bài viết: "He always starts work at 5.00 in the morning." Mốc 2.00 chiều là giờ tan làm.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> Where does Mr Tuan usually have breakfast?', opts: o4('At home with his family.', 'At the bus station.', 'On the bus with passengers.', 'At his wife\'s shop.'), ans: 'B', why: 'Bài viết: "he usually buys a banh mi at the bus station" và "never eats breakfast at home".' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> Which sentence is true about Mr Tuan\'s wife?', opts: o4('She does not always go to the beach with them.', 'She never goes to the beach with her family.', 'She drives a bus like her husband.', 'She works at the bus station on Sundays.'), ans: 'A', why: 'Bài viết "His wife sometimes goes with them" — <i>sometimes</i> nghĩa là thỉnh thoảng, tức không phải lúc nào cũng đi. Bẫy ở B: đọc lướt thấy vế "but she is usually busy" rồi kết luận bà không bao giờ đi, trong khi "sometimes" khẳng định có những lần bà vẫn đi cùng.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> How many hours does Mr Tuan work each working day?', opts: o4('8 hours.', '7 hours.', '9 hours.', '10 hours.'), ans: 'C', why: 'Ông làm từ 5 giờ sáng đến 14 giờ: 14 − 5 = <b>9 tiếng</b>. Chọn 8 là nhầm với con số "eight times a day" (số lượt chạy xe).' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 30', pts: 1, text: '<b>Câu 30.</b> Why is Mr Tuan never bored with his job?', opts: o4('Because he works only six days a week.', 'Because he meets many interesting people.', 'Because he drives the same route every day.', 'Because he has a long lunch break.'), ans: 'B', why: 'Câu cuối bài: "he is never bored with his job because he meets many interesting people every day".' },
  ],
},

/* ═══════════ ĐỀ 21 — PHÁT ÂM ĐUÔI -S/-ES VÀ -ED ═══════════ */
{
  id: 10721, title: 'Đề 21 · Phát âm đuôi -s/-es và -ed — /s/ /z/ /ɪz/ và /t/ /d/ /ɪd/', time: 60,
  questions: [
    { sec: 'Đuôi -s/-es', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Which word ends with the sound /ɪz/?', opts: o4('books', 'maps', 'watches', 'rooms'), ans: 'C', why: 'Sau âm gió /tʃ/ trong <i>watches</i>, đuôi -es phải đọc thành một âm tiết riêng /ɪz/. <i>Books, maps</i> đọc /s/, <i>rooms</i> đọc /z/.' },
    { sec: 'Đuôi -ed', lvl: 'TH', name: 'Câu 2', pts: 1, text: 'In which word is the ending <b>-ed</b> pronounced /ɪd/?', opts: o4('wanted', 'played', 'opened', 'cleaned'), ans: 'A', why: '<i>Wanted</i> có gốc kết thúc bằng /t/ nên -ed đọc /ɪd/; ba từ còn lại kết thúc bằng âm hữu thanh nên -ed chỉ đọc /d/.' },
    { sec: 'Đuôi -ed', lvl: 'NC', name: 'Câu 3', pts: 1, text: 'In which sentence do the two <u>underlined</u> endings have the SAME pronunciation?', opts: o4('He <u>washed</u> the dishes and <u>painted</u> the door.', 'She <u>helped</u> her mum and <u>cooked</u> dinner.', 'They <u>visited</u> Hue and <u>walked</u> to the beach.', 'We <u>opened</u> the box and <u>wanted</u> a new pen.'), ans: 'B', why: '<i>Helped</i> và <i>cooked</i> đều đứng sau âm vô thanh /p/, /k/ nên cùng đọc /t/. Bẫy ở A: học sinh thấy <i>washed</i> và <i>painted</i> cùng có đuôi -ed nên tưởng đọc giống nhau, thực ra là /t/ và /ɪd/; C và D cũng là hai âm khác nhau.' },
    { sec: 'Đuôi -s/-es', lvl: 'NB', name: 'Câu 4', pts: 1, text: 'Choose the word whose final <b>-s</b> is pronounced /s/.', opts: o4('pens', 'bags', 'chairs', 'desks'), ans: 'D', why: '<i>Desks</i> kết thúc bằng âm vô thanh /k/ nên -s đọc /s/. Ba từ còn lại kết thúc bằng âm hữu thanh /n/, /g/, /z/ nên -s đọc /z/.' },
    { sec: 'Đuôi -s/-es', lvl: 'TH', name: 'Câu 5', pts: 1, text: 'Choose the word that has a different final sound from the others.', opts: o4('brushes', 'cats', 'oranges', 'buses'), ans: 'B', why: '<i>Cats</i> đọc /s/; <i>brushes, oranges, buses</i> đều thêm âm tiết /ɪz/ vì gốc từ kết thúc bằng âm gió.' },
    { sec: 'Chính tả -ed', lvl: 'NB', name: 'Câu 6', pts: 1, text: 'Choose the correct past form of the verb <i>stop</i>.', opts: o4('stopped', 'stoped', 'stopeed', 'stopping'), ans: 'A', why: 'Động từ một âm tiết kết thúc bằng nguyên âm + phụ âm phải gấp đôi phụ âm trước khi thêm -ed: <i>stop → stopped</i>.' },
    { sec: 'Đuôi -ed', lvl: 'NC', name: 'Câu 7', pts: 1, text: 'Which group contains ONLY verbs whose <b>-ed</b> ending is pronounced /ɪd/?', opts: o4('asked – laughed – hoped', 'lived – played – carried', 'needed – painted – started', 'wanted – walked – ended'), ans: 'C', why: 'Cả <i>needed, painted, started</i> đều có gốc kết thúc bằng /d/ hoặc /t/ nên -ed đọc /ɪd/. Bẫy ở D: <i>wanted</i> và <i>ended</i> đúng là /ɪd/ nhưng <i>walked</i> đọc /t/, chỉ cần một từ sai là cả nhóm sai.' },
    { sec: 'Đuôi -s/-es', lvl: 'NC', name: 'Câu 8', pts: 1, text: 'Choose the sentence in which the <u>underlined</u> ending is pronounced differently from the other three.', opts: o4('My brother <u>reads</u> books every night.', 'She <u>plays</u> the piano very well.', 'He <u>opens</u> the window every morning.', 'Nam <u>stops</u> at the red light.'), ans: 'D', why: '<i>Stops</i> đứng sau âm vô thanh /p/ nên đọc /s/; <i>reads, plays, opens</i> đứng sau âm hữu thanh nên đọc /z/. Bẫy ở A: học sinh thấy <i>reads</i> viết bằng chữ "d" rồi đoán bừa là âm lạ, trong khi /d/ là âm hữu thanh nên -s vẫn đọc /z/.' },
    { sec: 'Đuôi -s/-es', lvl: 'NB', name: 'Câu 9', pts: 1, text: 'Choose the word whose ending adds ONE more syllable to the word.', opts: o4('boxes', 'plays', 'rooms', 'stops'), ans: 'A', why: '<i>Box</i> kết thúc bằng /ks/ nên -es đọc /ɪz/ và tạo thêm một âm tiết: <i>box</i> (1) → <i>boxes</i> (2). Ba từ kia vẫn giữ nguyên số âm tiết.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 10', pts: 1, text: 'Look at this list of verbs: <i>asked, visited, played, watched, needed, opened, helped, wanted</i>. How many of them have the <b>-ed</b> ending pronounced /ɪd/?', opts: o4('Two.', 'Four.', 'Three.', 'Five.'), ans: 'C', why: 'Chỉ có <i>visited, needed, wanted</i> đọc /ɪd/ vì gốc từ kết thúc bằng /t/ hoặc /d/ → <b>3</b> từ. Bẫy ở B: học sinh đếm thêm <i>opened</i> vì thấy chữ "e" trước "d", nhưng <i>opened</i> chỉ đọc /d/ (một âm tiết cuối).' },
    { sec: 'Đuôi -ed', lvl: 'TH', name: 'Câu 11', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently: work<u>ed</u> — want<u>ed</u> — wash<u>ed</u> — look<u>ed</u>', opts: o4('worked', 'wanted', 'washed', 'looked'), ans: 'B', why: '<i>Wanted</i> đọc /ɪd/; <i>worked, washed, looked</i> đều đứng sau âm vô thanh nên đọc /t/.' },
    { sec: 'Đuôi -s/-es', lvl: 'NC', name: 'Câu 12', pts: 1, text: 'Which pair of words has the SAME final sound?', opts: o4('teaches – changes', 'laughs – loves', 'hats – heads', 'wishes – works'), ans: 'A', why: '<i>Teaches</i> /ɪz/ và <i>changes</i> /ɪz/ giống nhau. Bẫy ở D: <i>wishes</i> đúng là /ɪz/ nhưng <i>works</i> chỉ đọc /s/; bẫy ở C: chữ viết "ts" và "ds" trông giống nhau nhưng đọc /s/ và /z/.' },
    { sec: 'Chính tả -s/-es', lvl: 'NB', name: 'Câu 13', pts: 1, text: 'Choose the correct form: "He ___ TV every evening."', opts: o4('watch', 'watchs', 'watching', 'watches'), ans: 'D', why: 'Động từ kết thúc bằng -ch phải thêm -es (không phải -s) ở ngôi thứ ba số ít: <i>watch → watches</i>.' },
    { sec: 'Đuôi -s/-es', lvl: 'TH', name: 'Câu 14', pts: 1, text: 'Choose the word whose final <b>-s</b> is pronounced /z/.', opts: o4('hopes', 'boys', 'books', 'cats'), ans: 'B', why: '<i>Boys</i> kết thúc bằng nguyên âm đôi (âm hữu thanh) nên -s đọc /z/; <i>hopes, books, cats</i> đứng sau /p/, /k/, /t/ nên đọc /s/.' },
    { sec: 'Chính tả -ed', lvl: 'NB', name: 'Câu 15', pts: 1, text: 'The past form of the verb <i>study</i> is ___.', opts: o4('studyed', 'studing', 'studied', 'studies'), ans: 'C', why: 'Động từ kết thúc bằng phụ âm + y thì đổi y thành i rồi thêm -ed: <i>study → studied</i>.' },
    { sec: 'Đuôi -ed', lvl: 'TH', name: 'Câu 16', pts: 1, text: 'Choose the word that does NOT end with the sound /t/.', opts: o4('jumped', 'kissed', 'danced', 'climbed'), ans: 'D', why: '<i>Climbed</i> có gốc kết thúc bằng âm hữu thanh /m/ nên -ed đọc /d/; ba từ còn lại đứng sau /p/, /s/ nên đọc /t/.' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 17', pts: 1, text: 'Choose the underlined part that needs correction: My brother <u>studyed</u> hard, <u>finished</u> his homework and <u>watched</u> TV <u>last night</u>.', opts: o4('studyed', 'finished', 'watched', 'last night'), ans: 'A', why: '<i>Study</i> kết thúc bằng phụ âm + y nên quá khứ phải là <i>studied</i>. Bẫy ở B: học sinh tưởng <i>finished</i> sai vì gốc từ kết thúc bằng -sh, nhưng quy tắc gấp đôi hay đổi y chỉ áp dụng cho trường hợp khác; "finished" viết hoàn toàn đúng.' },
    { sec: 'Đuôi -s/-es', lvl: 'TH', name: 'Câu 18', pts: 1, text: 'Choose the word that has a different final sound: <i>dogs — cooks — pens — cars</i>', opts: o4('dogs', 'cooks', 'pens', 'cars'), ans: 'B', why: '<i>Cooks</i> đọc /s/ vì đứng sau âm vô thanh /k/; <i>dogs, pens, cars</i> đều đọc /z/.' },
    { sec: 'Đuôi -ed', lvl: 'NC', name: 'Câu 19', pts: 1, text: 'Which sentence contains a verb whose <b>-ed</b> ending is pronounced /ɪd/?', opts: o4('They finished the game at ten.', 'She travelled to Hue last summer.', 'We invited ten friends to the party.', 'He phoned his grandmother yesterday.'), ans: 'C', why: '<i>Invited</i> có gốc kết thúc bằng /t/ nên -ed đọc /ɪd/. Bẫy ở B: <i>travelled</i> viết hai chữ l nên trông "dài" giống nhóm /ɪd/, nhưng gốc kết thúc bằng /l/ nên chỉ đọc /d/.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 20', pts: 1, text: 'In a pronunciation game, a verb is worth 1 point if its <b>-ed</b> ending is /t/, 2 points if it is /d/ and 3 points if it is /ɪd/. Minh has three verbs: <i>helped, opened, wanted</i>. How many points does he get?', opts: o4('5', '6', '7', '4'), ans: 'B', why: '<i>Helped</i> /t/ = 1 điểm, <i>opened</i> /d/ = 2 điểm, <i>wanted</i> /ɪd/ = 3 điểm → 1 + 2 + 3 = <b>6</b>. Bẫy ở A: học sinh xếp <i>opened</i> vào nhóm /t/ (1 điểm) nên chỉ được 5.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>Last Saturday my class <b>(21)___</b> a picnic at Bach Ma National Park. We <b>(22)___</b> the bus at seven o\'clock in the morning. The weather was cool, <b>(23)___</b> nobody felt tired. We walked to a small waterfall, <b>(24)___</b> many photos and had lunch under the trees. In the afternoon it rained heavily, so we came home <b>(25)___</b> than we planned.<br><br><b>Câu 21.</b> Last Saturday my class <b>(21)___</b> a picnic at Bach Ma National Park.', opts: o4('has', 'have', 'is having', 'had'), ans: 'D', why: 'Cụm thời gian "Last Saturday" cho biết câu ở thì quá khứ đơn nên dùng <i>had</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> We <b>(22)___</b> the bus at seven o\'clock in the morning.', opts: o4('caught', 'catched', 'catches', 'catching'), ans: 'A', why: '<i>Catch</i> là động từ bất quy tắc, quá khứ là <i>caught</i>, không thêm -ed thành "catched".' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> The weather was cool, <b>(23)___</b> nobody felt tired.', opts: o4('because', 'but', 'so', 'although'), ans: 'C', why: 'Trời mát là NGUYÊN NHÂN, "nobody felt tired" là KẾT QUẢ, nên dùng <i>so</i>. Bẫy ở A: <i>because</i> đảo ngược quan hệ, thành "trời mát bởi vì không ai thấy mệt" — vô lí.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> We walked to a small waterfall, <b>(24)___</b> many photos and had lunch under the trees.', opts: o4('taked', 'takes', 'taking', 'took'), ans: 'D', why: 'Ba động từ trong câu phải cùng thì quá khứ: walked – <i>took</i> – had. <i>Take</i> là động từ bất quy tắc nên quá khứ là <i>took</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> In the afternoon it rained heavily, so we came home <b>(25)___</b> than we planned.', opts: o4('early', 'earlier', 'more early', 'earliest'), ans: 'B', why: 'Có từ "than" nên phải dùng dạng so sánh hơn; <i>early</i> là tính từ hai âm tiết kết thúc bằng -y nên đổi thành <i>earlier</i>.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>Last month, Class 6C joined a clean-up day at Lang Sen Lake. Thirty students took part. They started at 7.30 in the morning. The boys collected plastic bottles and cans around the lake, and the girls picked up paper and dry leaves in the park. At 9.00 they stopped for a short break and drank some water. After the break, they painted the old benches green. They finished at 11.00. In the afternoon, their teacher showed them photos of the lake before and after the clean-up. Everyone was surprised at the difference.<br><br><b>Câu 26.</b> Which sentence is NOT true about the clean-up day?', opts: o4('The girls collected plastic bottles and cans.', 'The students had a short break at 9.00.', 'They painted the benches after the break.', 'The teacher showed them photos in the afternoon.'), ans: 'A', why: 'Bài đọc viết rõ "The boys collected plastic bottles and cans", còn các bạn nữ nhặt giấy và lá khô. Bẫy ở A là học sinh chỉ nhớ có việc "collected bottles and cans" mà không để ý nhóm nào làm việc đó.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> What time did the students start working?', opts: o4('At 9.00.', 'At 11.00.', 'At 7.00.', 'At 7.30.'), ans: 'D', why: 'Bài đọc: "They started at 7.30 in the morning."' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> What did the students do after the break?', opts: o4('They drank some water.', 'They collected dry leaves.', 'They painted the old benches.', 'They went home.'), ans: 'C', why: 'Bài đọc: "After the break, they painted the old benches green."' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> How long did the students work at the lake that morning?', opts: o4('Three and a half hours.', 'Four hours.', 'Three hours.', 'Two and a half hours.'), ans: 'A', why: 'Từ 7.30 đến 11.00 là <b>3 giờ 30 phút</b>. Bẫy ở B: học sinh lấy tròn 7.00 đến 11.00 thành 4 tiếng mà quên giờ bắt đầu là 7.30.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 30', pts: 1, text: '<b>Câu 30.</b> Which idea can be inferred from the passage?', opts: o4('The lake was already clean before that day.', 'Only the boys worked hard that morning.', 'The students finished the work in the afternoon.', 'The lake looked much better after the clean-up.'), ans: 'D', why: 'Câu cuối nói mọi người "was surprised at the difference" khi xem ảnh trước và sau, nghĩa là hồ đẹp hơn hẳn. Bẫy ở C: buổi chiều chỉ là lúc xem ảnh, còn việc dọn dẹp đã xong lúc 11.00; bẫy ở B: các bạn nữ cũng làm việc.' },
  ],
},
/* ═══════════ ĐỀ 22 — PHÁT ÂM NGUYÊN ÂM VÀ TRỌNG ÂM TỪ HAI ÂM TIẾT ═══════════ */
{
  id: 10722, title: 'Đề 22 · Phát âm nguyên âm và trọng âm — từ hai âm tiết', time: 60,
  questions: [
    { sec: 'Nguyên âm', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently: br<u>ea</u>d — b<u>ea</u>ch — h<u>ea</u>d — r<u>ea</u>dy', opts: o4('bread', 'beach', 'head', 'ready'), ans: 'B', why: '"ea" trong <i>beach</i> đọc /iː/; trong <i>bread, head, ready</i> đều đọc /e/.' },
    { sec: 'Nguyên âm', lvl: 'NC', name: 'Câu 2', pts: 1, text: 'In which pair do the two words have the SAME vowel sound?', opts: o4('son – soon', 'hat – hate', 'live – five', 'some – come'), ans: 'D', why: '<i>Some</i> /sʌm/ và <i>come</i> /kʌm/ cùng có /ʌ/. Bẫy ở A: <i>son</i> /sʌn/ và <i>soon</i> /suːn/ chỉ giống nhau ở chữ viết; bẫy ở C: <i>live</i> /lɪv/ khác hẳn <i>five</i> /faɪv/ dù cùng kết thúc bằng -ive.' },
    { sec: 'Trọng âm', lvl: 'TH', name: 'Câu 3', pts: 1, text: 'Which word is NOT stressed on the first syllable: <i>begin — happy — sister — dinner</i>?', opts: o4('begin', 'happy', 'sister', 'dinner'), ans: 'A', why: '<i>Begin</i> nhấn âm tiết thứ hai (be-GIN); <i>happy, sister, dinner</i> đều nhấn âm tiết thứ nhất.' },
    { sec: 'Nguyên âm', lvl: 'NB', name: 'Câu 4', pts: 1, text: 'Choose the word that contains the sound /iː/.', opts: o4('sit', 'ship', 'sheep', 'rich'), ans: 'C', why: '<i>Sheep</i> /ʃiːp/ có nguyên âm dài /iː/; <i>sit, ship, rich</i> đều có nguyên âm ngắn /ɪ/.' },
    { sec: 'Trọng âm', lvl: 'NC', name: 'Câu 5', pts: 1, text: 'Which sentence contains a word stressed on the SECOND syllable?', opts: o4('My sister wants to become a doctor.', 'The children play football in the garden.', 'My father reads a newspaper after lunch.', 'Her brother is a farmer in Ha Nam.'), ans: 'A', why: 'Trong câu A, từ <i>become</i> nhấn âm tiết thứ hai (be-COME). Bẫy ở B: <i>football</i> và <i>garden</i> đều là từ hai âm tiết nhưng nhấn âm đầu, học sinh dễ tưởng từ ghép dài thì nhấn phía sau.' },
    { sec: 'Nguyên âm', lvl: 'TH', name: 'Câu 6', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently: b<u>a</u>g — h<u>a</u>nd — c<u>a</u>t — m<u>a</u>ke', opts: o4('bag', 'hand', 'cat', 'make'), ans: 'D', why: 'Chữ "a" trong <i>make</i> đọc /eɪ/ vì có "e" câm ở cuối; ba từ còn lại đọc /æ/.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 7', pts: 1, text: 'Look at these words: <i>morning, between, teacher, hotel, sister, polite</i>. How many of them are stressed on the second syllable?', opts: o4('Two.', 'Three.', 'Four.', 'One.'), ans: 'B', why: '<i>Between, hotel, polite</i> nhấn âm tiết thứ hai → <b>3</b> từ. Bẫy ở A: học sinh quen đọc "HO-tel" theo kiểu tiếng Việt nên bỏ sót <i>hotel</i> và chỉ đếm được hai từ.' },
    { sec: 'Vần', lvl: 'NB', name: 'Câu 8', pts: 1, text: 'Choose the word that does NOT rhyme with the others.', opts: o4('day', 'play', 'buy', 'say'), ans: 'C', why: '<i>Buy</i> /baɪ/ có âm /aɪ/; <i>day, play, say</i> đều kết thúc bằng /eɪ/.' },
    { sec: 'Nguyên âm', lvl: 'NC', name: 'Câu 9', pts: 1, text: 'Which group of words all have the SAME vowel sound?', opts: o4('book – food – moon', 'see – sea – bread', 'cat – car – cake', 'cook – look – good'), ans: 'D', why: '<i>Cook, look, good</i> đều có nguyên âm ngắn /ʊ/. Bẫy ở A: cùng viết "oo" nhưng <i>food</i> và <i>moon</i> đọc /uː/, chỉ <i>book</i> đọc /ʊ/; bẫy ở B: <i>see</i> và <i>sea</i> đọc /iː/ còn <i>bread</i> đọc /e/.' },
    { sec: 'Trọng âm', lvl: 'TH', name: 'Câu 10', pts: 1, text: 'Which word has a different stress pattern from the word <i>city</i>?', opts: o4('relax', 'window', 'busy', 'evening'), ans: 'A', why: '<i>City</i> nhấn âm tiết thứ nhất, và <i>window, busy, evening</i> cũng vậy; chỉ <i>relax</i> nhấn âm tiết thứ hai (re-LAX).' },
    { sec: 'Nguyên âm', lvl: 'NB', name: 'Câu 11', pts: 1, text: 'Choose the word that contains the sound /aɪ/.', opts: o4('big', 'sit', 'night', 'ship'), ans: 'C', why: '<i>Night</i> /naɪt/ có nguyên âm đôi /aɪ/; ba từ còn lại có /ɪ/.' },
    { sec: 'Nguyên âm', lvl: 'TH', name: 'Câu 12', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently: <u>a</u>bout — <u>a</u>fter — <u>a</u>go — <u>a</u>gain', opts: o4('about', 'after', 'ago', 'again'), ans: 'B', why: 'Chữ "a" đầu từ trong <i>after</i> đọc /ɑː/ và mang trọng âm; trong <i>about, ago, again</i> đều là âm yếu /ə/.' },
    { sec: 'Vần', lvl: 'NC', name: 'Câu 13', pts: 1, text: 'Mai wants to find a word that rhymes with <i>heard</i>. Which word should she choose?', opts: o4('bird', 'beard', 'hard', 'head'), ans: 'A', why: '<i>Heard</i> /hɜːd/ và <i>bird</i> /bɜːd/ cùng vần /ɜːd/. Bẫy ở B: <i>beard</i> chỉ khác <i>heard</i> một chữ cái nhưng đọc /bɪəd/; bẫy ở C: <i>hard</i> /hɑːd/ giống về mặt chữ viết chứ không giống về âm.' },
    { sec: 'Phụ âm', lvl: 'NC', name: 'Câu 14', pts: 1, text: 'In which word is the letter <b>s</b> pronounced /z/?', opts: o4('sister', 'listen', 'sport', 'music'), ans: 'D', why: 'Trong <i>music</i> /ˈmjuːzɪk/, chữ "s" đọc /z/. Bẫy ở B: <i>listen</i> có chữ "s" nhưng là âm câm, hoàn toàn không phát âm — nhiều học sinh vẫn đọc thành /lɪstən/.' },
    { sec: 'Âm tiết', lvl: 'NB', name: 'Câu 15', pts: 1, text: 'Choose the word that has TWO syllables.', opts: o4('friend', 'school', 'pupil', 'strong'), ans: 'C', why: '<i>Pupil</i> có hai âm tiết (pu-pil); <i>friend, school, strong</i> đều chỉ có một âm tiết dù viết khá dài.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 16', pts: 1, text: 'In a word game, a player gets 1 point for a word stressed on the first syllable and 2 points for a word stressed on the second syllable. Lan has four words: <i>autumn, hotel, market, begin</i>. How many points does she get?', opts: o4('5', '6', '7', '8'), ans: 'B', why: '<i>Autumn</i> và <i>market</i> nhấn âm đầu (1 + 1), <i>hotel</i> và <i>begin</i> nhấn âm sau (2 + 2) → tổng <b>6</b> điểm. Bẫy ở D: học sinh cho rằng cả bốn từ hai âm tiết đều nhấn âm thứ hai nên tính 4 × 2 = 8.' },
    { sec: 'Nguyên âm', lvl: 'TH', name: 'Câu 17', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently: m<u>o</u>nth — l<u>o</u>ve — c<u>o</u>me — h<u>o</u>me', opts: o4('month', 'love', 'come', 'home'), ans: 'D', why: 'Chữ "o" trong <i>home</i> đọc /əʊ/; trong <i>month, love, come</i> đều đọc /ʌ/.' },
    { sec: 'Âm tiết', lvl: 'NC', name: 'Câu 18', pts: 1, text: 'Choose the word that has a different NUMBER of syllables from the other three.', opts: o4('family', 'brother', 'sister', 'cousin'), ans: 'A', why: '<i>Family</i> có ba âm tiết (fa-mi-ly); <i>brother, sister, cousin</i> đều hai âm tiết. Bẫy là học sinh đọc nhanh "fam-ly" thành hai âm tiết rồi cho rằng cả bốn từ giống nhau.' },
    { sec: 'Phụ âm', lvl: 'TH', name: 'Câu 19', pts: 1, text: 'Choose the word whose <u>underlined</u> part is pronounced differently: <u>th</u>ink — <u>th</u>at — <u>th</u>ank — <u>th</u>ree', opts: o4('think', 'that', 'thank', 'three'), ans: 'B', why: '"th" trong <i>that</i> đọc /ð/ (hữu thanh); trong <i>think, thank, three</i> đọc /θ/ (vô thanh).' },
    { sec: 'Trọng âm', lvl: 'NB', name: 'Câu 20', pts: 1, text: 'Choose the word that is stressed on the SECOND syllable.', opts: o4('Monday', 'sunny', 'today', 'birthday'), ans: 'C', why: '<i>Today</i> nhấn âm tiết thứ hai (to-DAY); <i>Monday, sunny, birthday</i> đều nhấn âm tiết thứ nhất.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>My name is Khanh and I am a member of the English Speaking Club. We meet <b>(21)___</b> Friday afternoon in Room 12. The club has fifteen members, <b>(22)___</b> only ten of them come every week. In each meeting we sing songs, play word games and learn to say new words <b>(23)___</b>. Last month we <b>(24)___</b> a short play in English for the whole school. I never miss a meeting because it is <b>(25)___</b> than any other club in my school.<br><br><b>Câu 21.</b> We meet <b>(21)___</b> Friday afternoon in Room 12.', opts: o4('on', 'in', 'at', 'of'), ans: 'A', why: 'Với một buổi cụ thể của một ngày trong tuần ("Friday afternoon") ta dùng <i>on</i>, không dùng "in the afternoon" nữa.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> The club has fifteen members, <b>(22)___</b> only ten of them come every week.', opts: o4('because', 'and', 'so', 'but'), ans: 'D', why: 'Câu lạc bộ có mười lăm thành viên NHƯNG chỉ mười bạn đi đều — hai ý trái chiều nên dùng <i>but</i>. Bẫy ở B: chọn <i>and</i> là bỏ mất chữ "only" mang ý tương phản; bẫy ở C: <i>so</i> biến vế sau thành kết quả, vô lí.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> … we sing songs, play word games and learn to say new words <b>(23)___</b>.', opts: o4('correct', 'correctness', 'correctly', 'more correct'), ans: 'C', why: 'Cần một trạng từ bổ nghĩa cho động từ "say" nên chọn <i>correctly</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> Last month we <b>(24)___</b> a short play in English for the whole school.', opts: o4('perform', 'performed', 'performs', 'performing'), ans: 'B', why: '"Last month" là dấu hiệu của thì quá khứ đơn nên dùng <i>performed</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'VD', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> I never miss a meeting because it is <b>(25)___</b> than any other club in my school.', opts: o4('more interesting', 'interesting', 'the most interesting', 'interestinger'), ans: 'A', why: 'Có "than" nên phải dùng so sánh hơn; <i>interesting</i> là tính từ dài nên thêm <i>more</i>. Bẫy ở C: dạng so sánh nhất "the most interesting" đi với "in my school" chứ không bao giờ đi với "than".' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>Linh is thirteen and she is in Grade 7. Every evening, from 8.00 to 8.30, she listens to an English radio programme, "Say It Right". The programme teaches listeners how to pronounce difficult words. On Mondays and Wednesdays, the teacher explains vowel sounds; on Fridays she talks about word stress. Linh keeps a small notebook and writes down five new words after each programme. Her brother Tuan sometimes listens with her, but he prefers music programmes. Linh says her speaking is much better now, and last term she won the second prize in the school English contest.<br><br><b>Câu 26.</b> How long does the radio programme last?', opts: o4('One hour.', 'Fifteen minutes.', 'Half an hour.', 'Two hours.'), ans: 'C', why: 'Chương trình phát từ 8.00 đến 8.30, tức là 30 phút — <i>half an hour</i>.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> Which statement is NOT true about Linh?', opts: o4('She writes new words in a notebook.', 'She listens to the programme in the evening.', 'She is a student in Grade 7.', 'She won the first prize last term.'), ans: 'D', why: 'Bài viết "she won the second prize", không phải giải nhất. Bẫy ở D là học sinh chỉ nhớ có chữ "prize" mà bỏ qua chữ "second".' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> What does the teacher talk about on Fridays?', opts: o4('Vowel sounds.', 'Word stress.', 'Pop music.', 'New songs.'), ans: 'B', why: 'Bài viết: "on Fridays she talks about word stress"; các nguyên âm được dạy vào thứ Hai và thứ Tư.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> Which idea can be inferred from the passage?', opts: o4('Tuan never listens to the radio.', 'Linh has studied English for seven years.', 'The programme helps Linh speak better.', 'The programme is only for Grade 7 students.'), ans: 'C', why: 'Linh nghe mỗi tối, ghi từ mới và nói rằng "her speaking is much better now" — đó là kết quả của chương trình. Bẫy ở A: Tuấn "sometimes listens with her", tức vẫn có nghe, chỉ là thích chương trình âm nhạc hơn.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 30', pts: 1, text: '<b>Câu 30.</b> What kind of programme does Tuan prefer?', opts: o4('Music programmes.', 'English lessons.', 'Sports news.', 'Film reviews.'), ans: 'A', why: 'Bài viết: "he prefers music programmes".' },
  ],
},
/* ═══════════ ĐỀ 23 — TỪ VỰNG: TRƯỜNG HỌC, GIA ĐÌNH, NHÀ Ở ═══════════ */
{
  id: 10723, title: 'Đề 23 · Từ vựng trường học, gia đình, nhà ở — word form cơ bản', time: 60,
  questions: [
    { sec: 'Word form', lvl: 'NC', name: 'Câu 1', pts: 1, text: 'Mr Ha works as a ___; he ___ Maths to Grade 6 students.', opts: o4('teaching – teaches', 'teacher – teach', 'teach – teacher', 'teacher – teaches'), ans: 'D', why: 'Sau mạo từ "a" cần một DANH TỪ chỉ người (<i>teacher</i>), còn chỗ trống thứ hai là động từ chia theo "he" (<i>teaches</i>). Bẫy ở B: học sinh điền đúng danh từ rồi quên thêm -s cho động từ ở ngôi thứ ba số ít.' },
    { sec: 'Gia đình', lvl: 'NB', name: 'Câu 2', pts: 1, text: 'My father\'s mother is my ___.', opts: o4('grandmother', 'aunt', 'sister', 'cousin'), ans: 'A', why: 'Mẹ của bố chính là bà — <i>grandmother</i>.' },
    { sec: 'Đồ đạc trong nhà', lvl: 'TH', name: 'Câu 3', pts: 1, text: 'We keep our clothes in the ___.', opts: o4('fridge', 'cooker', 'wardrobe', 'sink'), ans: 'C', why: '<i>Wardrobe</i> là tủ quần áo. <i>Fridge</i> là tủ lạnh, <i>cooker</i> là bếp nấu, <i>sink</i> là bồn rửa.' },
    { sec: 'Nhóm từ', lvl: 'NC', name: 'Câu 4', pts: 1, text: 'Three of these words name people in the same family. Which one is the odd one out?', opts: o4('uncle', 'neighbour', 'niece', 'cousin'), ans: 'B', why: '<i>Uncle, niece, cousin</i> đều là người trong họ hàng; <i>neighbour</i> là hàng xóm, không có quan hệ họ hàng. Bẫy là học sinh thấy hàng xóm cũng là người thân quen sống gần nhà nên xếp chung nhóm.' },
    { sec: 'Phòng trong nhà', lvl: 'TH', name: 'Câu 5', pts: 1, text: 'The whole family has meals together in the ___.', opts: o4('bathroom', 'hall', 'bedroom', 'dining room'), ans: 'D', why: '<i>Dining room</i> là phòng ăn — nơi cả nhà dùng bữa.' },
    { sec: 'Đồ dùng học tập', lvl: 'NB', name: 'Câu 6', pts: 1, text: 'We put our books and notebooks in our ___.', opts: o4('ruler', 'rubber', 'school bag', 'board'), ans: 'C', why: '<i>School bag</i> là cặp sách — nơi đựng sách vở.' },
    { sec: 'Word form', lvl: 'TH', name: 'Câu 7', pts: 1, text: 'My brother is a very ___ student; he studies six hours a day.', opts: o4('hard-working', 'hardly', 'work', 'works'), ans: 'A', why: 'Trước danh từ "student" cần một TÍNH TỪ: <i>hard-working</i> (chăm chỉ). <i>Hardly</i> là trạng từ và có nghĩa "hầu như không".' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 8', pts: 1, text: 'In Mai\'s family there are her grandparents, her parents, Mai herself and her two younger brothers. How many people are there in her family?', opts: o4('6', '7', '8', '5'), ans: 'B', why: 'Ông bà (2) + bố mẹ (2) + Mai (1) + hai em trai (2) = <b>7</b> người. Bẫy ở A: học sinh quên đếm chính Mai vì bài dùng chữ "Mai herself".' },
    { sec: 'Gia đình', lvl: 'NB', name: 'Câu 9', pts: 1, text: 'My dad\'s brother is my ___.', opts: o4('nephew', 'grandfather', 'uncle', 'son'), ans: 'C', why: 'Anh (em) trai của bố là chú/bác — <i>uncle</i>.' },
    { sec: 'Nhà ở', lvl: 'NC', name: 'Câu 10', pts: 1, text: 'Our new flat is on the fifth ___ of the building, so we usually go up by ___.', opts: o4('stair – lift', 'floor – ladder', 'ground – lift', 'floor – lift'), ans: 'D', why: 'Tầng của toà nhà là <i>floor</i>, còn thang máy là <i>lift</i>. Bẫy ở A: <i>stair</i> là bậc cầu thang chứ không phải tầng; bẫy ở B: <i>ladder</i> là cái thang gỗ dựng tạm, không dùng trong chung cư.' },
    { sec: 'Cụm từ', lvl: 'NC', name: 'Câu 11', pts: 1, text: 'Which sentence uses the word <i>homework</i> correctly?', opts: o4('I must make my homework before dinner.', 'I must do my homework before dinner.', 'I must do my homeworks before dinner.', 'I must doing my homework before dinner.'), ans: 'B', why: 'Cụm cố định là <i>do homework</i>, và <i>homework</i> là danh từ không đếm được nên không thêm -s. Bẫy ở A: tiếng Việt nói "làm bài tập" khiến học sinh chọn "make"; bẫy ở C: thêm -s vì tưởng nhiều bài tập thì phải số nhiều.' },
    { sec: 'Word form', lvl: 'TH', name: 'Câu 12', pts: 1, text: 'My mother is a ___. She works in the kitchen of a big restaurant.', opts: o4('cook', 'cooker', 'cooking', 'cooked'), ans: 'A', why: '<i>Cook</i> là đầu bếp (người); <i>cooker</i> là cái bếp nấu (đồ vật) — đây là cặp từ học sinh nhầm nhiều nhất.' },
    { sec: 'Phòng trong nhà', lvl: 'NB', name: 'Câu 13', pts: 1, text: 'We wash our hands and face in the ___.', opts: o4('garage', 'attic', 'bathroom', 'garden'), ans: 'C', why: '<i>Bathroom</i> là phòng tắm — nơi rửa mặt, rửa tay.' },
    { sec: 'Từ trái nghĩa', lvl: 'TH', name: 'Câu 14', pts: 1, text: 'Choose the word with the OPPOSITE meaning to <i>noisy</i>.', opts: o4('quiet', 'busy', 'crowded', 'modern'), ans: 'A', why: '<i>Noisy</i> (ồn ào) trái nghĩa với <i>quiet</i> (yên tĩnh).' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 15', pts: 1, text: 'Choose the underlined part that needs correction: My grandmother <u>lives</u> <u>with</u> us and she <u>cooks</u> very <u>good</u>.', opts: o4('lives', 'with', 'cooks', 'good'), ans: 'D', why: 'Bổ nghĩa cho động từ "cooks" phải là trạng từ <i>well</i>, không phải tính từ "good". Bẫy ở C: học sinh nghĩ lỗi nằm ở động từ, nhưng "she cooks" đã chia đúng ngôi thứ ba số ít.' },
    { sec: 'Phòng trong nhà', lvl: 'NB', name: 'Câu 16', pts: 1, text: 'We cook our meals in the ___.', opts: o4('bedroom', 'kitchen', 'hall', 'yard'), ans: 'B', why: '<i>Kitchen</i> là nhà bếp — nơi nấu ăn.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 17', pts: 1, text: 'Nam\'s house has three bedrooms. In each bedroom there are two beds and one desk. How many pieces of furniture (beds and desks) are there in the bedrooms?', opts: o4('6', '8', '9', '12'), ans: 'C', why: 'Mỗi phòng có 2 + 1 = 3 món; ba phòng có 3 × 3 = <b>9</b> món. Bẫy ở A: học sinh chỉ đếm giường (3 × 2 = 6) mà quên bàn học.' },
    { sec: 'Gia đình', lvl: 'TH', name: 'Câu 18', pts: 1, text: 'My grandparents ___ in the countryside with my aunt.', opts: o4('lives', 'is living', 'living', 'live'), ans: 'D', why: '"My grandparents" là chủ ngữ số nhiều nên động từ giữ nguyên thể: <i>live</i>.' },
    { sec: 'Trường học', lvl: 'NB', name: 'Câu 19', pts: 1, text: 'Ms Lan teaches English at our school, so she is a ___.', opts: o4('teacher', 'student', 'driver', 'farmer'), ans: 'A', why: 'Người dạy học ở trường là <i>teacher</i> — giáo viên.' },
    { sec: 'Từ trái nghĩa', lvl: 'NC', name: 'Câu 20', pts: 1, text: 'Choose the word OPPOSITE in meaning to the <u>underlined</u> word: "The furniture in our living room is very <u>modern</u>."', opts: o4('expensive', 'old-fashioned', 'comfortable', 'beautiful'), ans: 'B', why: '<i>Modern</i> (hiện đại) trái nghĩa với <i>old-fashioned</i> (kiểu cũ). Bẫy ở A: học sinh liên tưởng "hiện đại thì đắt" nên chọn <i>expensive</i>, nhưng đắt – rẻ mới là cặp trái nghĩa của "expensive".' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>My family lives in a small house in Thanh Hoa. The house is not big, so we have to keep it <b>(21)___</b>. My sister and I <b>(22)___</b> a bedroom next to my parents\' room. Our living room is small, <b>(23)___</b> we all like it: every evening we watch TV there together. My mother is very good <b>(24)___</b> growing flowers, and there are always fresh flowers on the table. I love my house because it is always warm and full of <b>(25)___</b>.<br><br><b>Câu 21.</b> The house is not big, so we have to keep it <b>(21)___</b>.', opts: o4('tidily', 'tidiness', 'tidier', 'tidy'), ans: 'D', why: 'Cấu trúc <i>keep + tân ngữ + TÍNH TỪ</i> nên phải dùng <i>tidy</i>. Bẫy ở A: thấy phía trước là động từ "keep" nên học sinh vội thêm -ly thành trạng từ.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> My sister and I <b>(22)___</b> a bedroom next to my parents\' room.', opts: o4('shares', 'sharing', 'share', 'shared'), ans: 'C', why: 'Chủ ngữ "My sister and I" là số nhiều nên động từ ở hiện tại đơn giữ nguyên thể: <i>share</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> Our living room is small, <b>(23)___</b> we all like it: every evening we watch TV there together.', opts: o4('but', 'so', 'because', 'or'), ans: 'A', why: 'Phòng khách nhỏ nhưng cả nhà vẫn thích — hai ý trái chiều nên nối bằng <i>but</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> My mother is very good <b>(24)___</b> growing flowers.', opts: o4('in', 'at', 'for', 'with'), ans: 'B', why: 'Cụm cố định là <i>be good at + V-ing</i> (giỏi làm việc gì). Bẫy ở A: tiếng Việt nói "giỏi TRONG việc trồng hoa" khiến học sinh chọn <i>in</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> I love my house because it is always warm and full of <b>(25)___</b>.', opts: o4('love', 'lovely', 'loving', 'loved'), ans: 'A', why: 'Sau cụm <i>full of</i> phải là một danh từ, nên chọn <i>love</i>; <i>lovely</i> là tính từ.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>The Tran family lives in a four-storey house on Le Loi Street. On the ground floor there is a small shop. Mrs Tran sells school things there: pens, rulers, notebooks and school bags. The first floor has the living room and the kitchen. On the second floor there are two bedrooms, one for the parents and one for the grandmother. Minh and his younger sister sleep on the third floor. There is also a study with a large bookshelf on this floor. Minh likes the study best because it is quiet and he can see the river from its window. The family moved to this house ten years ago.<br><br><b>Câu 26.</b> What does Mrs Tran sell in her shop?', opts: o4('Flowers.', 'Food and drinks.', 'Books and magazines.', 'School things.'), ans: 'D', why: 'Bài đọc: "Mrs Tran sells school things there: pens, rulers, notebooks and school bags".' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> Where do Minh and his sister sleep?', opts: o4('On the first floor.', 'On the third floor.', 'On the second floor.', 'On the ground floor.'), ans: 'B', why: 'Bài đọc: "Minh and his younger sister sleep on the third floor"; tầng hai là phòng của bố mẹ và bà.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> Why does Minh like the study best?', opts: o4('Because his sister never goes there.', 'Because there is a television in it.', 'Because it is quiet and has a nice view.', 'Because it is next to his grandmother\'s room.'), ans: 'C', why: 'Bài đọc: "it is quiet and he can see the river from its window". Bẫy ở D: phòng bà ở tầng hai còn phòng đọc ở tầng ba nên không thể cạnh nhau; bẫy ở B: ti vi không hề được nhắc tới trong bài.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> On how many floors of the house do the family members sleep?', opts: o4('One.', 'Three.', 'Four.', 'Two.'), ans: 'D', why: 'Tầng hai có hai phòng ngủ và tầng ba là chỗ ngủ của Minh và em gái → <b>2</b> tầng. Bẫy ở A: học sinh chỉ đếm tầng có chữ "bedrooms" mà bỏ qua câu "Minh and his younger sister sleep on the third floor".' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 30', pts: 1, text: '<b>Câu 30.</b> Where is the kitchen?', opts: o4('On the first floor.', 'On the ground floor.', 'On the second floor.', 'On the third floor.'), ans: 'A', why: 'Bài đọc: "The first floor has the living room and the kitchen."' },
  ],
},
/* ═══════════ ĐỀ 24 — TỪ VỰNG: THIÊN NHIÊN, LỄ HỘI, THÀNH PHỐ ═══════════ */
{
  id: 10724, title: 'Đề 24 · Từ vựng thiên nhiên, lễ hội, thành phố — từ trong ngữ cảnh', time: 60,
  questions: [
    { sec: 'Thiên nhiên', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'The Mekong is the longest ___ in Viet Nam.', opts: o4('river', 'lake', 'mountain', 'island'), ans: 'A', why: 'Sông Mê Kông là một dòng sông — <i>river</i>.' },
    { sec: 'Lễ hội', lvl: 'TH', name: 'Câu 2', pts: 1, text: 'People wear <i>ao dai</i>, visit pagodas and give lucky money during ___.', opts: o4('Christmas', 'Halloween', 'Tet', 'Easter'), ans: 'C', why: 'Mặc áo dài, đi lễ chùa và mừng tuổi là phong tục của <i>Tet</i> — Tết Nguyên đán.' },
    { sec: 'Nhóm từ', lvl: 'NC', name: 'Câu 3', pts: 1, text: 'Three of these words name things made by nature. Which one is different?', opts: o4('desert', 'lantern', 'valley', 'cave'), ans: 'B', why: '<i>Desert, valley, cave</i> đều là cảnh quan thiên nhiên; <i>lantern</i> (đèn lồng) là đồ vật do con người làm. Bẫy là học sinh thấy <i>cave</i> (hang động) lạ tai nên chọn nhầm, trong khi hang động vẫn là dạng địa hình tự nhiên.' },
    { sec: 'Thành phố', lvl: 'TH', name: 'Câu 4', pts: 1, text: 'In a big city you can see a lot of tall ___.', opts: o4('mountains', 'waterfalls', 'villages', 'buildings'), ans: 'D', why: 'Đặc trưng của thành phố lớn là các toà nhà cao tầng — <i>tall buildings</i>.' },
    { sec: 'Thiên nhiên', lvl: 'NB', name: 'Câu 5', pts: 1, text: 'Which word means "a very large area of salt water"?', opts: o4('ocean', 'river', 'lake', 'stream'), ans: 'A', why: '<i>Ocean</i> là đại dương — vùng nước mặn rộng lớn; sông, hồ và suối đều là nước ngọt.' },
    { sec: 'Thành phố', lvl: 'NC', name: 'Câu 6', pts: 1, text: 'Choose the best word: "Hoi An is a ___ town; people there keep many old houses from the 18th century."', opts: o4('modern', 'historic', 'noisy', 'crowded'), ans: 'B', why: 'Vế sau nói về những ngôi nhà cổ từ thế kỉ 18 nên tính từ hợp lí là <i>historic</i> (cổ kính, có bề dày lịch sử). Bẫy ở A: <i>modern</i> nghĩa ngược hẳn; bẫy ở D: <i>crowded</i> đúng với Hội An ngày nay nhưng không liên quan tới vế "nhà cổ".' },
    { sec: 'Từ đồng nghĩa', lvl: 'NC', name: 'Câu 7', pts: 1, text: 'Choose the word or phrase CLOSEST in meaning to the <u>underlined</u> word: "The streets of Ha Noi are very <u>crowded</u> at rush hour."', opts: o4('quiet', 'narrow', 'clean', 'full of people'), ans: 'D', why: '<i>Crowded</i> nghĩa là đông đúc — <i>full of people</i>. Bẫy ở B: phố cổ Hà Nội đúng là hẹp, nhưng <i>narrow</i> nói về độ rộng của đường chứ không nói về số người.' },
    { sec: 'Lễ hội', lvl: 'NB', name: 'Câu 8', pts: 1, text: 'At the Mid-Autumn Festival, children carry ___ and eat moon cakes.', opts: o4('fireworks', 'balloons', 'lanterns', 'kites'), ans: 'C', why: 'Trung thu là dịp trẻ em rước đèn lồng — <i>lanterns</i>.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 9', pts: 1, text: 'A city tour bus leaves the Old Quarter every 30 minutes, from 8.00 to 12.00. How many buses leave during this time?', opts: o4('8', '9', '10', '7'), ans: 'B', why: 'Các chuyến khởi hành lúc 8.00, 8.30, 9.00 … 12.00. Trong 4 giờ có 8 khoảng 30 phút, nên số chuyến là 8 + 1 = <b>9</b>. Bẫy ở A: học sinh chỉ lấy 4 giờ chia 30 phút mà quên cộng chuyến đầu tiên.' },
    { sec: 'Thiên nhiên', lvl: 'TH', name: 'Câu 10', pts: 1, text: 'Son Doong is the largest ___ in the world; visitors walk inside it with torches.', opts: o4('cave', 'lake', 'desert', 'beach'), ans: 'A', why: 'Sơn Đoòng là hang động lớn nhất thế giới — <i>cave</i>; chỉ hang động mới "đi vào bên trong" với đèn pin.' },
    { sec: 'So sánh', lvl: 'NC', name: 'Câu 11', pts: 1, text: 'Da Lat is ___ than Ha Noi in summer, so many people go there for their holiday.', opts: o4('cool', 'more cool', 'the coolest', 'cooler'), ans: 'D', why: 'Có "than" nên phải dùng so sánh hơn; <i>cool</i> là tính từ ngắn nên thêm -er. Bẫy ở B: học sinh áp dụng nhầm công thức "more + tính từ" của tính từ dài; bẫy ở C: dạng so sánh nhất không đi với "than".' },
    { sec: 'Lễ hội', lvl: 'TH', name: 'Câu 12', pts: 1, text: 'At many spring festivals in Viet Nam, young men ___ dragon dances in the village yard.', opts: o4('do', 'make', 'perform', 'play'), ans: 'C', why: 'Với các tiết mục biểu diễn ta dùng động từ <i>perform</i>: <i>perform a dragon dance</i>.' },
    { sec: 'Thiên nhiên', lvl: 'NB', name: 'Câu 13', pts: 1, text: 'A very dry place with a lot of sand and little water is a ___.', opts: o4('forest', 'desert', 'lake', 'island'), ans: 'B', why: '<i>Desert</i> là sa mạc — vùng đất khô, nhiều cát và rất ít nước.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 14', pts: 1, text: 'At a flower festival there are 5 rows of flower pots. Each row has 12 pots, but 4 pots in the last row are empty. How many pots have flowers in them?', opts: o4('60', '48', '52', '56'), ans: 'D', why: 'Tổng số chậu: 5 × 12 = 60; trừ 4 chậu trống → <b>56</b> chậu có hoa. Bẫy ở A: quên trừ bốn chậu trống; bẫy ở B: bỏ luôn cả hàng cuối (60 − 12 = 48).' },
    { sec: 'Lễ hội', lvl: 'TH', name: 'Câu 15', pts: 1, text: 'My family always ___ Tet with our grandparents in the countryside.', opts: o4('celebrates', 'congratulates', 'remembers', 'visits'), ans: 'A', why: 'Đón/ăn mừng một ngày lễ là <i>celebrate</i>. <i>Congratulate</i> là chúc mừng một NGƯỜI về thành tích của họ.' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 16', pts: 1, text: 'Choose the underlined part that needs correction: Ha Noi <u>has</u> <u>many</u> <u>interesting place</u> <u>to visit</u>.', opts: o4('has', 'many', 'interesting place', 'to visit'), ans: 'C', why: 'Sau <i>many</i> phải là danh từ đếm được SỐ NHIỀU: <i>interesting places</i>. Bẫy ở B: học sinh nghĩ phải đổi "many" thành "much", nhưng "place" là danh từ đếm được nên "many" hoàn toàn đúng.' },
    { sec: 'Thiên nhiên', lvl: 'NB', name: 'Câu 17', pts: 1, text: 'A ___ is water that falls down from a high place in the mountains.', opts: o4('waterfall', 'valley', 'bay', 'stream'), ans: 'A', why: '<i>Waterfall</i> là thác nước — dòng nước đổ từ trên cao xuống.' },
    { sec: 'Thành phố', lvl: 'TH', name: 'Câu 18', pts: 1, text: 'Which of these names is NOT a city?', opts: o4('Hue', 'Fansipan', 'Can Tho', 'Hai Phong'), ans: 'B', why: '<i>Fansipan</i> là ngọn núi cao nhất Việt Nam; Huế, Cần Thơ, Hải Phòng đều là thành phố.' },
    { sec: 'Dùng từ', lvl: 'NC', name: 'Câu 19', pts: 1, text: 'Which sentence uses the word <i>island</i> correctly?', opts: o4('Phu Quoc is an island in the mountains.', 'There are many islands on the desert.', 'An island is a high place with snow.', 'Phu Quoc is the largest island in Viet Nam.'), ans: 'D', why: '<i>Island</i> là vùng đất có nước bao quanh, nên chỉ câu D hợp lí. Bẫy ở A: học sinh biết Phú Quốc là đảo nên chọn ngay câu có tên Phú Quốc mà không đọc hết phần "in the mountains" hoàn toàn vô lí.' },
    { sec: 'Lễ hội', lvl: 'NC', name: 'Câu 20', pts: 1, text: 'Read: "Every year, thousands of people come to Phu Tho on the tenth day of the third lunar month to remember the Hung Kings." Which festival is it?', opts: o4('Mid-Autumn Festival', 'Tet Holiday', 'Hung Kings Temple Festival', 'Lantern Festival'), ans: 'C', why: 'Giỗ Tổ mùng 10 tháng 3 âm lịch ở Phú Thọ là <i>Hung Kings Temple Festival</i>. Bẫy ở B: học sinh thấy cụm "lunar month" liền nghĩ ngay tới Tết, nhưng Tết rơi vào tháng Giêng âm lịch.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>Da Nang is a modern city in the centre of Viet Nam. It <b>(21)___</b> between the mountains and the sea, so the air there is fresh. Every June the city holds an international <b>(22)___</b> festival, and thousands of visitors come to watch the beautiful lights over the Han River. Da Nang is also famous <b>(23)___</b> its long beaches and clean streets. If you like nature, you <b>(24)___</b> visit Ba Na Hills, about 25 kilometres from the city centre. My family went there last summer and we <b>(25)___</b> a wonderful time.<br><br><b>Câu 21.</b> It <b>(21)___</b> between the mountains and the sea.', opts: o4('lie', 'lies', 'is lying', 'lying'), ans: 'B', why: 'Chủ ngữ "It" là ngôi thứ ba số ít, câu nói về một sự thật lâu dài nên dùng hiện tại đơn: <i>lies</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> Every June the city holds an international <b>(22)___</b> festival, and thousands of visitors come to watch the beautiful lights over the Han River.', opts: o4('fireworks', 'flower', 'music', 'food'), ans: 'A', why: 'Vế sau nói tới "the beautiful lights over the Han River" — đó là lễ hội pháo hoa quốc tế Đà Nẵng: <i>fireworks festival</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> Da Nang is also famous <b>(23)___</b> its long beaches and clean streets.', opts: o4('of', 'with', 'for', 'in'), ans: 'C', why: 'Cụm cố định là <i>be famous for</i> (nổi tiếng về/vì cái gì).' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> If you like nature, you <b>(24)___</b> visit Ba Na Hills, about 25 kilometres from the city centre.', opts: o4('should to', 'ought', 'must to', 'should'), ans: 'D', why: 'Sau <i>should</i> là động từ nguyên thể KHÔNG có "to": <i>should visit</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> My family went there last summer and we <b>(25)___</b> a wonderful time.', opts: o4('had', 'made', 'did', 'took'), ans: 'A', why: 'Cụm cố định là <i>have a wonderful time</i>, ở quá khứ thành <i>had</i>. Bẫy ở D: học sinh dịch "trải qua một kì nghỉ" rồi chọn <i>took</i>; bẫy ở B: tiếng Việt "làm nên kỉ niệm đẹp" dẫn tới <i>made</i>.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>The Flower Festival in Da Lat takes place every two years in December. During the festival, the streets around Xuan Huong Lake are full of flowers of all colours. Visitors can join many activities: a flower parade in the morning, a tea festival in the afternoon and music shows in the evening. Last year, more than 100000 people came to the town for the festival. Many families stayed for three days and three nights. The hotels were full, so some visitors slept in homestays in nearby villages. Local farmers were happy because they sold a lot of flowers and vegetables during those days.<br><br><b>Câu 26.</b> How often does the Flower Festival take place?', opts: o4('Every year.', 'Every month.', 'Every two years.', 'Twice a year.'), ans: 'C', why: 'Bài đọc: "takes place every two years in December" — hai năm một lần.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> A family stayed for the whole festival and paid 500000 dong for each night at a homestay. How much did they pay?', opts: o4('1000000 dong', '1500000 dong', '2000000 dong', '500000 dong'), ans: 'B', why: 'Gia đình ở ba đêm: 3 × 500000 = <b>1500000 đồng</b>. Bẫy ở A: học sinh đếm "three days" thành hai đêm nên chỉ nhân với 2.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> What can visitors do in the evening?', opts: o4('Join a flower parade.', 'Visit a tea festival.', 'Buy vegetables.', 'Watch music shows.'), ans: 'D', why: 'Bài đọc: "music shows in the evening"; diễu hành hoa là buổi sáng, lễ hội trà là buổi chiều.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> Why did some visitors sleep in homestays?', opts: o4('Because all the hotels were full.', 'Because homestays were cheaper.', 'Because they liked villages better.', 'Because the hotels were far away.'), ans: 'A', why: 'Bài đọc: "The hotels were full, so some visitors slept in homestays". Bẫy ở B: giá rẻ là suy đoán từ hiểu biết bên ngoài, bài hoàn toàn không nói tới giá phòng.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 30', pts: 1, text: '<b>Câu 30.</b> Where is the Flower Festival held?', opts: o4('In Ha Noi.', 'In Da Lat.', 'In Da Nang.', 'In Hue.'), ans: 'B', why: 'Bài đọc mở đầu bằng "The Flower Festival in Da Lat".' },
  ],
},
/* ═══════════ ĐỀ 25 — COMMUNICATION: CHÀO HỎI, GIỚI THIỆU, LỜI MỜI ═══════════ */
{
  id: 10725, title: 'Đề 25 · Communication — chào hỏi, giới thiệu, lời mời', time: 60,
  questions: [
    { sec: 'Chào hỏi', lvl: 'NB', name: 'Câu 1', pts: 1, text: '— "Good morning, Miss Hoa." — "___"', opts: o4('Good night.', 'Goodbye.', 'Good morning.', 'See you later.'), ans: 'C', why: 'Lời chào buổi sáng được đáp lại bằng chính lời chào đó: <i>Good morning</i>.' },
    { sec: 'Giới thiệu', lvl: 'NC', name: 'Câu 2', pts: 1, text: '— "Hi, I\'m Long. I\'m new in this class." — "___"', opts: o4('Nice to meet you, too.', 'Hi, Long. I\'m Mai. Welcome!', 'Yes, please. Thank you.', 'I\'m fine, thank you.'), ans: 'B', why: 'Bạn mới tự giới thiệu tên nên ta cũng giới thiệu tên mình và chào đón bạn. Bẫy ở A: chỉ nói "Nice to meet you, <b>too</b>" khi người kia đã nói "Nice to meet you" trước; bẫy ở D là đáp cho câu hỏi "How are you?".' },
    { sec: 'Chào hỏi', lvl: 'TH', name: 'Câu 3', pts: 1, text: '— "How do you do?" — "___"', opts: o4('I\'m fine, thanks.', 'Very well, thank you.', 'I\'m a new student.', 'How do you do?'), ans: 'D', why: '<i>How do you do?</i> là câu chào trang trọng khi gặp lần đầu; người nghe đáp lại bằng đúng câu ấy chứ không trả lời về sức khoẻ.' },
    { sec: 'Lời mời', lvl: 'NC', name: 'Câu 4', pts: 1, text: '— "Would you like to come to my birthday party on Saturday?" — "___"', opts: o4('I\'d love to, but I\'m busy on Saturday.', 'Yes, I would like some, please.', 'No, I don\'t like parties at all.', 'Yes, I do. Thank you very much.'), ans: 'A', why: 'Từ chối lịch sự gồm hai phần: bày tỏ sự thích thú rồi nêu lí do. Bẫy ở B: "I would like some" dùng khi được mời ĐỒ ĂN, THỨC UỐNG; bẫy ở D: lời mời "Would you like…?" không bao giờ đáp bằng "Yes, I do".' },
    { sec: 'Cảm ơn', lvl: 'TH', name: 'Câu 5', pts: 1, text: '— "Thanks a lot for your help." — "___"', opts: o4('Yes, please.', 'Never mind.', 'You\'re welcome.', 'The same to you.'), ans: 'C', why: 'Đáp lại lời cảm ơn là <i>You\'re welcome</i>. "Never mind" dùng khi an ủi ai đó, "The same to you" dùng để đáp lại lời chúc.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 6', pts: 1, text: 'Mai invites Nam to the cinema at 7.00 p.m. on Friday. Nam has an English class from 6.00 to 7.30 p.m. every Friday. What should Nam say?', opts: o4('"Yes, I\'d love to. See you at seven."', '"I don\'t like films, sorry."', '"Sure, I\'m free all Friday evening."', '"Sorry, I can\'t. I have an English class then."'), ans: 'D', why: 'Buổi chiếu lúc 19.00 trùng với lớp tiếng Anh 18.00–19.30 nên Nam phải từ chối và nêu lí do. Bẫy ở A: học sinh chỉ nhìn lời mời mà không đối chiếu lịch học; bẫy ở B: từ chối bằng lí do sai sự thật và thiếu lịch sự.' },
    { sec: 'Giới thiệu', lvl: 'NB', name: 'Câu 7', pts: 1, text: '— "Lan, this is my friend, Trang." — "___"', opts: o4('How are you today?', 'Nice to meet you.', 'See you again next week.', 'Good luck with your test.'), ans: 'B', why: 'Khi được giới thiệu với người lạ, ta nói <i>Nice to meet you</i>; ba câu còn lại dùng để hỏi thăm, chào tạm biệt hoặc chúc may mắn.' },
    { sec: 'Chào hỏi', lvl: 'TH', name: 'Câu 8', pts: 1, text: '— "How are you today, Minh?" — "___"', opts: o4('I\'m very well, thanks.', 'I\'m twelve years old.', 'I\'m from Hue city.', 'I\'m a new student in Class 6A.'), ans: 'A', why: '<i>How are you?</i> hỏi về sức khoẻ, tâm trạng nên trả lời "I\'m very well, thanks"; các phương án kia trả lời cho câu hỏi về tuổi, quê quán và nghề nghiệp.' },
    { sec: 'Lời mời', lvl: 'NC', name: 'Câu 9', pts: 1, text: 'Which is the most POLITE way to invite your teacher to your class party?', opts: o4('Come to our class party!', 'You must come to our class party.', 'Do you want to come to our party?', 'Would you like to come to our class party?'), ans: 'D', why: 'Với người lớn tuổi hay thầy cô, lời mời lịch sự nhất là <i>Would you like to…?</i>. Bẫy ở B: <i>must</i> mang nghĩa bắt buộc, nghe như ra lệnh; bẫy ở A là câu mệnh lệnh, chỉ dùng với bạn bè thân.' },
    { sec: 'Tạm biệt', lvl: 'NB', name: 'Câu 10', pts: 1, text: '— "See you tomorrow!" — "___"', opts: o4('Nice to meet you.', 'See you.', 'You\'re welcome.', 'Not at all.'), ans: 'B', why: 'Lời tạm biệt "See you tomorrow" được đáp lại bằng <i>See you</i>.' },
    { sec: 'Gợi ý', lvl: 'TH', name: 'Câu 11', pts: 1, text: '— "Let\'s go to the library after school." — "___"', opts: o4('Yes, I am.', 'Here you are.', 'That\'s a good idea.', 'Yes, please.'), ans: 'C', why: 'Đáp lại lời rủ rê "Let\'s…" bằng cách đồng tình: <i>That\'s a good idea</i>.' },
    { sec: 'Lời mời', lvl: 'NC', name: 'Câu 12', pts: 1, text: 'Choose the response that shows the speaker ACCEPTS the invitation.', opts: o4('Sounds great! What time shall we meet?', 'I\'m afraid I can\'t make it.', 'Thanks, but maybe another time.', 'Sorry, I\'m busy this weekend.'), ans: 'A', why: 'Chỉ câu A vừa khen ý tưởng vừa hỏi giờ hẹn — dấu hiệu rõ ràng của việc nhận lời. Bẫy ở C: có chữ "Thanks" nên học sinh tưởng là đồng ý, nhưng "maybe another time" chính là lời từ chối khéo.' },
    { sec: 'Gọi điện', lvl: 'NC', name: 'Câu 13', pts: 1, text: '— "___" — "Hello, this is Nam speaking."', opts: o4('Who are you?', 'What is your full name, please?', 'Are you Nam?', 'May I speak to Nam, please?'), ans: 'D', why: 'Câu trả lời "this is Nam speaking" là cách nói chuẩn khi nghe điện thoại, nên câu hỏi trước đó phải là lời xin gặp lịch sự. Bẫy ở A: "Who are you?" dịch sát tiếng Việt nhưng trong tiếng Anh nghe rất thô lỗ; bẫy ở B: hỏi tên không hợp vì người gọi đã biết mình muốn gặp ai.' },
    { sec: 'Lời chúc', lvl: 'NB', name: 'Câu 14', pts: 1, text: '— "Happy New Year!" — "___"', opts: o4('Thank you very much.', 'Yes, of course.', 'The same to you!', 'You\'re welcome.'), ans: 'C', why: 'Đáp lại một lời chúc bằng cách chúc lại: <i>The same to you!</i>.' },
    { sec: 'Xin lỗi', lvl: 'TH', name: 'Câu 15', pts: 1, text: '— "I\'m sorry I\'m late." — "___"', opts: o4('Yes, you are.', 'That\'s all right.', 'Thank you.', 'Not at all, please.'), ans: 'B', why: 'Đáp lại lời xin lỗi bằng <i>That\'s all right</i> (không sao đâu).' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 16', pts: 1, text: 'Lan wants to introduce her cousin Hoa to her classmate Minh. Which sentence should Lan say FIRST?', opts: o4('"Minh, this is my cousin, Hoa."', '"Hoa, how old are you?"', '"Minh, do you know Hoa?"', '"Nice to meet you, Hoa."'), ans: 'A', why: 'Người giới thiệu mở đầu bằng mẫu <i>This is + tên người được giới thiệu</i>. Bẫy ở D: "Nice to meet you" là câu của hai người ĐƯỢC giới thiệu nói với nhau, không phải của người đứng ra giới thiệu.' },
    { sec: 'Mời dùng đồ', lvl: 'TH', name: 'Câu 17', pts: 1, text: '— "Would you like some orange juice?" — "___"', opts: o4('Yes, I would.', 'No, I wouldn\'t.', 'Yes, please.', 'Yes, I\'d love to.'), ans: 'C', why: 'Nhận lời mời đồ ăn, thức uống ta nói <i>Yes, please</i>; "Yes, I\'d love to" chỉ dùng khi được mời LÀM một việc gì đó.' },
    { sec: 'Hội thoại', lvl: 'NC', name: 'Câu 18', pts: 1, text: 'In which pair do the two speakers NOT talk naturally?', opts: o4('— "How do you go to school?" — "By bike."', '— "Nice to meet you." — "Yes, I am."', '— "What\'s your name?" — "My name\'s Lan."', '— "Where are you from?" — "I\'m from Hue."'), ans: 'B', why: '"Nice to meet you" phải được đáp bằng "Nice to meet you, too", không phải "Yes, I am". Bẫy là học sinh thấy câu ngắn gọn "Yes, I am" rất quen nên cho là hợp lí, trong khi câu trên không hề là câu hỏi Yes/No.' },
    { sec: 'Tạm biệt', lvl: 'NB', name: 'Câu 19', pts: 1, text: '— "Goodbye! Have a nice weekend." — "___"', opts: o4('Thanks. You too.', 'Not at all. Don\'t mention it.', 'Never mind.', 'Yes, I do.'), ans: 'A', why: 'Được chúc cuối tuần vui vẻ, ta cảm ơn và chúc lại: <i>Thanks. You too.</i> Phương án B chỉ dùng để đáp lại lời cảm ơn.' },
    { sec: 'Xin phép', lvl: 'TH', name: 'Câu 20', pts: 1, text: '— "May I use your pen, please?" — "___"', opts: o4('Yes, I can.', 'No, I\'m not.', 'Yes, please give it to me.', 'Sure. Here you are.'), ans: 'D', why: 'Khi đồng ý cho mượn đồ, ta nói <i>Sure. Here you are.</i> (Đây, bạn cầm lấy). "Yes, please" là câu của người XIN, không phải người cho.' },
    { sec: 'Hoàn thành hội thoại', lvl: 'NB', name: 'Câu 21', pts: 1, text: '<i>Complete the dialogue (Câu 21–25).</i><br>Mark: Good afternoon. <b>(21)___</b><br>Hoa: Good afternoon. I\'m Hoa. Nice to meet you.<br>Mark: Nice to meet you, too. <b>(22)___</b><br>Hoa: I\'m from Hue, but I live in Da Nang now.<br>Mark: <b>(23)___</b><br>Hoa: Yes, I am. I\'m in Class 6B.<br>Mark: Great! <b>(24)___</b> to join our football club this afternoon?<br>Hoa: <b>(25)___</b> I have a music lesson at four.<br><br><b>Câu 21.</b> Good afternoon. <b>(21)___</b>', opts: o4('How old are you?', 'What do you do?', 'My name is Mark.', 'Where do you live?'), ans: 'C', why: 'Hoa đáp lại bằng "I\'m Hoa", tức là Mark vừa tự giới thiệu tên mình.' },
    { sec: 'Hoàn thành hội thoại', lvl: 'NC', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> Nice to meet you, too. <b>(22)___</b> — "I\'m from Hue, but I live in Da Nang now."', opts: o4('Where are you from?', 'Where do you live?', 'What is your address?', 'How do you go to school?'), ans: 'A', why: 'Hoa bắt đầu bằng "I\'m from Hue" nên câu hỏi phải là <i>Where are you from?</i>. Bẫy ở B: nếu hỏi "Where do you live?" thì câu trả lời sẽ mở đầu bằng "I live in Da Nang", còn vế "I\'m from Hue" trở thành thừa.' },
    { sec: 'Hoàn thành hội thoại', lvl: 'NC', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> <b>(23)___</b> — "Yes, I am. I\'m in Class 6B."', opts: o4('Do you study here?', 'Are you a new student here?', 'Can you speak English?', 'Is this your school?'), ans: 'B', why: 'Câu trả lời "Yes, I am" bắt buộc câu hỏi phải bắt đầu bằng <i>Are you…?</i>. Bẫy ở A: hỏi "Do you…?" thì phải đáp "Yes, I do"; bẫy ở D: hỏi "Is this…?" thì đáp "Yes, it is".' },
    { sec: 'Hoàn thành hội thoại', lvl: 'TH', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> Great! <b>(24)___</b> to join our football club this afternoon?', opts: o4('Do you like', 'Are you like', 'Will you like', 'Would you like'), ans: 'D', why: 'Mẫu câu mời chuẩn là <i>Would you like to + động từ nguyên thể?</i>.' },
    { sec: 'Hoàn thành hội thoại', lvl: 'NB', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> <b>(25)___</b> I have a music lesson at four.', opts: o4('Yes, I would love to come.', 'That sounds great.', 'I\'m sorry, I can\'t.', 'Of course, thanks.'), ans: 'C', why: 'Vế sau nêu lí do bận học nhạc nên câu trước phải là lời từ chối: <i>I\'m sorry, I can\'t.</i>' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>Last Monday a new student came to Class 6A. Her name is Yuki and she is from Osaka, Japan. Her father works for a Japanese company in Hai Phong, so the family moved to Viet Nam in July. On her first day, the teacher asked Yuki to introduce herself. She said, "Hello, everyone. My name is Yuki. I am twelve years old. I love drawing and Vietnamese food." All the students clapped their hands. At break time, Lan came to her and said, "Would you like to have lunch with us?" Yuki smiled and said yes. Now Yuki has four new friends and they teach her Vietnamese every day.<br><br><b>Câu 26.</b> Why did Yuki\'s family move to Viet Nam?', opts: o4('Because Yuki wanted to learn Vietnamese.', 'Because her father works in Hai Phong.', 'Because they like Vietnamese food.', 'Because her mother is Vietnamese.'), ans: 'B', why: 'Bài đọc: "Her father works for a Japanese company in Hai Phong, so the family moved to Viet Nam."' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> What does Yuki love doing?', opts: o4('She loves drawing.', 'She loves singing.', 'She loves football.', 'She loves reading.'), ans: 'A', why: 'Yuki tự giới thiệu: "I love drawing and Vietnamese food."' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> What did Lan do at break time?', opts: o4('She taught Yuki some Vietnamese words.', 'She introduced Yuki to the teacher.', 'She invited Yuki to have lunch with them.', 'She asked Yuki about her family.'), ans: 'C', why: 'Bài đọc: "At break time, Lan came to her and said, \'Would you like to have lunch with us?\'". Bẫy ở A: việc dạy tiếng Việt được nhắc ở câu cuối nhưng là chuyện các bạn làm "now… every day", không phải điều Lan làm giờ ra chơi hôm ấy.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> Where is Yuki from?', opts: o4('Ha Noi.', 'Hai Phong.', 'Tokyo.', 'Osaka.'), ans: 'D', why: 'Bài đọc: "she is from Osaka, Japan"; Hải Phòng chỉ là nơi bố của Yuki làm việc.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 30', pts: 1, text: '<b>Câu 30.</b> Yuki\'s family arrived in Viet Nam in July and the new school year began in September. How long did Yuki stay in Viet Nam before the school year began?', opts: o4('One month.', 'Two months.', 'Three months.', 'Four months.'), ans: 'B', why: 'Từ tháng Bảy đến tháng Chín là <b>2</b> tháng. Bẫy ở C: học sinh đếm cả tháng Bảy, tháng Tám và tháng Chín thành ba tháng thay vì đếm khoảng cách giữa hai mốc.' },
  ],
},
/* ═══════════ ĐỀ 26 — COMMUNICATION: HỎI ĐƯỜNG, MUA SẮM, GỢI Ý ═══════════ */
{
  id: 10726, title: 'Đề 26 · Communication — hỏi đường, mua sắm, đưa ra gợi ý', time: 60,
  questions: [
    { sec: 'Hỏi đường', lvl: 'NC', name: 'Câu 1', pts: 1, text: '— "Excuse me, how can I get to the post office?" — "___"', opts: o4('It is very far from here.', 'Yes, there is one near here.', 'I am going to the post office, too.', 'Go straight ahead and turn left at the traffic lights.'), ans: 'D', why: 'Câu hỏi "How can I get to…?" cần một lời CHỈ ĐƯỜNG cụ thể. Bẫy ở A: chỉ nói về khoảng cách nên người hỏi vẫn không biết đi lối nào; bẫy ở B là câu trả lời cho "Is there a post office near here?".' },
    { sec: 'Mua sắm', lvl: 'TH', name: 'Câu 2', pts: 1, text: '— "How much is this T-shirt?" — "___"', opts: o4('It\'s very nice.', 'Yes, I like it.', 'It\'s 150000 dong.', 'I\'ll take two.'), ans: 'C', why: '<i>How much…?</i> hỏi giá nên phải trả lời bằng số tiền.' },
    { sec: 'Mua sắm', lvl: 'NB', name: 'Câu 3', pts: 1, text: '— "Can I help you?" — "___"', opts: o4('Yes, I\'d like a pair of shoes.', 'No, you can\'t.', 'Yes, you can.', 'I\'m helping you.'), ans: 'A', why: '"Can I help you?" là câu người bán hàng mời chào; khách đáp lại bằng cách nói mình muốn mua gì.' },
    { sec: 'Cửa hàng', lvl: 'TH', name: 'Câu 4', pts: 1, text: 'The supermarket ___ at 9 a.m. and ___ at 9 p.m. every day.', opts: o4('open – close', 'opens – closes', 'is open – is close', 'opening – closing'), ans: 'B', why: 'Chủ ngữ "The supermarket" là ngôi thứ ba số ít nên cả hai động từ đều thêm -s: <i>opens – closes</i>.' },
    { sec: 'Gợi ý', lvl: 'NC', name: 'Câu 5', pts: 1, text: 'You want to suggest going to the bookshop with your friend. Which sentence is correct?', opts: o4('Let\'s to go to the bookshop.', 'Why we don\'t go to the bookshop?', 'Why don\'t we go to the bookshop?', 'Shall we going to the bookshop?'), ans: 'C', why: 'Mẫu gợi ý đúng là <i>Why don\'t we + động từ nguyên thể?</i>. Bẫy ở B: học sinh giữ nguyên trật tự "we don\'t" như câu kể; bẫy ở A: sau "Let\'s" là động từ nguyên thể không "to".' },
    { sec: 'Địa điểm', lvl: 'NB', name: 'Câu 6', pts: 1, text: 'You can buy fresh bread and cakes at a ___.', opts: o4('bakery', 'chemist\'s', 'bookshop', 'post office'), ans: 'A', why: '<i>Bakery</i> là tiệm bánh; <i>chemist\'s</i> bán thuốc, <i>bookshop</i> bán sách.' },
    { sec: 'Hỏi đường', lvl: 'TH', name: 'Câu 7', pts: 1, text: '— "Is there a supermarket near here?" — "___"', opts: o4('Yes, they are near here.', 'No, it isn\'t very far.', 'Yes, it is here.', 'Yes, there is one opposite the bank.'), ans: 'D', why: 'Câu hỏi bắt đầu bằng "Is there…?" nên phải đáp bằng "Yes, there is…" và nên chỉ thêm vị trí. Ba phương án còn lại dùng sai chủ ngữ "it/they" thay cho "there".' },
    { sec: 'Trật tự từ', lvl: 'NC', name: 'Câu 8', pts: 1, text: 'Choose the sentence with the correct word order.', opts: o4('How much does cost this dictionary?', 'How much does this dictionary cost?', 'How much this dictionary costs?', 'How much cost this dictionary?'), ans: 'B', why: 'Trật tự chuẩn là <i>How much + does + chủ ngữ + động từ nguyên thể?</i>. Bẫy ở A: học sinh đưa động từ chính lên ngay sau trợ động từ theo thói quen tiếng Việt; bẫy ở C: quên hẳn trợ động từ "does".' },
    { sec: 'Chỉ đường', lvl: 'NB', name: 'Câu 9', pts: 1, text: 'Turn right at the corner. The bank is ___ your left.', opts: o4('on', 'in', 'at', 'to'), ans: 'A', why: 'Cụm cố định chỉ phía bên là <i>on your left / on your right</i>.' },
    { sec: 'Mua sắm', lvl: 'TH', name: 'Câu 10', pts: 1, text: '— "What size do you wear?" — "___"', opts: o4('It\'s too big.', '200000 dong.', 'Size M, please.', 'Yes, I do.'), ans: 'C', why: 'Câu hỏi về cỡ quần áo nên trả lời bằng cỡ: <i>Size M</i>. Phương án B là câu trả lời cho "How much…?".' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 11', pts: 1, text: 'A school bag costs 95000 dong and a pencil case costs 35000 dong. Minh buys one school bag and two pencil cases, and he gives the shop assistant 200000 dong. How much change does he get?', opts: o4('70000 dong', '105000 dong', '30000 dong', '35000 dong'), ans: 'D', why: 'Minh phải trả 95000 + 2 × 35000 = 165000 đồng, nên tiền thừa là 200000 − 165000 = <b>35000 đồng</b>. Bẫy ở A: học sinh chỉ tính một hộp bút (200000 − 130000 = 70000); bẫy ở B: quên luôn hộp bút và chỉ trừ tiền cặp sách.' },
    { sec: 'Chỉ đường', lvl: 'TH', name: 'Câu 12', pts: 1, text: '— "Excuse me, where is the nearest bus stop?" — "It\'s ___ the bookshop and the bakery."', opts: o4('next', 'between', 'opposite to', 'in front'), ans: 'B', why: 'Có hai địa điểm ở hai bên nên dùng <i>between … and …</i>. "Next" và "in front" thiếu giới từ "to/of", còn "opposite" không đi với "to".' },
    { sec: 'Mua sắm', lvl: 'NB', name: 'Câu 13', pts: 1, text: '— "Here is your change." — "___"', opts: o4('Thank you.', 'Yes, please.', 'Not at all.', 'How much?'), ans: 'A', why: 'Khi người bán trả lại tiền thừa, ta nói <i>Thank you</i>.' },
    { sec: 'Gợi ý', lvl: 'NC', name: 'Câu 14', pts: 1, text: 'Which answer shows that the speaker REFUSES a suggestion politely?', opts: o4('Yes, let\'s go now.', 'That\'s a great idea!', 'OK, why not?', 'Sorry, I\'m too tired today.'), ans: 'D', why: 'Chỉ câu D nói lời xin lỗi kèm lí do — đó là cách từ chối lịch sự. Bẫy ở C: "why not?" có chữ "not" khiến học sinh tưởng là phủ định, nhưng thực ra đây là cách ĐỒNG Ý rất thoải mái.' },
    { sec: 'Hỏi đường', lvl: 'NC', name: 'Câu 15', pts: 1, text: 'Read the directions: "Go straight along Le Loi Street. Take the second turning on the right. The library is on your left, next to the museum." Where is the library?', opts: o4('On Le Loi Street, next to the museum.', 'On the first street on the right.', 'On the second street on the right, next to the museum.', 'Opposite the museum on Le Loi Street.'), ans: 'C', why: 'Người nghe phải rẽ vào con đường thứ HAI bên phải rồi mới thấy thư viện. Bẫy ở A: thư viện không còn nằm trên phố Lê Lợi nữa sau khi rẽ; bẫy ở D: bài nói thư viện ở CẠNH bảo tàng chứ không đối diện.' },
    { sec: 'Mua sắm', lvl: 'TH', name: 'Câu 16', pts: 1, text: '— "Anything else?" — "___"', opts: o4('Yes, I am.', 'No, thanks. That\'s all.', 'Yes, please help me.', 'It\'s very cheap.'), ans: 'B', why: 'Người bán hỏi khách có mua thêm gì không; khách đáp <i>No, thanks. That\'s all.</i> nếu đã mua đủ.' },
    { sec: 'Địa điểm', lvl: 'NB', name: 'Câu 17', pts: 1, text: 'You can send a letter at the ___.', opts: o4('bakery', 'stadium', 'museum', 'post office'), ans: 'D', why: '<i>Post office</i> là bưu điện — nơi gửi thư và bưu phẩm.' },
    { sec: 'Gợi ý', lvl: 'TH', name: 'Câu 18', pts: 1, text: '— "Let\'s take a taxi to the airport." — "___ It\'s too expensive."', opts: o4('I don\'t think so.', 'That\'s a good idea.', 'Yes, let\'s.', 'OK, I agree.'), ans: 'A', why: 'Vế sau nêu lí do phản đối (quá đắt) nên câu trước phải là lời không tán thành: <i>I don\'t think so.</i>' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 19', pts: 1, text: 'Choose the underlined part that needs correction: Could you <u>tell</u> me <u>how</u> <u>can I get</u> <u>to</u> the market?', opts: o4('tell', 'how', 'can I get', 'to'), ans: 'C', why: 'Trong câu hỏi gián tiếp, phần sau "how" giữ trật tự câu kể: <i>how I can get</i>. Bẫy ở D: học sinh tưởng phải bỏ "to", nhưng cụm <i>get to + nơi chốn</i> là đúng.' },
    { sec: 'Phương tiện', lvl: 'NB', name: 'Câu 20', pts: 1, text: '— "How do I get to the zoo?" — "You can go ___ bus number 5."', opts: o4('on', 'by', 'in', 'with'), ans: 'B', why: 'Nói về phương tiện đi lại ta dùng <i>by</i>: <i>by bus, by bike, by train</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'VD', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>Yesterday my mother and I went shopping at the new supermarket on Quang Trung Street. It takes us only ten minutes <b>(21)___</b> there on foot. The supermarket has three floors. Fruit and vegetables are on the ground floor, clothes are on the first floor, and there is a small food court <b>(22)___</b> the top floor. The first pair of shoes my mother liked was <b>(23)___</b> expensive, so she asked the shop assistant for a cheaper pair. After that we <b>(24)___</b> some noodles at the food court. I was tired <b>(25)___</b> happy when we came home.<br><br><b>Câu 21.</b> It takes us only ten minutes <b>(21)___</b> there on foot.', opts: o4('to walk', 'walking', 'walk', 'walked'), ans: 'A', why: 'Cấu trúc cố định là <i>It takes somebody + thời gian + to + động từ nguyên thể</i>. Bẫy ở B: học sinh nhớ mẫu "spend time doing something" rồi áp dụng nhầm cho "It takes…".' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> … and there is a small food court <b>(22)___</b> the top floor.', opts: o4('in', 'at', 'on', 'to'), ans: 'C', why: 'Với tầng của một toà nhà ta luôn dùng <i>on</i>: <i>on the top floor</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> The first pair of shoes my mother liked was <b>(23)___</b> expensive, so she asked for a cheaper pair.', opts: o4('very few', 'too much', 'enough', 'too'), ans: 'D', why: 'Trước một tính từ ta dùng <i>too</i> để chỉ mức quá đáng: <i>too expensive</i>. "Too much" chỉ đứng trước danh từ không đếm được.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> After that we <b>(24)___</b> some noodles at the food court.', opts: o4('had', 'took', 'made', 'did'), ans: 'A', why: '<i>Have + món ăn</i> nghĩa là ăn món đó; ở quá khứ là <i>had</i>. Bẫy ở B: học sinh dịch "lấy/gọi một tô mì" nên chọn <i>took</i>; bẫy ở C: <i>made</i> nghĩa là tự nấu, không hợp với việc ăn ở khu ẩm thực.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> I was tired <b>(25)___</b> happy when we came home.', opts: o4('and', 'but', 'so', 'because'), ans: 'B', why: 'Mệt và vui là hai cảm giác trái chiều nên nối bằng <i>but</i>. Bẫy ở A: chọn <i>and</i> là bỏ qua quan hệ tương phản giữa hai tính từ.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>Bright Star Bookshop is on Nguyen Trai Street, opposite the city library. It opens at 8.00 every day and closes at 20.00, but on Sundays it closes at 17.00. The shop has two floors. On the ground floor you can find dictionaries, textbooks and notebooks. On the first floor there are story books, maps and a small coffee corner. In that corner you can read a book and drink tea. This month the shop has a special offer: if you buy three notebooks, you pay only for two. Students with a student card get 10% off all books. Mr Quang, the owner, says that Saturday evening is the busiest time of the week.<br><br><b>Câu 26.</b> What time does the bookshop close on Sundays?', opts: o4('At 8.00.', 'At 20.00.', 'At 18.00.', 'At 17.00.'), ans: 'D', why: 'Bài đọc: "on Sundays it closes at 17.00"; 20.00 là giờ đóng cửa của các ngày khác.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> Mai buys three notebooks this month. Each notebook costs 15000 dong. How much does she pay?', opts: o4('45000 dong', '15000 dong', '30000 dong', '40000 dong'), ans: 'C', why: 'Mua ba quyển chỉ trả tiền hai quyển: 2 × 15000 = <b>30000 đồng</b>. Bẫy ở A: học sinh nhân thẳng 3 × 15000 mà quên chương trình khuyến mãi của tháng này.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> Where can you find dictionaries?', opts: o4('On the ground floor.', 'On the first floor.', 'In the coffee corner.', 'In the city library.'), ans: 'A', why: 'Bài đọc: "On the ground floor you can find dictionaries, textbooks and notebooks."' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> Which statement is NOT true about Bright Star Bookshop?', opts: o4('It is opposite the city library.', 'It opens later on Sundays.', 'Students with a student card pay less.', 'It sells both maps and textbooks.'), ans: 'B', why: 'Cửa hàng mở cửa lúc 8.00 TẤT CẢ các ngày, chủ nhật chỉ khác ở giờ ĐÓNG cửa. Bẫy ở B là học sinh đọc thấy "on Sundays" khác biệt rồi vội cho rằng cả giờ mở lẫn giờ đóng đều khác.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 30', pts: 1, text: '<b>Câu 30.</b> What can you do in the coffee corner?', opts: o4('Buy dictionaries.', 'Meet Mr Quang.', 'Read a book and drink tea.', 'Borrow story books.'), ans: 'C', why: 'Bài đọc: "In that corner you can read a book and drink tea."' },
  ],
},
/* ═══════════ ĐỀ 27 — READING: MIÊU TẢ NGƯỜI VÀ NƠI CHỐN ═══════════ */
{
  id: 10727, title: 'Đề 27 · Reading — miêu tả người và nơi chốn, tìm thông tin chi tiết', time: 60,
  questions: [
    { sec: 'Miêu tả ngoại hình', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'My best friend has long black ___ and big brown eyes.', opts: o4('hairs', 'hair', 'head', 'face'), ans: 'B', why: '<i>Hair</i> khi chỉ tóc trên đầu là danh từ không đếm được nên không thêm -s.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 2', pts: 1, text: 'Read: "Nam is 1.55 metres tall. His brother Hung is 8 centimetres taller than Nam, and their cousin Bao is 3 centimetres shorter than Hung." How tall is Bao?', opts: o4('1.60 m', '1.63 m', '1.52 m', '1.58 m'), ans: 'A', why: 'Hùng cao 1,55 + 0,08 = 1,63 m; Bảo thấp hơn Hùng 3 cm nên cao 1,63 − 0,03 = <b>1,60 m</b>. Bẫy ở D: học sinh trừ 3 cm từ chiều cao của Nam thay vì của Hùng.' },
    { sec: 'Tính cách', lvl: 'TH', name: 'Câu 3', pts: 1, text: 'Which word describes a person\'s CHARACTER, not their appearance?', opts: o4('tall', 'slim', 'curly', 'generous'), ans: 'D', why: '<i>Generous</i> (rộng lượng) nói về tính cách; <i>tall, slim, curly</i> đều miêu tả hình dáng bên ngoài.' },
    { sec: 'Suy luận', lvl: 'NC', name: 'Câu 4', pts: 1, text: 'Read: "Mai is not as tall as Lan, but she is taller than Hoa." Who is the shortest of the three?', opts: o4('Mai', 'Lan', 'Hoa', 'We cannot know.'), ans: 'C', why: 'Lan cao nhất, Mai ở giữa, nên <i>Hoa</i> thấp nhất. Bẫy ở A: cụm "not as tall as Lan" khiến học sinh vội kết luận Mai thấp nhất mà bỏ qua vế sau "taller than Hoa".' },
    { sec: 'Trật tự tính từ', lvl: 'NC', name: 'Câu 5', pts: 1, text: 'Which sentence has the correct order of adjectives?', opts: o4('She has black long straight hair.', 'She has long straight black hair.', 'She has straight black long hair.', 'She has black straight long hair.'), ans: 'B', why: 'Trật tự chuẩn là độ dài → kiểu dáng → màu sắc: <i>long straight black hair</i>. Bẫy ở A và D: học sinh quen nói màu tóc trước như tiếng Việt ("tóc đen dài").' },
    { sec: 'Miêu tả ngoại hình', lvl: 'NB', name: 'Câu 6', pts: 1, text: 'My sister wears ___ because she cannot see the board clearly.', opts: o4('a hat', 'a scarf', 'gloves', 'glasses'), ans: 'D', why: '<i>Glasses</i> là kính mắt — thứ người nhìn kém phải đeo.' },
    { sec: 'Câu hỏi miêu tả', lvl: 'TH', name: 'Câu 7', pts: 1, text: '— "What does your new teacher look like?" — "___"', opts: o4('She is tall and has short hair.', 'She is very kind and patient.', 'She teaches English.', 'She likes reading books.'), ans: 'A', why: '<i>What does she look like?</i> hỏi về NGOẠI HÌNH. Phương án B trả lời cho câu hỏi "What is she like?" (tính cách) — đây là cặp câu hỏi học sinh nhầm nhiều nhất.' },
    { sec: 'Nơi chốn', lvl: 'NB', name: 'Câu 8', pts: 1, text: 'Ha Long Bay is in ___ Viet Nam.', opts: o4('southern', 'central', 'northern', 'western'), ans: 'C', why: 'Vịnh Hạ Long thuộc tỉnh Quảng Ninh ở miền Bắc — <i>northern Viet Nam</i>.' },
    { sec: 'Giới từ', lvl: 'TH', name: 'Câu 9', pts: 1, text: 'There are tall green trees ___ both sides of the road.', opts: o4('in', 'at', 'by', 'on'), ans: 'D', why: 'Cụm cố định là <i>on both sides of…</i> (ở hai bên của…).' },
    { sec: 'Suy luận', lvl: 'NC', name: 'Câu 10', pts: 1, text: 'Read: "Our new house is smaller than our old one, but it has a bigger garden." Which sentence is TRUE?', opts: o4('The old house has a smaller garden.', 'The new house is bigger than the old one.', 'The old house has no garden.', 'The two houses have the same garden.'), ans: 'A', why: 'Nhà mới có vườn RỘNG HƠN, vậy vườn nhà cũ nhỏ hơn. Bẫy ở C: "smaller" và "bigger" chỉ so sánh kích thước chứ không nói nhà cũ không có vườn.' },
    { sec: 'Tính cách', lvl: 'NB', name: 'Câu 11', pts: 1, text: 'Nam always helps his classmates with their homework. He is very ___.', opts: o4('lazy', 'kind', 'shy', 'clever'), ans: 'B', why: 'Luôn sẵn lòng giúp người khác là biểu hiện của sự tốt bụng — <i>kind</i>.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 12', pts: 1, text: 'A square park has four gates, one at each corner. The distance around the park is 1200 metres. How far is it from one gate to the next?', opts: o4('200 m', '400 m', '300 m', '600 m'), ans: 'C', why: 'Bốn cổng chia chu vi thành 4 phần bằng nhau: 1200 : 4 = <b>300 m</b>. Bẫy ở B: học sinh nghĩ bốn cổng chỉ tạo ra ba khoảng nên chia cho 3.' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 13', pts: 1, text: 'Choose the underlined part that needs correction: My cousin <u>have</u> a <u>round</u> face, <u>big</u> eyes and a <u>small</u> nose.', opts: o4('have', 'round', 'big', 'small'), ans: 'A', why: 'Chủ ngữ "My cousin" là số ít nên phải dùng <i>has</i>. Bẫy là học sinh thấy phía sau liệt kê nhiều bộ phận (face, eyes, nose) nên tưởng phải dùng động từ số nhiều.' },
    { sec: 'Từ trái nghĩa', lvl: 'TH', name: 'Câu 14', pts: 1, text: 'Which word is the OPPOSITE of <i>narrow</i>?', opts: o4('long', 'wide', 'short', 'high'), ans: 'B', why: '<i>Narrow</i> (hẹp) trái nghĩa với <i>wide</i> (rộng); <i>long – short</i> mới là cặp dài – ngắn.' },
    { sec: 'Nghề nghiệp', lvl: 'NB', name: 'Câu 15', pts: 1, text: 'My mother is a nurse. She works in a ___.', opts: o4('school', 'factory', 'museum', 'hospital'), ans: 'D', why: 'Y tá làm việc ở bệnh viện — <i>hospital</i>.' },
    { sec: 'Miêu tả người', lvl: 'TH', name: 'Câu 16', pts: 1, text: 'Which sentence describes the father correctly?', opts: o4('My father is a tall man with a beard black.', 'My father is a black beard tall man.', 'My father is a tall man with a black beard.', 'My father with a black beard is tall man.'), ans: 'C', why: 'Tính từ đứng trước danh từ (<i>a black beard</i>) và ta dùng <i>with</i> để thêm chi tiết ngoại hình.' },
    { sec: 'Suy luận', lvl: 'NC', name: 'Câu 17', pts: 1, text: 'Read: "In the photo, Nam is standing on the left of Mai. Lan is standing on the right of Mai. Hoa is standing on the right of Lan." Who is standing at the far right?', opts: o4('Hoa', 'Nam', 'Mai', 'Lan'), ans: 'A', why: 'Thứ tự từ trái sang phải là Nam – Mai – Lan – Hoa, nên ngoài cùng bên phải là <i>Hoa</i>. Bẫy ở B: học sinh đọc "Nam is on the left of Mai" rồi hiểu ngược thành Nam đứng phía phải.' },
    { sec: 'Đoán nghĩa từ', lvl: 'TH', name: 'Câu 18', pts: 1, text: 'The word <i>quiet</i> in the phrase "a quiet street" means ___.', opts: o4('with many shops', 'very long', 'with tall trees', 'with little noise'), ans: 'D', why: '<i>Quiet</i> nghĩa là yên tĩnh — ít tiếng ồn.' },
    { sec: 'Nơi chốn', lvl: 'NB', name: 'Câu 19', pts: 1, text: 'Sa Pa is famous for its beautiful ___ and cool weather all year round.', opts: o4('beaches', 'mountains', 'deserts', 'bridges'), ans: 'B', why: 'Sa Pa nổi tiếng với núi non và ruộng bậc thang — <i>mountains</i>.' },
    { sec: 'Nhóm từ', lvl: 'TH', name: 'Câu 20', pts: 1, text: 'Which word does NOT describe a place?', opts: o4('crowded', 'peaceful', 'talkative', 'modern'), ans: 'C', why: '<i>Talkative</i> (hay nói) chỉ dùng cho người; <i>crowded, peaceful, modern</i> đều có thể miêu tả một nơi chốn.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>My grandmother lives in a small village in Nam Dinh. She is seventy years old, <b>(21)___</b> she is still very strong. She has short grey hair and a kind face. Every morning she works in her garden and grows vegetables and flowers. In the afternoon she often sits under the old tree <b>(22)___</b> the house and tells stories to the children in the village. Everyone in the village <b>(23)___</b> her because she is generous and helpful. Her house is <b>(24)___</b> than mine, but it is always clean and full of sunlight. I visit her <b>(25)___</b> month.<br><br><b>Câu 21.</b> She is seventy years old, <b>(21)___</b> she is still very strong.', opts: o4('so', 'and', 'because', 'but'), ans: 'D', why: 'Bảy mươi tuổi mà vẫn khoẻ mạnh là hai ý trái chiều, nên dùng <i>but</i>. Bẫy ở A: <i>so</i> biến vế sau thành kết quả, thành ra "vì bà bảy mươi tuổi nên bà khoẻ" — vô lí.' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> In the afternoon she often sits under the old tree <b>(22)___</b> the house and tells stories to the children.', opts: o4('on', 'in front of', 'between', 'under'), ans: 'B', why: 'Cây cổ thụ ở phía trước ngôi nhà nên dùng <i>in front of</i>. Bẫy ở D: từ "under" đã xuất hiện ngay trước đó ("under the old tree") nên học sinh chọn lại theo quán tính; bẫy ở C: <i>between</i> đòi hỏi phải có hai vật.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> Everyone in the village <b>(23)___</b> her because she is generous and helpful.', opts: o4('loves', 'love', 'loving', 'is love'), ans: 'A', why: '<i>Everyone</i> luôn được coi là số ít nên động từ thêm -s: <i>loves</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> Her house is <b>(24)___</b> than mine, but it is always clean and full of sunlight.', opts: o4('small', 'the smallest', 'smaller', 'more small'), ans: 'C', why: 'Có "than" nên dùng so sánh hơn của tính từ ngắn: <i>smaller</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> I visit her <b>(25)___</b> month.', opts: o4('a', 'every', 'all', 'in'), ans: 'B', why: '<i>Every month</i> nghĩa là hằng tháng; "all month" nghĩa là suốt cả tháng, khác hẳn.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>Cat Ba is the largest island in Ha Long Bay. About 13000 people live there. The island has high mountains, green forests and many small beaches with white sand. In the middle of the island there is a national park. Visitors can walk in the forest, see rare animals and climb to the top of a hill to look at the bay. The main town is small and quiet in winter, but in summer it is very crowded because thousands of tourists come here. Most people on the island are fishermen; they go out to sea at 5.00 in the morning and come back at noon. The local fish market opens at 12.30 every day.<br><br><b>Câu 26.</b> Why is the main town crowded in summer?', opts: o4('Because a lot of tourists visit the island.', 'Because many people live on the island.', 'Because the fish market opens at noon.', 'Because the national park is in the town.'), ans: 'A', why: 'Bài đọc: "in summer it is very crowded because thousands of tourists come here". Bẫy ở D: vườn quốc gia nằm ở GIỮA ĐẢO chứ không nằm trong thị trấn, nên không phải lí do khiến thị trấn đông.' },
    { sec: 'Đọc hiểu', lvl: 'TH', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> What do most people on Cat Ba do for a living?', opts: o4('They work in the national park.', 'They work in hotels.', 'They sell white sand.', 'They catch fish.'), ans: 'D', why: 'Bài đọc: "Most people on the island are fishermen" — họ đi biển đánh cá.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> How many hours do the fishermen spend at sea each day?', opts: o4('5 hours', '7 hours', '6 hours', '12 hours'), ans: 'B', why: 'Họ ra khơi lúc 5.00 và về lúc 12.00 trưa: 12 − 5 = <b>7 tiếng</b>. Bẫy ở D: học sinh lấy luôn con số 12 trong chữ "noon" làm đáp án.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> Where is Cat Ba Island?', opts: o4('In Da Nang.', 'In Nha Trang.', 'In Ha Long Bay.', 'In Phu Quoc.'), ans: 'C', why: 'Câu đầu bài đọc: "Cat Ba is the largest island in Ha Long Bay."' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 30', pts: 1, text: '<b>Câu 30.</b> Which statement is NOT true about Cat Ba?', opts: o4('The island has no forests.', 'The island has a national park.', 'There are small beaches on the island.', 'The town is quiet in winter.'), ans: 'A', why: 'Bài đọc nói rõ đảo có "green forests". Bẫy là câu A rất ngắn nên học sinh đọc lướt qua và mặc định câu ngắn thì đúng, trong khi ba câu dài hơn đều khớp với bài.' },
  ],
},
/* ═══════════ ĐỀ 28 — READING: THÓI QUEN VÀ HOẠT ĐỘNG HẰNG NGÀY ═══════════ */
{
  id: 10728, title: 'Đề 28 · Reading — thói quen và hoạt động hằng ngày, suy luận đơn giản', time: 60,
  questions: [
    { sec: 'Thói quen', lvl: 'NB', name: 'Câu 1', pts: 1, text: 'My father usually gets ___ at half past five in the morning.', opts: o4('up', 'on', 'in', 'off'), ans: 'A', why: 'Cụm động từ chỉ việc thức dậy là <i>get up</i>.' },
    { sec: 'Suy luận thời gian', lvl: 'NC', name: 'Câu 2', pts: 1, text: 'Read: "Lan gets up at 6.00. She has breakfast 30 minutes later and leaves home 15 minutes after breakfast." What time does Lan leave home?', opts: o4('6.30', '6.15', '7.00', '6.45'), ans: 'D', why: 'Lan ăn sáng lúc 6.30, rồi 15 phút sau mới rời nhà → <b>6.45</b>. Bẫy ở A: học sinh dừng lại ở mốc ăn sáng mà quên cộng thêm 15 phút.' },
    { sec: 'Hỏi giờ', lvl: 'TH', name: 'Câu 3', pts: 1, text: '— "What time do you usually have lunch?" — "___"', opts: o4('For an hour.', 'In the kitchen.', 'At half past eleven.', 'Twice a day.'), ans: 'C', why: '<i>What time…?</i> hỏi mốc giờ nên trả lời bằng "At + giờ"; phương án A trả lời cho "How long…?", D trả lời cho "How often…?".' },
    { sec: 'Hoạt động', lvl: 'NB', name: 'Câu 4', pts: 1, text: 'After school, I often ___ my bike in the park with my friends.', opts: o4('drive', 'ride', 'play', 'take'), ans: 'B', why: 'Với xe đạp, xe máy hay ngựa ta dùng động từ <i>ride</i>; <i>drive</i> dùng cho ô tô.' },
    { sec: 'Cụm từ', lvl: 'TH', name: 'Câu 5', pts: 1, text: 'My mother ___ the housework every morning before she goes to work.', opts: o4('does', 'makes', 'takes', 'plays'), ans: 'A', why: 'Cụm cố định là <i>do the housework</i> (làm việc nhà); "make" chỉ việc tạo ra sản phẩm.' },
    { sec: 'Thì hiện tại', lvl: 'NC', name: 'Câu 6', pts: 1, text: 'Which sentence describes a DAILY HABIT, not an action happening now?', opts: o4('Look! The children are playing in the yard.', 'My sister is doing her homework at the moment.', 'My father reads the newspaper every morning.', 'We are having dinner now.'), ans: 'C', why: 'Thói quen hằng ngày dùng hiện tại đơn kèm trạng ngữ "every morning". Bẫy ở B: học sinh thấy "doing her homework" là việc quen làm mỗi ngày nên chọn, nhưng cụm "at the moment" cho biết việc đang diễn ra ngay lúc nói.' },
    { sec: 'Thói quen', lvl: 'NB', name: 'Câu 7', pts: 1, text: 'I brush my ___ twice a day, after breakfast and before bedtime.', opts: o4('hair', 'hands', 'face', 'teeth'), ans: 'D', why: '<i>Brush one\'s teeth</i> là đánh răng — việc làm sau bữa sáng và trước khi đi ngủ.' },
    { sec: 'Hiện tại đơn', lvl: 'TH', name: 'Câu 8', pts: 1, text: 'She ___ to bed early because she has to get up at five.', opts: o4('go', 'goes', 'going', 'is go'), ans: 'B', why: 'Chủ ngữ "She" là ngôi thứ ba số ít nên động từ thêm -es: <i>goes</i>.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 9', pts: 1, text: 'Hoa spends 45 minutes on her homework every evening from Monday to Friday. How much time does she spend on homework in one week?', opts: o4('3 hours', '4 hours', '3 hours and 45 minutes', '4 hours and 15 minutes'), ans: 'C', why: '45 × 5 = 225 phút = <b>3 giờ 45 phút</b>. Bẫy ở A: học sinh chỉ tính bốn ngày (45 × 4 = 180 phút = 3 giờ) vì quên rằng từ thứ Hai đến thứ Sáu là năm ngày.' },
    { sec: 'Câu hỏi tần suất', lvl: 'TH', name: 'Câu 10', pts: 1, text: '___ does your brother go swimming? — Every Sunday.', opts: o4('How often', 'How long', 'What time', 'How many'), ans: 'A', why: 'Câu trả lời "Every Sunday" nói về tần suất nên hỏi bằng <i>How often</i>.' },
    { sec: 'Sửa lỗi sai', lvl: 'NC', name: 'Câu 11', pts: 1, text: 'Choose the underlined part that needs correction: My brother <u>usually</u> <u>get up</u> at six, <u>but</u> today he <u>got up</u> at seven.', opts: o4('usually', 'get up', 'but', 'got up'), ans: 'B', why: 'Chủ ngữ "My brother" là số ít nên phải là <i>gets up</i>. Bẫy ở D: học sinh thấy hai dạng "get up" và "got up" khác nhau rồi cho rằng dạng quá khứ mới là lỗi, trong khi "today he got up at seven" hoàn toàn hợp lí.' },
    { sec: 'Ghép câu hỏi', lvl: 'NC', name: 'Câu 12', pts: 1, text: 'Which question can be answered with "For about two hours"?', opts: o4('What time do you do your homework?', 'How often do you do your homework?', 'When do you do your homework?', 'How long do you do your homework every evening?'), ans: 'D', why: 'Câu trả lời bắt đầu bằng "For…" chỉ THỜI LƯỢNG nên câu hỏi phải là <i>How long…?</i>. Bẫy ở B: <i>How often</i> hỏi tần suất, câu trả lời sẽ là "every evening" chứ không phải "for two hours".' },
    { sec: 'Bữa ăn', lvl: 'NB', name: 'Câu 13', pts: 1, text: 'On Sunday mornings my family often ___ breakfast together.', opts: o4('does', 'makes', 'has', 'takes'), ans: 'C', why: 'Với các bữa ăn ta dùng <i>have</i>: <i>have breakfast / lunch / dinner</i>.' },
    { sec: 'Nhận diện thì', lvl: 'TH', name: 'Câu 14', pts: 1, text: 'Which sentence is in the present simple?', opts: o4('They are watching a film.', 'They watch a film every Saturday.', 'They watched a film yesterday.', 'They will watch a film tonight.'), ans: 'B', why: 'Hiện tại đơn dùng động từ nguyên thể kèm trạng ngữ tần suất "every Saturday".' },
    { sec: 'Liên từ thời gian', lvl: 'NB', name: 'Câu 15', pts: 1, text: 'I have a shower ___ I get up in the morning.', opts: o4('after', 'so', 'but', 'because'), ans: 'A', why: 'Tắm diễn ra SAU khi ngủ dậy nên dùng <i>after</i>.' },
    { sec: 'Suy luận thời gian', lvl: 'NC', name: 'Câu 16', pts: 1, text: 'Read: "Nam gets up at 5.30 and goes jogging for half an hour. Then he has a shower and has breakfast at 6.30." What does Nam do between 6.00 and 6.30?', opts: o4('He goes jogging.', 'He has breakfast.', 'He gets up.', 'He has a shower.'), ans: 'D', why: 'Nam chạy bộ từ 5.30 đến 6.00, ăn sáng lúc 6.30, nên khoảng giữa là lúc đi tắm. Bẫy ở A: học sinh quên cộng "half an hour" nên tưởng 6.00 mới là lúc bắt đầu chạy.' },
    { sec: 'Giới từ', lvl: 'TH', name: 'Câu 17', pts: 1, text: 'My parents work ___ 8 a.m. ___ 5 p.m. every day.', opts: o4('in – at', 'from – to', 'at – to', 'between – to'), ans: 'B', why: 'Khoảng thời gian có mốc đầu và mốc cuối dùng cặp <i>from … to …</i>.' },
    { sec: 'Vận dụng thực tế', lvl: 'VD', name: 'Câu 18', pts: 1, text: 'A school bus picks up students at 6.30 and arrives at school at 7.05. On Monday it started 10 minutes late but still arrived on time. How long did the trip take on Monday?', opts: o4('35 minutes', '45 minutes', '25 minutes', '15 minutes'), ans: 'C', why: 'Xe khởi hành lúc 6.40 và tới trường lúc 7.05 → <b>25 phút</b>. Bẫy ở A: 35 phút là thời gian của những ngày bình thường, học sinh quên trừ 10 phút xuất phát muộn.' },
    { sec: 'Câu hỏi Yes/No', lvl: 'TH', name: 'Câu 19', pts: 1, text: '— "Do you often stay up late?" — "___"', opts: o4('No, I don\'t. I go to bed at ten.', 'Yes, I am.', 'No, I am not.', 'Yes, I did.'), ans: 'A', why: 'Câu hỏi với trợ động từ "Do" phải được đáp bằng "Yes, I do" hoặc "No, I don\'t".' },
    { sec: 'Cụm từ', lvl: 'NB', name: 'Câu 20', pts: 1, text: 'In the evening, my grandparents often ___ a walk around the lake.', opts: o4('do', 'make', 'play', 'take'), ans: 'D', why: 'Cụm cố định là <i>take a walk</i> (đi dạo).' },
    { sec: 'Điền từ (cloze)', lvl: 'NC', name: 'Câu 21', pts: 1, text: '<i>Read and choose the best word for each blank (Câu 21–25).</i><br>My uncle is a baker in a small town. His day starts very early: he gets up at three o\'clock in the morning <b>(21)___</b> the bread must be ready at six. He works in the bakery for about five hours and then has a big breakfast with my aunt. In the afternoon he usually <b>(22)___</b> for two hours because he is tired. He seldom watches TV in the evening; he prefers <b>(23)___</b> books. At weekends the bakery is even busier: it takes him three hours <b>(24)___</b> all the bread for Sunday morning. He says he loves his job because the smell of fresh bread makes him <b>(25)___</b>.<br><br><b>Câu 21.</b> He gets up at three o\'clock in the morning <b>(21)___</b> the bread must be ready at six.', opts: o4('so', 'because', 'but', 'although'), ans: 'B', why: 'Bánh phải xong lúc sáu giờ là LÍ DO khiến bác dậy từ ba giờ, nên dùng <i>because</i>. Bẫy ở A: <i>so</i> đảo ngược quan hệ, thành "bác dậy lúc ba giờ nên bánh phải xong lúc sáu giờ".' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 22', pts: 1, text: '<b>Câu 22.</b> In the afternoon he usually <b>(22)___</b> for two hours because he is tired.', opts: o4('sleeps', 'sleep', 'is sleeping', 'slept'), ans: 'A', why: 'Đoạn văn nói về thói quen hằng ngày và chủ ngữ "he" là số ít nên dùng <i>sleeps</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'NB', name: 'Câu 23', pts: 1, text: '<b>Câu 23.</b> He seldom watches TV in the evening; he prefers <b>(23)___</b> books.', opts: o4('read', 'to reading', 'reading', 'reads'), ans: 'C', why: 'Sau <i>prefer</i> ta dùng V-ing khi nói về sở thích chung: <i>prefers reading</i>.' },
    { sec: 'Điền từ (cloze)', lvl: 'VD', name: 'Câu 24', pts: 1, text: '<b>Câu 24.</b> At weekends it takes him three hours <b>(24)___</b> all the bread for Sunday morning.', opts: o4('bake', 'baking', 'for bake', 'to bake'), ans: 'D', why: 'Cấu trúc <i>It takes somebody + thời gian + to + động từ nguyên thể</i>. Bẫy ở B: học sinh nhầm sang mẫu "spend time doing something" nên chọn dạng V-ing.' },
    { sec: 'Điền từ (cloze)', lvl: 'TH', name: 'Câu 25', pts: 1, text: '<b>Câu 25.</b> He loves his job because the smell of fresh bread makes him <b>(25)___</b>.', opts: o4('happily', 'happy', 'happiness', 'more happily'), ans: 'B', why: 'Cấu trúc <i>make + tân ngữ + TÍNH TỪ</i> nên dùng <i>happy</i>, không dùng trạng từ "happily".' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 26', pts: 1, text: '<i>Read the passage and answer the questions (Câu 26–30).</i><br>Mrs Hoa is a nurse at a small clinic in Binh Duong. She works in shifts. In a morning-shift week, she starts work at 6.00 and finishes at 14.00. In a night-shift week, she starts at 22.00 and finishes at 6.00 the next morning. She changes her shift every two weeks. When she works at night, she sleeps from 8.00 to 14.00 in the daytime and cooks dinner for her family in the afternoon. Her husband takes their two children to school every day. On her days off, the whole family often goes to the park or visits her parents in the countryside. Mrs Hoa says the night shift is difficult, but she likes helping people.<br><br><b>Câu 26.</b> Why does Mrs Hoa sleep in the daytime?', opts: o4('Because she is often ill.', 'Because she has no work to do.', 'Because she works at night that week.', 'Because her children are at school.'), ans: 'C', why: 'Bài đọc: "When she works at night, she sleeps from 8.00 to 14.00 in the daytime". Bẫy ở B: bà ngủ ngày không phải vì rảnh rỗi mà vì vừa làm ca đêm xong.' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 27', pts: 1, text: '<b>Câu 27.</b> How many hours does one night shift last?', opts: o4('Eight hours.', 'Six hours.', 'Ten hours.', 'Seven hours.'), ans: 'A', why: 'Từ 22.00 đến 6.00 sáng hôm sau là <b>8 tiếng</b>. Bẫy ở C: học sinh tính tới 8.00 — giờ bà bắt đầu đi ngủ — thay vì giờ tan ca là 6.00.' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 28', pts: 1, text: '<b>Câu 28.</b> Who takes the children to school?', opts: o4('Mrs Hoa.', 'Her parents.', 'Her neighbour.', 'Her husband.'), ans: 'D', why: 'Bài đọc: "Her husband takes their two children to school every day."' },
    { sec: 'Đọc hiểu', lvl: 'NB', name: 'Câu 29', pts: 1, text: '<b>Câu 29.</b> Where does Mrs Hoa work?', opts: o4('In a school.', 'In a factory.', 'In a clinic.', 'In a shop.'), ans: 'C', why: 'Câu đầu bài đọc: "Mrs Hoa is a nurse at a small clinic in Binh Duong."' },
    { sec: 'Đọc hiểu', lvl: 'NC', name: 'Câu 30', pts: 1, text: '<b>Câu 30.</b> Which statement is NOT true about Mrs Hoa?', opts: o4('She changes her shift every two weeks.', 'She works in the morning every day.', 'She cooks dinner for her family.', 'She sometimes visits her parents.'), ans: 'B', why: 'Bà làm việc theo ca và cứ hai tuần lại đổi ca, nên có những tuần bà làm đêm chứ không phải sáng nào cũng đi làm. Bẫy ở B là học sinh chỉ nhớ chi tiết "morning-shift week" mà bỏ qua chữ "in shifts" ở đầu bài.' },
  ],
},
];

